        // Property filters
        filterEffects, setFilterEffects,
        filterCounter, setFilterCounter,
        filterXP, setFilterXP,
        filterVariants, setFilterVariants,

        // Audit mode
        auditMode, setAuditMode,
        duplicateIds,

        // Derived Data
        library,
        processedList,
        allAvailableTags,
        allSkills,
        allAttributes,
        allCounters,
        allFormulas,

        // Handlers
        handleOpenNew,
