        executePublish,
        addTag,
        removeTag,
        addEffect,
        updateEffect,
        updateEffectFields,
        removeEffect
    };
};

import { useState, useCallback } from 'react';
import { LibraryLoader } from '../../services/library/LibraryLoader';
import { ItemUsageDetail } from '../../types/usageTypes';

export type ItemType = 'trait' | 'skill' | 'background' | 'counter' | 'mystic' | 'specialization';

/**
 * Hook to manage loading and caching of item usage details (campaigns/characters)
 */
export function useItemUsageDetails(currentSettingId: string, itemType: ItemType) {
    const [cache] = useState(() => new Map<string, ItemUsageDetail>());
    const [loadingIds, setLoadingIds] = useState<Set<string>>(new Set());

    const loadDetails = useCallback(async (itemId: string) => {
        // Only load if not already in cache and not currently loading
        if (cache.has(itemId) || loadingIds.has(itemId)) return;

        setLoadingIds(prev => {
            const next = new Set(prev);
            next.add(itemId);
            return next;
        });

        try {
            const details = await LibraryLoader.loadItemUsageDetails(itemId, currentSettingId, itemType);
            cache.set(itemId, details);
            // Force a re-render to update components using the cache
            setLoadingIds(prev => {
                const next = new Set(prev);
                next.delete(itemId);
                return next;
            });
        } catch (error) {
            setLoadingIds(prev => {
                const next = new Set(prev);
                next.delete(itemId);
                return next;
            });
        }
    }, [cache, currentSettingId, itemType, loadingIds]);

    return {
        loadDetails,
        usageDetailsCache: cache,
        loadingIds
    };
}

import { useState, useEffect, useCallback } from 'react';
import { CharacterSheetData } from '../../types';
import { RulesData } from '../../types/rules';
import { CampaignService } from '../../services/CampaignService';
import { ErrorService } from '../../services/ErrorService';
import { loadRules } from '../../services/RulesLoader';
import { logger } from '../../utils/logger';
import { INITIAL_DATA } from '../../data/initialState';

export const useRulesSync = (
    data: CharacterSheetData,
    rules: RulesData | null,
    setData: (newData: CharacterSheetData | ((prev: CharacterSheetData) => CharacterSheetData)) => void,
    updateRules: (rules: RulesData) => void,
    addLog: (message: string, type?: 'success' | 'danger' | 'info', category?: 'sheet' | 'settings' | 'both') => void
) => {
    const [isSourceSelected, setIsSourceSelected] = useState<boolean>(() => {
        return sessionStorage.getItem('rpg-source-selected') === 'true';
    });
    const [showConflict, setShowConflict] = useState(false);
    const [pendingRules, setPendingRules] = useState<{ rules: RulesData, id: string, name: string } | null>(null);

    // Initial Source Selection Helper
    const handleSourceSelect = useCallback(async (sourceType: 'online' | 'offline', selectedRules?: RulesData, settingId?: string, settingName?: string) => {
        setIsSourceSelected(true);
        sessionStorage.setItem('rpg-source-selected', 'true');

        if (sourceType === 'online' && selectedRules && settingId) {
            const hasCharacter = data.header?.name?.trim() !== '';
            const isDifferentCampaign = data.syncInfo?.settingId !== settingId;

            if (hasCharacter && isDifferentCampaign) {
                setPendingRules({ rules: selectedRules, id: settingId, name: settingName || 'Nouvelle Campagne' });
                setShowConflict(true);
            } else {
                updateRules({
                    ...selectedRules,
                    settingId,
                    settingName: settingName || (selectedRules.settingName as string)
                });
            }
        } else {
            const fallback = await loadRules();
            if (fallback) updateRules(fallback);
            else alert("Impossible de charger les r├¿gles locales.");
        }
    }, [data, updateRules]);

    // Restore Rules on Refresh if linked to campaign
    useEffect(() => {
        const syncInfo = data?.syncInfo;
        if (!syncInfo?.settingId || !rules || isSourceSelected === false) return;

        if (rules?.settingId !== syncInfo.settingId) {
            logger.log(`[useRulesSync] Rules Mismatch Detected. Restoring ${syncInfo.settingId}...`);
            CampaignService.loadSetting(syncInfo.settingId).then(restoredRules => {
                if (restoredRules) {
                    updateRules({
                        ...restoredRules,
                        settingId: syncInfo.settingId as string,
                        settingName: syncInfo.settingName || 'Inconnue'
                    });
                    addLog(`R├¿gles de la campagne "${syncInfo.settingName}" restaur├®es.`, 'info', 'settings');
                }
            }).catch(err => logger.error("[useRulesSync] Failed to restore rules", err));
        }
    }, [data.syncInfo, rules?.settingId, isSourceSelected, updateRules, addLog]);

    const handleConfirmReset = useCallback(() => {
        if (!pendingRules) return;
        setData(JSON.parse(JSON.stringify(INITIAL_DATA)));
        updateRules({ ...pendingRules.rules, settingId: pendingRules.id, settingName: pendingRules.name });
        setShowConflict(false);
        setPendingRules(null);
        addLog(`Nouvelle campagne charg├®e : ${pendingRules.name}. Fiche r├®initialis├®e.`, 'info', 'settings');
    }, [pendingRules, setData, updateRules, addLog]);

    return {
        isSourceSelected, setIsSourceSelected,
        showConflict, setShowConflict,
        pendingRules, setPendingRules,
        handleSourceSelect,
        handleConfirmReset
    };
};

import { useState, useMemo } from 'react';
import { LibrarySkillEntry, CharacterSheetData } from '../../types';
import { RulesData } from '../../types/rules';
import { mergeLibraries, MergedEntry } from '../../utils/libraryMerger';
import { smartIncludes } from '../../utils/stringUtils';

export const useSkillLibrary = (
    data: CharacterSheetData,
    rules: RulesData | null,
    onUpdate: (newData: CharacterSheetData) => void,
    addLog: (message: string, type?: 'success' | 'danger' | 'info', category?: 'sheet' | 'settings' | 'both') => void
) => {
    const [skillSearch, setSkillSearch] = useState('');
    const [hideKnownSkills, setHideKnownSkills] = useState(true);
    const [isSkillModalOpen, setIsSkillModalOpen] = useState(false);
    const [editingSkill, setEditingSkill] = useState<LibrarySkillEntry | null>(null);
    const [skillError, setSkillError] = useState<string | null>(null);
    const [showRenameConfirm, setShowRenameConfirm] = useState<{ oldName: string, newSkill: LibrarySkillEntry } | null>(null);
    const [showImportConfirm, setShowImportConfirm] = useState(false);
    const [skillToDelete, setSkillToDelete] = useState<LibrarySkillEntry | null>(null);

    const hybridSkills = useMemo(() => {
        const local = data.skillLibrary || [];
        const official = rules?.libraries?.skills || [];
        return mergeLibraries(local, official);
    }, [data.skillLibrary, rules]);

    const usedSkillNames = useMemo(() => {
        const names = new Set<string>();
        if (data.skills) {
            Object.keys(data.skills).forEach(key => {
                const list = data.skills[key] || [];
                list.forEach((s: any) => {
                    if (s.name && s.name.trim() !== '') {
                        names.add(s.name.trim().toLowerCase());
                    }
                });
            });
        }
        return names;
    }, [data.skills]);

    const filteredSkills = useMemo(() => {
        return hybridSkills.filter(m => {
            const matchesSearch = smartIncludes(m.entry.name, skillSearch) ||
                smartIncludes(m.entry.description || '', skillSearch);
            const isKnown = usedSkillNames.has(m.entry.name.trim().toLowerCase());
            const matchesFilter = hideKnownSkills ? !isKnown : true;
            return matchesSearch && matchesFilter;
        }).sort((a, b) => a.entry.name.localeCompare(b.entry.name));
    }, [hybridSkills, skillSearch, hideKnownSkills, usedSkillNames]);

    const handleOpenNewSkill = () => {
        setSkillError(null);
        setEditingSkill({
            id: Math.random().toString(36).substr(2, 9),
            name: '',
            description: ''
        });
        setIsSkillModalOpen(true);
    };

    const handleOpenEditSkill = (merged: MergedEntry<LibrarySkillEntry>) => {
        setSkillError(null);
        setEditingSkill({ ...merged.entry });
        setIsSkillModalOpen(true);
    };

    const finalizeSaveSkill = (skillToSave: LibrarySkillEntry, renameOnSheet: boolean = false) => {
        const localList = data.skillLibrary || [];
        const exists = localList.some(s => s.id === skillToSave.id);

        let newLibrary;
        if (exists) {
            newLibrary = localList.map(s => s.id === skillToSave.id ? skillToSave : s);
        } else {
            newLibrary = [...localList, skillToSave];
        }

        const newData = { ...data, skillLibrary: newLibrary };

        if (renameOnSheet && showRenameConfirm) {
            const oldName = showRenameConfirm.oldName.trim().toLowerCase();
            const newName = skillToSave.name.trim();

            const updatedSkills = { ...data.skills };
            Object.keys(updatedSkills).forEach(cat => {
                if (Array.isArray(updatedSkills[cat])) {
                    updatedSkills[cat] = updatedSkills[cat].map((s: any) =>
                        (s.name && s.name.trim().toLowerCase() === oldName)
                            ? { ...s, name: newName }
                            : s
                    );
                }
            });
            newData.skills = updatedSkills;
        }

        onUpdate(newData);
        addLog(`Comp├®tence "${skillToSave.name}" enregistr├®e dans la r├®serve.`, 'success', 'settings');
        setIsSkillModalOpen(false);
        setEditingSkill(null);
        setShowRenameConfirm(null);
    };

    const handleSaveSkill = (skillToSave: LibrarySkillEntry) => {
        if (!skillToSave.name.trim()) {
            setSkillError("Le nom de la comp├®tence est requis.");
            return;
        }

        const duplicate = hybridSkills.find(m =>
            m.source === 'local' &&
            m.entry.id !== skillToSave.id &&
            m.entry.name.trim().toLowerCase() === skillToSave.name.trim().toLowerCase()
        );

        if (duplicate) {
            setSkillError("Une comp├®tence portant ce nom existe d├®j├á.");
            return;
        }

        const existingMerged = hybridSkills.find(m => m.entry.id === skillToSave.id);
        const existing = existingMerged ? existingMerged.entry : null;
        const nameChanged = existing && existing.name.trim().toLowerCase() !== skillToSave.name.trim().toLowerCase();
        const isUsed = existing && usedSkillNames.has(existing.name.trim().toLowerCase());

        if (nameChanged && isUsed) {
            setShowRenameConfirm({ oldName: existing.name, newSkill: skillToSave });
            setIsSkillModalOpen(false);
            return;
        }

        const cleanedSkill = {
            ...skillToSave,
            variants: skillToSave.variants ? skillToSave.variants.map(v => v.trim()).filter(v => v !== '') : []
        };

        finalizeSaveSkill(cleanedSkill);
    };

    const handleDeleteRequest = (merged: MergedEntry<LibrarySkillEntry>) => {
        if (merged.source === 'official') {
            addLog("Impossible de supprimer une comp├®tence officielle.", "info", "settings");
            return;
        }
        setSkillToDelete(merged.entry);
    };

    const executeDeleteSkill = () => {
        if (!skillToDelete) return;
        const localList = data.skillLibrary || [];
        onUpdate({ ...data, skillLibrary: localList.filter(s => s.id !== skillToDelete.id) });
        addLog(`Comp├®tence "${skillToDelete.name}" supprim├®e de la r├®serve.`, 'info', 'settings');
        setSkillToDelete(null);
    };

    const executeImportFromSheet = () => {
        const currentLib = JSON.parse(JSON.stringify(data.skillLibrary || []));
        const existingNames = new Set(currentLib.map((s: any) => s.name.trim().toLowerCase()));
        let addedCount = 0;

        Object.keys(data.skills).forEach(key => {
            if (key === 'arrieres_plans') return;
            const sheetSkills = data.skills[key] || [];
            sheetSkills.forEach((skill: any) => {
                const normalized = skill.name ? skill.name.trim() : "";
                if (normalized && !existingNames.has(normalized.toLowerCase())) {
                    currentLib.push({
                        id: Math.random().toString(36).substr(2, 9),
                        name: skill.name,
                        description: "",
                        defaultCategory: key
                    });
                    existingNames.add(normalized.toLowerCase());
                    addedCount++;
                }
            });
        });

        if (addedCount > 0) {
            currentLib.sort((a: any, b: any) => a.name.localeCompare(b.name));
            onUpdate({ ...data, skillLibrary: currentLib });
            addLog(`${addedCount} comp├®tence(s) import├®e(s) depuis la fiche.`, 'success', 'settings');
        } else {
            addLog("Toutes les comp├®tences de la fiche sont d├®j├á dans la r├®serve.", 'info', 'settings');
        }
        setShowImportConfirm(false);
    };

    return {
        skillSearch, setSkillSearch,
        hideKnownSkills, setHideKnownSkills,
        isSkillModalOpen, setIsSkillModalOpen,
        editingSkill, setEditingSkill,
        skillError, setSkillError,
        showRenameConfirm, setShowRenameConfirm,
        showImportConfirm, setShowImportConfirm,
        skillToDelete, setSkillToDelete,
        hybridSkills,
        usedSkillNames,
        filteredSkills,
        handleOpenNewSkill,
        handleOpenEditSkill,
        handleSaveSkill,
        finalizeSaveSkill,
        handleDeleteRequest,
        executeDeleteSkill,
        executeImportFromSheet
    };
};

import { useState, useEffect, useCallback } from 'react';
import { CharacterSheetData } from '../../types';
import { getInitialCharacterData, INITIAL_DATA } from '../../data/initialState';
import { applyRulesToState } from '../../utils/rulesAdapter';
import { RulesData } from '../../types/rules';

export const useSettingsManager = (
    initialData: CharacterSheetData,
    rules: RulesData | null,
    isOnlineMode: boolean,
    expertMode: boolean,
    onUpdate: (newData: CharacterSheetData) => void,
    onAddLog: (message: string, type?: 'success' | 'danger' | 'info', category?: 'sheet' | 'settings' | 'both') => void,
    onDirtyChange?: (isDirty: boolean) => void
) => {
    const [localData, setLocalData] = useState<CharacterSheetData>(initialData);
    const [activeTab, setActiveTab] = useState<'general' | 'attributes' | 'skills' | 'specializations' | 'creation' | 'library' | 'cloud' | 'suggestions'>('library');
    const [isDirty, setIsDirty] = useState(false);
    const [showResetConfirm, setShowResetConfirm] = useState(false);
    const [showExpertWarning, setShowExpertWarning] = useState(false);

    // Helper to compare data excluding volatile/computed fields
    const getComparableData = useCallback((d: CharacterSheetData) => {
        const {
            appLogs,
            xpLogs,
            experience,
            syncInfo,
            appVersion,
            _rulesVersion,
            _schemaVersion,
            suggestions,
            ...rest
        } = d;
        return rest;
    }, []);

    // Effect to detect unsaved changes
    useEffect(() => {
        const dirty = JSON.stringify(getComparableData(localData)) !== JSON.stringify(getComparableData(initialData));
        setIsDirty(dirty);
        if (onDirtyChange) {
            onDirtyChange(dirty);
        }
    }, [localData, initialData, onDirtyChange, getComparableData]);

    // Force Tab to Library if entering Online Mode without Expert Mode
    useEffect(() => {
        const advancedTabs = ['attributes', 'skills', 'specializations', 'creation'];
        if (isOnlineMode && !expertMode && advancedTabs.includes(activeTab)) {
            setActiveTab('library');
        }
    }, [isOnlineMode, expertMode, activeTab]);

    const handleSave = useCallback(() => {
        onUpdate(localData);
        onAddLog('Modifications de la structure sauvegard├®es', 'success', 'settings');
    }, [localData, onUpdate, onAddLog]);

    const handleLocalUpdate = useCallback((newData: CharacterSheetData) => {
        setLocalData(newData);
    }, []);

    const performReset = useCallback(() => {
        // Use factory to get fresh IDs
        const base = getInitialCharacterData();
        const newState = rules ? applyRulesToState(base, rules) : base;

        setLocalData(newState);
        onUpdate(newState);
        setShowResetConfirm(false);

        const logMsg = rules
            ? `R├®initialisation compl├¿te (R├¿gles charg├®es : v${rules.version})`
            : "R├®initialisation compl├¿te des donn├®es (R├¿gles par d├®faut)";
        onAddLog(logMsg, 'danger', 'settings');
    }, [rules, onUpdate, onAddLog]);

    const toggleAutoSync = useCallback((enabled: boolean) => {
        if (!localData.syncInfo) return;
        handleLocalUpdate({
            ...localData,
            syncInfo: {
                ...localData.syncInfo,
                isAutoSyncEnabled: enabled
            }
        });
    }, [localData, handleLocalUpdate]);

    return {
        localData,
        activeTab,
        setActiveTab,
        isDirty,
        showResetConfirm,
        setShowResetConfirm,
        showExpertWarning,
        setShowExpertWarning,
        handleSave,
        handleLocalUpdate,
        performReset,
        toggleAutoSync
    };
};

import { useState } from 'react';
import { CharacterSheetData, LibraryEntry, XPTransaction } from '../../types';
import { RulesData } from '../../types/rules';

export const useTraitEditor = (
    data: CharacterSheetData,
    _rules: RulesData | null,
    onChange: (newData: CharacterSheetData) => void,
    onAddLog: (message: string, type?: 'success' | 'danger' | 'info', category?: 'sheet' | 'settings' | 'both', detail?: string) => void,
    recordXPTransaction?: (transaction: Omit<XPTransaction, 'id' | 'timestamp'>) => void,
    onMasterSkillNeeded?: (traitName: string, pendingAdd: () => void) => void
) => {
    const [multiSelectTarget, setMultiSelectTarget] = useState<'avantages' | 'desavantages' | null>(null);

    const removeTrait = (type: 'avantages' | 'desavantages', index: number) => {
        const list = [...data.page2[type]];
        const removedItem = list[index];
        const removedName = removedItem.name;

        // Determine if this trait has a auto_counter effect and an associated counter
        const newCustomCounters = [...data.counters.custom];
        let hasCounterChanges = false;
        const counterIdToRemove = removedItem.associatedCounterId;

        // If not found directly, try via definition
        if (!counterIdToRemove && removedItem.definitionId && _rules?.libraries?.traits) {
            const traitDef = _rules.libraries.traits.find(t => t.id === removedItem.definitionId);
            if (traitDef) {
                const hasNewProperty = traitDef.hasAutoCounter;

                // If it should have a counter but associatedCounterId is missing, this is an edge case
                // usually we rely on associatedCounterId stored on the character's instance.
                if (hasNewProperty) {
                    onAddLog(`Suppression du compteur li├® ├á ${removedName}`, 'info', 'sheet');
                }
            }
        }

        if (counterIdToRemove) {
            const counterIndex = newCustomCounters.findIndex(c => c.id === counterIdToRemove);
            if (counterIndex !== -1) {
                const oldCounter = newCustomCounters[counterIndex];
                newCustomCounters.splice(counterIndex, 1);
                hasCounterChanges = true;
                onAddLog(`Compteur Auto li├® supprim├® : ${oldCounter.name || 'Compteur Auto'}`, 'info', 'sheet');
            }
        }

        // Reset master_skill competence to 0 if applicable
        let newSkills = { ...data.skills };
        let hasSkillChanges = false;
        if (removedItem.masterSkillTarget) {
            const targetSkillName = removedItem.masterSkillTarget;
            for (const catId of Object.keys(newSkills)) {
                const list = newSkills[catId];
                if (!Array.isArray(list)) continue;
                const idx = list.findIndex(s => s.name === targetSkillName);
                if (idx !== -1) {
                    const updated = [...list];
                    updated[idx] = { ...updated[idx], value: 0, creationValue: 0 };
                    newSkills = { ...newSkills, [catId]: updated };
                    hasSkillChanges = true;
                    onAddLog(`Ma├«trise retir├®e : ${targetSkillName} remis ├á 0`, 'info', 'sheet');
                    break;
                }
            }
        }

        // Record refund if it was a paid trait
        if (recordXPTransaction && removedItem.name.trim()) {
            const isPostCreation = removedItem.isPostCreation;
            const points = parseInt(removedItem.value) || 0;
            const traitCostFactor = _rules?.configurations?.xpCosts?.traitCost ?? (data.xpCosts?.traitCost ?? 5);

            if (isPostCreation && points > 0) {
                recordXPTransaction({
                    type: 'refund',
                    description: `Suppression Trait : ${removedName}`,
                    amount: points * traitCostFactor,
                    source: 'XP Libre'
                });
            }
        }

        list[index] = { name: '', value: '', variant: '', description: '', tag: '', definitionId: undefined };
        const newData = {
            ...data,
            page2: { ...data.page2, [type]: list },
            counters: hasCounterChanges ? { ...data.counters, custom: newCustomCounters } : data.counters,
            skills: hasSkillChanges ? newSkills : data.skills
        };
        onChange(newData);
        if (removedName.trim()) {
            onAddLog(`Suppression ${type === 'avantages' ? 'Avantage' : 'D├®savantage'} : ${removedName}`, 'info', 'sheet');
        }
    };

    const handleMultiAdd = (instances: { entry: LibraryEntry; variant?: string; cost?: string }[]) => {
        if (!multiSelectTarget) return;
        const currentList = [...data.page2[multiSelectTarget]];
        let addedCount = 0;
        let totalXPCost = 0;
        let listIndex = 0;
        const isPostCreation = !data.creationConfig?.active;
        const traitCostFactor = _rules?.configurations?.xpCosts?.traitCost ?? (data.xpCosts?.traitCost ?? 5);

        const newCustomCounters = [...data.counters.custom];
        let hasCounterChanges = false;

        // Index of trait entries that need master_skill wizard
        let masterSkillTraitIndex: number | null = null;
        let masterSkillTraitName: string | null = null;

        instances.forEach(instance => {
            const entry = instance.entry;
            const costValue = instance.cost || entry.cost || "";

            while (listIndex < currentList.length && currentList[listIndex].name.trim() !== '') {
                listIndex++;
            }

            if (listIndex < currentList.length) {
                // Helper to resolve effective effect properties from global library
                const resolveEffect = (e: any) => {
                    const res = { ...e };
                    if (e.formulaId && _rules?.libraries?.formulas) {
                        const global = _rules.libraries.formulas.find(f => f.id === e.formulaId);
                        if (global) {
                            if (global.target) res.target = global.target;
                            if (global.effectType) res.effectType = global.effectType;
                        }
                    }
                    return res;
                };

                // Determine if this trait has a auto_counter effect
                let associatedCounterId: string | undefined = undefined;
                const hasNewAutoCounter = entry.hasAutoCounter;
                const counterEffect = entry.effects?.map(resolveEffect).find(e => e.effectType === 'auto_counter');

                if (hasNewAutoCounter || counterEffect) {
                    const baseCounterName = (entry.autoCounterName || counterEffect?.target)?.trim();
                    const variantName = instance.variant?.trim();

                    let finalCounterName: string;
                    if (baseCounterName) {
                        finalCounterName = variantName ? `${baseCounterName} (${variantName})` : baseCounterName;
                    } else {
                        // Fallback to variant or trait name
                        finalCounterName = variantName || entry.name;
                    }

                    associatedCounterId = Math.random().toString(36).substring(2, 9);
                    const newCounter: any = {
                        id: associatedCounterId,
                        name: finalCounterName,
                        value: 0,
                        max: 10,
                        current: 0,
                        creationValue: 0,
                        variant: 'squares_only'
                    };

                    // Find an empty custom counter slot, or append
                    const emptyCounterIndex = newCustomCounters.findIndex(c => c.name.trim() === '');
                    if (emptyCounterIndex !== -1) {
                        newCustomCounters[emptyCounterIndex] = newCounter;
                    } else {
                        newCustomCounters.push(newCounter);
                    }

                    hasCounterChanges = true;
                    onAddLog(`Compteur ajout├® : ${finalCounterName}`, 'info', 'sheet');
                }

                // Detect master_skill effect ÔÇö wizard will fill in masterSkillTarget later
                // Detect master_skill effect ÔÇö wizard will fill in masterSkillTarget later
                const hasMasterSkill = entry.effects?.some(e => {
                    const resolved = resolveEffect(e);
                    return resolved.effectType === 'master_skill';
                });
                if (hasMasterSkill && masterSkillTraitIndex === null) {
                    masterSkillTraitIndex = listIndex;
                    masterSkillTraitName = entry.name;
                }

                currentList[listIndex] = {
                    name: entry.name,
                    value: costValue,
                    description: entry.description || "",
                    tag: entry.tags?.[0] || '',
                    variant: instance.variant || '',
                    definitionId: entry.id,
                    type: multiSelectTarget === 'avantages' ? 'avantage' : 'desavantage',
                    mysticAbilityId: entry.mysticAbilityId || undefined,
                    isPostCreation: isPostCreation ? true : undefined,
                    creationValue: isPostCreation ? "0" : undefined,
                    associatedCounterId: associatedCounterId,
                    hasAutoCounter: entry.hasAutoCounter,
                    autoCounterName: entry.autoCounterName,
                    isXPUpgradeable: entry.isXPUpgradeable
                };

                if (isPostCreation) {
                    const points = parseInt(costValue) || 0;
                    totalXPCost += points * traitCostFactor;
                }
                addedCount++;
            }
        });

        if (addedCount > 0) {
            const newData = {
                ...data,
                page2: { ...data.page2, [multiSelectTarget]: currentList },
                counters: hasCounterChanges ? { ...data.counters, custom: newCustomCounters } : data.counters
            };

            if (isPostCreation && totalXPCost > 0) {
                onAddLog(`Achat de ${addedCount} trait(s) pour ${totalXPCost} XP.`, 'success', 'sheet');

                if (recordXPTransaction) {
                    const descriptions = instances.map(i => i.entry.name).join(', ');
                    recordXPTransaction({
                        type: 'spend',
                        description: `Achat Traits : ${descriptions}`,
                        amount: totalXPCost,
                        source: 'XP Libre'
                    });
                }
            } else {
                onAddLog(`Ajout de ${addedCount} trait(s).`, 'success', 'sheet');
            }

            onChange(newData);

            // Trigger master_skill wizard after state is committed
            if (masterSkillTraitIndex !== null && masterSkillTraitName && onMasterSkillNeeded) {
                const traitIdx = masterSkillTraitIndex;
                const traitType = multiSelectTarget;
                onMasterSkillNeeded(masterSkillTraitName, () => {
                    // This callback is called with the chosen skill from the wizard
                    // It will be replaced by applyMasterSkill in CharacterSheetPage2
                    void traitIdx; void traitType;
                });
            }
        }
        setMultiSelectTarget(null);
    };

    /**
     * Applique la ma├«trise d'une comp├®tence sur la fiche.
     * Appel├® depuis CharacterSheetPage2 apr├¿s confirmation du wizard.
     */
    const applyMasterSkill = (
        currentData: CharacterSheetData,
        traitType: 'avantages' | 'desavantages',
        traitName: string,
        categoryId: string,
        skillName: string
    ): CharacterSheetData => {
        // 1. Mettre la comp├®tence au rang 5 avec creationValue = 5 (gratuit en XP)
        const newSkills = { ...currentData.skills };
        const catList = newSkills[categoryId];
        if (Array.isArray(catList)) {
            const skillIdx = catList.findIndex(s => s.name === skillName);
            if (skillIdx !== -1) {
                const updated = [...catList];
                updated[skillIdx] = { ...updated[skillIdx], value: 5, creationValue: 5 };
                newSkills[categoryId] = updated;
            }
        }

        // 2. Stocker le nom dans le TraitEntry correspondant (masterSkillTarget)
        // Et mettre ├á jour le variant pour l'affichage ("Maitre : Bagarre")
        const traitList = [...currentData.page2[traitType]];
        const traitIdx = traitList.findIndex(t => t.name === traitName && !t.masterSkillTarget);
        if (traitIdx !== -1) {
            traitList[traitIdx] = {
                ...traitList[traitIdx],
                masterSkillTarget: skillName,
                variant: skillName
            };
        }

        return {
            ...currentData,
            skills: newSkills,
            page2: { ...currentData.page2, [traitType]: traitList }
        };
    };

    return {
        multiSelectTarget,
        setMultiSelectTarget,
        removeTrait,
        handleMultiAdd,
        applyMasterSkill
    };
};

import { useCallback } from 'react';
import { DotEntry, SuggestionEntry } from '../../types';
import { normalizeString } from '../../utils/stringUtils';
import { generateId } from '../../utils/factories';
import { CharacterSheetData } from '../../types/character';
import { RulesData } from '../../types/rules';

export const useVariableSkills = (
    data: CharacterSheetData,
    onChange: (update: (prev: CharacterSheetData) => CharacterSheetData) => void,
    onAddLog: (message: string, type?: 'success' | 'danger' | 'info', category?: 'sheet' | 'settings' | 'both') => void,
    rules: RulesData | null,
    setVariantModalState: (state: any) => void,
    variantModalState: any
) => {
    const handleDefineVariant = useCallback((category: string, id: string, name: string) => {
        const existingEntry = data.skills[category]?.find(s => s.id === id);
        let definitionId = existingEntry?.definitionId;
        let variants: string[] = [];

        const libSkill = rules?.libraries?.skills?.find(s =>
            (definitionId && s.id === definitionId) ||
            normalizeString(s.name) === normalizeString(name)
        );

        if (libSkill) {
            definitionId = libSkill.id;
            variants = libSkill.variants || [];
        }

        setVariantModalState({
            isOpen: true,
            category,
            id,
            skillName: name,
            definitionId,
            variants
        });
    }, [data.skills, rules?.libraries?.skills, setVariantModalState]);

    const finalizeVariantDefinition = (variantName: string) => {
        const { category, id, definitionId } = variantModalState;
        if (!variantName.trim()) return;

        onChange(prev => {
            const list = prev.skills[category];
            if (!list) return prev;

            const index = list.findIndex(s => s.id === id);
            if (index === -1) return prev;

            const newList = [...list];

            newList[index] = {
                ...newList[index],
                variant: variantName.trim(),
                definitionId: definitionId || newList[index].definitionId
            };

            const newItem: DotEntry = {
                id: generateId(),
                name: newList[index].name,
                value: 0,
                creationValue: 0,
                max: 5,
                variant: "",
                definitionId: definitionId
            };

            newList.splice(index + 1, 0, newItem);

            onAddLog(`D├®finition variante : ${newList[index].name} : ${newList[index].variant}`, 'success', 'sheet');

            const newState = {
                ...prev,
                skills: {
                    ...prev.skills,
                    [category]: newList
                }
            };

            if (definitionId && variantName.trim()) {
                const libSkill = rules?.libraries?.skills?.find(s => s.id === definitionId);
                const normalizedVariant = normalizeString(variantName);

                const isKnown = libSkill?.variants?.some(v => normalizeString(v) === normalizedVariant);

                if (libSkill && !isKnown) {
                    const alreadySuggested = prev.suggestions?.some(s =>
                        s.type === 'variant' &&
                        s.parentId === definitionId &&
                        normalizeString(s.name) === normalizedVariant
                    );

                    if (!alreadySuggested) {
                        const suggestion: SuggestionEntry = {
                            id: generateId(),
                            type: 'variant',
                            name: variantName.trim(),
                            category: category,
                            parentId: definitionId,
                            timestamp: Date.now()
                        };
                        newState.suggestions = [...(prev.suggestions || []), suggestion];
                        onAddLog(`Suggestion de variante envoy├®e : ${variantName}`, 'info', 'sheet');
                    }
                }
            }

            return newState;
        });

        setVariantModalState((prev: any) => ({ ...prev, isOpen: false }));
    };

    return {
        handleDefineVariant,
        finalizeVariantDefinition
    };
};

import { useState, useEffect, useRef } from 'react';
import { CharacterSheetData } from '../types';
import { CharacterSyncService } from '../services/CharacterSyncService';

// Time in seconds
const AUTO_SAVE_INTERVAL = 60;

export const useAutoSave = (
    data: CharacterSheetData,
    initialIsDirty: boolean, // Passed from layout if tracked elsewhere, or we track it here
    onSync: (mode: 'auto') => Promise<void>
) => {
    const [timeLeft, setTimeLeft] = useState(AUTO_SAVE_INTERVAL);
    const [isDirty, setIsDirty] = useState(false);
    const lastHashRef = useRef<string>("");

    // Detect changes with debounce to avoid heavy hashing on every keystroke
    useEffect(() => {
        const checkDirty = setTimeout(() => {
            if (!data.syncInfo?.lastSyncedHash) {
                // Not synced yet or orphan
                setIsDirty(true);
                return;
            }

            const currentHash = CharacterSyncService.generateDataHash(data);
            const isChanged = currentHash !== data.syncInfo.lastSyncedHash;

            if (isChanged && !isDirty) {
                setIsDirty(true);
                // On first modification, ensure we have a full timer
                setTimeLeft(AUTO_SAVE_INTERVAL);
            } else if (!isChanged && isDirty) {
                setIsDirty(false);
            }
        }, 1000); // 1s debounce for hash calculation

        return () => clearTimeout(checkDirty);
    }, [data, isDirty]);

    // Timer effect
    useEffect(() => {
        const isEnabled = data.syncInfo?.isAutoSyncEnabled;

        if (!isEnabled || !isDirty) {
            return;
        }

        const interval = setInterval(() => {
            setTimeLeft((prev) => {
                if (prev <= 1) {
                    // Trigger sync
                    onSync('auto');
                    return AUTO_SAVE_INTERVAL;
                }
                return prev - 1;
            });
        }, 1000);

        return () => clearInterval(interval);
    }, [data.syncInfo?.isAutoSyncEnabled, isDirty, onSync]);

    return {
        countdown: (data.syncInfo?.isAutoSyncEnabled && isDirty) ? timeLeft : undefined,
        isDirty
    };
};

import { useMemo } from 'react';
import { TraitEntry, LibraryEntry, BonusInfo } from '../types';
import { normalizeString } from '../utils/stringUtils';
import { logger } from '../utils/logger';
import { evaluateFormula } from '../utils/formulaEvaluator';
import { useCharacter } from '../context/CharacterContext';
import { useRules } from '../context/RulesContext';

/**
 * Hook chirurgical pour extraire la logique de calcul des bonus d'attributs.
 */
export const useCharacterBonuses = (
    avantages: TraitEntry[] = [],
    desavantages: TraitEntry[] = [],
    library: LibraryEntry[] = [],
    rulesTraits: LibraryEntry[] = []
) => {
    const { data: characterData } = useCharacter();
    const { rules } = useRules();

    return useMemo(() => {
        const attributeBonuses: Record<string, BonusInfo> = {};
        const blockedSkills: Record<string, { isBlocked: boolean, sourceName: string }> = {};
        const counterCreationBonuses: Record<string, number> = {};
        const counterXPBonuses: Record<string, number> = {};
        const calculatedMaxes: Record<string, number> = {};
        const activeReserves: Set<string> = new Set();
        const allTraits = [...(avantages || []), ...(desavantages || [])];

        allTraits.forEach(trait => {
            if (!trait.name) return;
            const normalizedTraitName = normalizeString(trait.name);
            const libEntry = library?.find(l => normalizeString(l.name) === normalizedTraitName) ||
                rulesTraits?.find(t => normalizeString(t.name) === normalizedTraitName);

            if (libEntry && libEntry.effects) {
                libEntry.effects.forEach(effect => {
                    // Try to resolve formula from global library if formulaId is present
                    let formulaString = effect.formula;
                    let isReserve = false;
                    let effectiveTarget = effect.target;
                    let effectiveType: string = effect.type;

                    if (effect.formulaId && rules?.libraries?.formulas) {
                        const globalFormula = rules.libraries.formulas.find(f => f.id === effect.formulaId);
                        if (globalFormula) {
                            formulaString = globalFormula.formula || effect.formula;
                            if (globalFormula.type === 'variable') {
                                isReserve = true;
                                activeReserves.add(globalFormula.id);
                            }

                            // AUTO-PORTANTE: Heirarchical Target and EffectType
                            if (globalFormula.forceVariant && !effect.target) {
                                // If it forces a variant, the trait's variant is our target
                                effectiveTarget = trait.variant;
                            } else if (!effectiveTarget && globalFormula.target) {
                                effectiveTarget = globalFormula.target;
                            }
                            if (globalFormula.effectType) {
                                effectiveType = globalFormula.effectType;
                            }
                        }
                    }

                    // Skill Blocking
                    if (effectiveType === 'block_skill_increase' && effectiveTarget) {
                        const targetName = normalizeString(effectiveTarget);
                        blockedSkills[targetName] = {
                            isBlocked: true,
                            sourceName: trait.name
                        };
                    }

                    // Formula Evaluation
                    const isFormulaLike = effectiveType === 'formula' || effectiveType === 'xp_bonus';
                    if (isFormulaLike && formulaString && characterData) {
                        // Skip evaluation for raw reserves (they don't target/modify existing stats, they ARE stats)
                        if (isReserve) return;

                        const targetName = normalizeString(effectiveTarget || "");
                        if (!targetName) return;

                        const traitValue = parseInt(trait.value?.toString() || '1') || 1;

                        try {
                            const result = evaluateFormula(formulaString, {
                                ...characterData,
                                formulaLibrary: rules?.libraries?.formulas || characterData.formulaLibrary
                            }, { traitLevel: traitValue });

                            // Handle special semantic effects even for formulas
                            if (effectiveType === 'xp_bonus' || targetName === 'xp') {
                                // XP handled elsewhere (but we could record it here if needed)
                                return;
                            }

                            const isAttribute = Object.keys(characterData.attributes).some(
                                cat => characterData.attributes[cat].some(attr => normalizeString(attr.name) === targetName)
                            );

                            const operator = effect.operator || (rules?.libraries?.formulas?.find(f => f.id === effect.formulaId)?.operator) || 'ADD';

                            if (isAttribute) {
                                if (!attributeBonuses[targetName]) {
                                    attributeBonuses[targetName] = { value: 0, sources: [] };
                                }
                                if (operator === 'ADD') {
                                    attributeBonuses[targetName].value += result;
                                } else if (operator === 'SUB') {
                                    attributeBonuses[targetName].value -= result;
                                } else if (operator === 'SET') {
                                    attributeBonuses[targetName].value = result;
                                }
                                attributeBonuses[targetName].sources.push(`${trait.name} (${operator === 'SUB' ? '-' : operator === 'SET' ? '=' : '+'}${result})`);
                            } else if ((effectiveType as string) === 'master_skill' || (effectiveType as string) === 'block_skill_increase') {
                                // These are handled by their own logic blocks usually
                            } else {
                                // Assume it's a counter
                                if (trait.isPostCreation) {
                                    if (operator === 'SET') counterXPBonuses[targetName] = result;
                                    else if (operator === 'SUB') counterXPBonuses[targetName] = (counterXPBonuses[targetName] || 0) - result;
                                    else counterXPBonuses[targetName] = (counterXPBonuses[targetName] || 0) + result;
                                } else {
                                    if (operator === 'SET') counterCreationBonuses[targetName] = result;
                                    else if (operator === 'SUB') counterCreationBonuses[targetName] = (counterCreationBonuses[targetName] || 0) - result;
                                    else counterCreationBonuses[targetName] = (counterCreationBonuses[targetName] || 0) + result;
                                }
                            }

                        } catch (e) {
                            logger.error(`Error evaluating formula for trait ${trait.name}:`, e);
                        }
                    }
                });
            }
        });
        // Calculate Dynamic Maxes for Counters
        if (characterData && rules?.libraries?.counters) {
            Object.values(characterData.skills || {}).flat().forEach(skill => {
                // We only care about skills that are actually "Counters" 
                // (This is determined by their category behavior, but checking library here is more direct)
                const counterLibEntry = rules.libraries.counters.find(c => c.name === skill.name);
                if (counterLibEntry?.formulaId) {
                    const formulaEntry = rules.libraries.formulas?.find(f => f.id === counterLibEntry.formulaId);
                    if (formulaEntry) {
                        try {
                            const maxVal = evaluateFormula(formulaEntry.formula, {
                                ...characterData,
                                formulaLibrary: rules.libraries.formulas
                            });
                            calculatedMaxes[skill.name] = maxVal;
                        } catch (e) {
                            logger.error(`Error calculating dynamic max for counter ${skill.name}:`, e);
                        }
                    }
                }
            });

            // Handle Standard Counters (those in data.counters)
            if (characterData.counters) {
                const processCounter = (counter: any) => {
                    if (!counter || !counter.name) return;
                    const nameKey = normalizeString(counter.name);
                    const libEntry = rules.libraries.counters.find(c => normalizeString(c.name) === nameKey);

                    if (libEntry?.formulaId) {
                        const formulaEntry = rules.libraries.formulas?.find(f => f.id === libEntry.formulaId);
                        if (formulaEntry) {
                            try {
                                const maxVal = evaluateFormula(formulaEntry.formula, {
                                    ...characterData,
                                    formulaLibrary: rules.libraries.formulas
                                });
                                calculatedMaxes[counter.name] = maxVal;
                            } catch (e) {
                                logger.error(`Error calculating dynamic max for counter ${counter.name}:`, e);
                            }
                        }
                    } else if (libEntry?.formula) {
                        try {
                            const maxVal = evaluateFormula(libEntry.formula, {
                                ...characterData,
                                formulaLibrary: rules.libraries.formulas
                            });
                            calculatedMaxes[counter.name] = maxVal;
                        } catch (e) {
                            logger.error(`Error calculating dynamic max for counter ${counter.name}:`, e);
                        }
                    }
                };

                Object.keys(characterData.counters).forEach(key => {
                    const value = characterData.counters[key as keyof typeof characterData.counters];
                    if (Array.isArray(value)) {
                        value.forEach(processCounter);
                    } else {
                        processCounter(value);
                    }
                });
            }
        }

        return { attributeBonuses, blockedSkills, counterCreationBonuses, counterXPBonuses, calculatedMaxes, activeReserves: Array.from(activeReserves) };
    }, [avantages, desavantages, library, rulesTraits, characterData, rules]);
};

import { useCallback } from 'react';
import { DotEntry, SuggestionEntry, XPTransaction } from '../types';
import { normalizeString } from '../utils/stringUtils';
import { generateId } from '../utils/factories';
import { RulesData } from '../types/rules';
import { CharacterSheetData } from '../types/character';
import { getSkillCategory, getCounter, setCounter } from '../utils/stateAccessors';
import { evaluateFormula } from '../utils/formulaEvaluator';

interface DropPayload {
    type: string;
    data: {
        id?: string;
        name: string;
        description?: string;
        isVariable?: boolean;
        categoryType?: string;
        [key: string]: any;
    };
    categoryType?: string;
}

export const useCharacterSheetActions = (
    data: CharacterSheetData,
    onChange: (update: (prev: CharacterSheetData) => CharacterSheetData) => void,
    onAddLog: (message: string, type?: 'success' | 'danger' | 'info', category?: 'sheet' | 'settings' | 'both', deduplicationId?: string) => void,
    recordXPTransaction: (transaction: Omit<XPTransaction, 'id' | 'timestamp'>) => void,
    rules: RulesData | null
) => {

    const updateHeader = useCallback((field: keyof typeof data.header, value: string) => {
        onChange(prev => ({ ...prev, header: { ...prev.header, [field]: value } }));
        onAddLog(`En-t├¬te modifi├®e : ${String(field)} = "${value}"`, 'info', 'sheet', `header_${String(field)}`);
    }, [onChange, onAddLog]);

    const updateDot = useCallback((section: 'skills', category: string, id: string, value: number) => {
        onChange(prev => {
            const list = getSkillCategory(prev, category);
            if (!list) return prev;

            const isCreationMode = prev.creationConfig && prev.creationConfig.active;
            const catDef = rules?.definitions?.skillCategories?.find(c => c.id === category);
            const behavior = catDef?.behavior;
            const isBaseSkill = !behavior || behavior === 'Comp├®tence' || behavior === 'Secondaire' || behavior === 'Arri├¿re-plan';

            const itemToUpdate = list.find(item => item.id === id);
            if (!itemToUpdate) return prev;

            // Recalculate cost if it's an XP purchase (not creation mode)
            if (!isCreationMode && itemToUpdate.value !== value) {
                const multiplier = catDef?.costConfig?.factor ?? 1.0;
                const isTriangular = catDef?.costConfig?.type === 'triangular';
                const isUpgrade = value > itemToUpdate.value;

                // Helper to calculate XP difference
                const triangular = (n: number) => (n * (n + 1)) / 2;
                const getXPCost = (curr: number, creat: number) => {
                    if (curr <= creat) return 0;
                    return isTriangular ? (triangular(curr) - triangular(creat)) * multiplier : (curr - creat) * multiplier;
                };

                const oldCost = getXPCost(itemToUpdate.value, itemToUpdate.creationValue || 0);
                const newCost = getXPCost(value, itemToUpdate.creationValue || 0);
                const diff = Math.abs(newCost - oldCost);

                if (diff !== 0) {
                    recordXPTransaction({
                        type: isUpgrade ? 'spend' : 'refund',
                        description: `${isUpgrade ? 'Am├®lioration' : 'R├®duction'} : ${itemToUpdate.name} (${itemToUpdate.value} ÔåÆ ${value})`,
                        amount: diff,
                        source: 'XP Libre',
                        relatedId: id
                    });
                }
            }

            const newList = list.map(item => {
                if (item.id !== id) return item;
                if (isCreationMode && isBaseSkill) {
                    return { ...item, value, creationValue: value };
                }
                return { ...item, value };
            });

            const itemName = itemToUpdate.name || 'Comp├®tence';
            onAddLog(`Modification ${String(itemName)} : ${value}`, 'info', 'sheet', `dot_${String(id)}`);

            const updatedState = {
                ...prev,
                [section]: {
                    ...prev[section],
                    [String(category)]: newList
                }
            };

            if (section === 'skills' && prev.counters) {
                const counterKey = Object.keys(prev.counters).find(k => k === id);
                if (counterKey) {
                    const currentCounter = getCounter(prev, counterKey);
                    if (currentCounter && !Array.isArray(currentCounter)) {
                        const newCounter = { ...currentCounter, value, creationValue: isCreationMode ? value : currentCounter.creationValue };
                        const updatedCounters = { ...prev.counters };
                        setCounter({ ...prev, counters: updatedCounters } as CharacterSheetData, counterKey, newCounter);
                        updatedState.counters = updatedCounters;
                    }
                }
            }

            return updatedState;
        });
    }, [onChange, onAddLog, rules]);

    const handleDropItem = useCallback((category: string, payload: DropPayload, targetIndex?: number) => {
        const { type, data: itemData, categoryType } = payload;
        const catDef = rules?.definitions?.skillCategories?.find(c => c.id === category);
        const behavior = catDef?.behavior || 'Comp├®tence';

        if (categoryType === 'skill' && (behavior !== 'Comp├®tence' && behavior !== 'Secondaire')) {
            onAddLog("Action bloqu├®e : Cette cat├®gorie n'accepte pas les comp├®tences.", 'danger', 'sheet');
            return;
        }
        if (categoryType === 'background' && behavior !== 'Arri├¿re-plan') {
            onAddLog("Action bloqu├®e : Cette cat├®gorie n'accepte pas les historiques.", 'danger', 'sheet');
            return;
        }

        const newEntry: DotEntry = type === 'sheet_item'
            ? (itemData as DotEntry)
            : {
                id: generateId(),
                name: itemData.name,
                value: 0,
                creationValue: 0,
                max: 5,
                variant: itemData.isVariable ? "" : undefined,
                description: itemData.description,
                definitionId: itemData.id
            };

        onChange(prev => {
            const updatedSkills = { ...prev.skills };
            if (type === 'sheet_item') {
                Object.keys(updatedSkills).forEach(cat => {
                    updatedSkills[cat] = (updatedSkills[cat] || []).filter(s => s.id !== newEntry.id);
                });
            }

            const currentList = [...(updatedSkills[category] || [])];
            if (newEntry.name && !itemData.isVariable && currentList.some(s => s.name?.toLowerCase() === itemData.name.toLowerCase() && s.id !== newEntry.id)) {
                return prev;
            }

            if (targetIndex !== undefined && targetIndex >= 0 && targetIndex <= currentList.length) {
                currentList.splice(targetIndex, 0, newEntry);
            } else {
                currentList.push(newEntry);
            }

            updatedSkills[category] = currentList;
            const newState = { ...prev, skills: updatedSkills };

            if (type === 'custom_lib_item' || type === 'lib_skill') {
                const suggestionType = categoryType || (category.toLowerCase().includes('background') || category.toLowerCase().includes('arri├¿re-plan') ? 'background' : 'skill');
                const suggestion: SuggestionEntry = {
                    id: generateId(),
                    type: suggestionType as 'skill' | 'background',
                    name: itemData.name,
                    category: category,
                    timestamp: Date.now()
                };
                newState.suggestions = [...(prev.suggestions || []), suggestion];
                onAddLog(`Suggestion cr├®├®e pour le MJ : ${itemData.name}`, 'info', 'sheet');
            }

            return newState;
        });

        onAddLog(type === 'sheet_item' ? `D├®placement : ${itemData.name || 'Espaceur'}` : `Ajout r├®ussi : ${itemData.name || 'Espaceur'}`, 'success', 'sheet');
    }, [onChange, onAddLog, rules]);

    const handleRemoveItem = useCallback((category: string, id: string) => {
        onChange(prev => {
            const currentList = prev.skills[category] || [];
            const itemToRemove = currentList.find(s => s.id === id);

            if (itemToRemove && itemToRemove.name && (itemToRemove.value || 0) > 0) {
                onAddLog(`Action bloqu├®e : Impossible de supprimer une comp├®tence avec des points investis.`, 'danger', 'sheet');
                return prev;
            }

            const updatedList = currentList.filter(s => s.id !== id);
            return { ...prev, skills: { ...prev.skills, [category]: updatedList } };
        });
        onAddLog("├ël├®ment supprim├® de la fiche", 'info', 'sheet');
    }, [onChange, onAddLog]);

    const updateAttribute = useCallback((category: string, id: string, field: 'val1' | 'val2' | 'val3', value: string) => {
        onChange(prev => {
            const numValue = parseInt(value) || 0;
            const isCreationMode = prev.creationConfig && prev.creationConfig.active;

            const updateInList = <T extends { id: string; name?: string; val1?: string; val2?: string; val3?: string;[key: string]: any }>(list: T[]) => {
                const idx = list.findIndex(item => item.id === id);
                if (idx === -1) return null;
                const newList = [...list];
                const item = newList[idx];

                // Garde pour val1 hors mode cr├®ation
                if (field === 'val1' && !isCreationMode) {
                    return null;
                }

                if (!isCreationMode && field === 'val2' && item.val2 !== value) {
                    const oldVal = parseInt(item.val2 || "0") || 0;
                    const newVal = numValue;
                    const diff = Math.abs(newVal - oldVal);
                    const costPerPoint = prev.xpCosts?.attributeFactor ?? 6;

                    if (diff !== 0) {
                        recordXPTransaction({
                            type: newVal > oldVal ? 'spend' : 'refund',
                            description: `${newVal > oldVal ? 'Augmentation' : 'R├®duction'} Attribut : ${item.name} (+${diff})`,
                            amount: diff * costPerPoint,
                            source: 'XP Libre',
                            relatedId: id
                        });
                    }
                }

                const creationKey = `creation${field.charAt(0).toUpperCase() + field.slice(1)}`;
                newList[idx] = isCreationMode
                    ? { ...item, [field]: value, [creationKey]: numValue }
                    : { ...item, [field]: value };
                return { newList, name: item.name };
            };

            const attrResult = updateInList(prev.attributes?.[category] || []);
            if (attrResult) {
                onAddLog(`Attribut ${attrResult.name} modifi├®`, 'info', 'sheet', `attr_${id}_${field}`);
                return { ...prev, attributes: { ...prev.attributes, [category]: attrResult.newList } };
            }

            const secResult = updateInList(prev.secondaryAttributes?.[category] || []);
            if (secResult) {
                onAddLog(`Attribut ${secResult.name} modifi├®`, 'info', 'sheet', `attr_sec_${id}_${field}`);
                return { ...prev, secondaryAttributes: { ...prev.secondaryAttributes, [category]: secResult.newList } };
            }

            return prev;
        });
    }, [onChange, onAddLog]);

    const updateCombatWeapon = useCallback((id: string, field: string, value: string) => {
        onChange(prev => {
            const newWeapons = (prev.combat.weapons || []).map(w => w.id === id ? { ...w, [field]: value } : w);
            return { ...prev, combat: { ...prev.combat, weapons: newWeapons } };
        });
        onAddLog(`Arme modifi├®e (${field})`, 'info', 'sheet');
    }, [onChange, onAddLog]);

    const updateArmor = useCallback((index: number, field: string, value: string) => {
        onChange(prev => {
            const newArmor = [...(prev.combat.armor || [])];
            if (newArmor[index]) {
                newArmor[index] = { ...newArmor[index], [field]: value };
                return { ...prev, combat: { ...prev.combat, armor: newArmor } };
            }
            return prev;
        });
        onAddLog(`Armure modifi├®e (${field})`, 'info', 'sheet');
    }, [onChange, onAddLog]);

    const updateCounter = useCallback((id: string, value: number, isCustom = false, field: 'value' | 'current' = 'value') => {
        onChange(prev => {
            const isCreationMode = prev.creationConfig && prev.creationConfig.active;
            if (isCustom) {
                const newCustom = (prev.counters.custom || []).map(c => {
                    if (c.id !== id) return c;
                    const newItem = { ...c };
                    if (field === 'value') {
                        newItem.value = value;
                        if (isCreationMode) newItem.creationValue = value;
                        const effectiveMax = newItem.variant === 'squares_only' ? (newItem.max || 10) : newItem.value;
                        if ((newItem.current || 0) > effectiveMax) newItem.current = effectiveMax;
                    } else if (field === 'current') {
                        newItem.current = value;
                    }
                    return newItem;
                });
                return { ...prev, counters: { ...prev.counters, custom: newCustom } };
            } else {
                const counterKey = Object.keys(prev.counters).find(k => {
                    const c = getCounter(prev, k);
                    return !Array.isArray(c) && c?.id === id;
                }) || id;
                const current = getCounter(prev, counterKey);
                if (!current || Array.isArray(current)) return prev;

                const sysDef = rules?.definitions?.counters?.[id] || (rules?.definitions?.counters && rules.definitions.counters[counterKey]);
                const displayName = current.name || sysDef?.name || id;
                const libDef = rules?.libraries?.counters?.find(c => c.id === id || normalizeString(c.name) === normalizeString(displayName));

                const xpCost = libDef?.xpCost != null ? libDef.xpCost : (sysDef?.xpCost ?? 0);
                const defaultValue = libDef?.defaultValue != null ? libDef.defaultValue : (sysDef?.defaultValue ?? 0);

                if (field === 'value' && (libDef || sysDef)) {
                    if (xpCost <= 0 && value > current.value) return prev;
                    if (value < defaultValue) return prev;
                }

                const newItem = { ...current };
                if (field === 'value') {
                    if (!isCreationMode && current.value !== value) {
                        const isUpgrade = value > current.value;
                        const diff = Math.abs(value - current.value);
                        if (xpCost > 0 && diff !== 0) {
                            recordXPTransaction({
                                type: isUpgrade ? 'spend' : 'refund',
                                description: `${isUpgrade ? 'Augmentation' : 'R├®duction'} Compteur : ${displayName}`,
                                amount: diff * xpCost,
                                source: 'XP Libre',
                                relatedId: id
                            });
                        }
                    }
                    newItem.value = value;
                    if ((newItem.current || 0) > value) newItem.current = value;
                } else if (field === 'current') {
                    newItem.current = value;
                }

                const updatedCounters = { ...prev.counters };
                setCounter({ ...prev, counters: updatedCounters } as CharacterSheetData, counterKey, newItem);
                const updatedState = { ...prev, counters: updatedCounters };

                // Sync with skills if applicable
                if (field === 'value' && prev.skills) {
                    const newSkills = { ...prev.skills };
                    let skillFound = false;
                    Object.keys(newSkills).forEach(catId => {
                        const list = newSkills[catId];
                        const idx = list.findIndex(s => s.id === id);
                        if (idx !== -1) {
                            const catDef = rules?.definitions?.skillCategories?.find(c => c.id === catId);
                            const isCounterCat = catDef?.behavior === 'Compteur';
                            const newList = [...list];
                            newList[idx] = { ...newList[idx], value, creationValue: (isCreationMode && !isCounterCat) ? value : newList[idx].creationValue };
                            newSkills[catId] = newList;
                            skillFound = true;
                        }
                    });
                    if (skillFound) updatedState.skills = newSkills;
                }
                return updatedState;
            }
        });
    }, [onChange, onAddLog, rules]);

    return {
        updateHeader,
        updateDot,
        handleDropItem,
        handleRemoveItem,
        updateAttribute,
        updateCombatWeapon,
        updateArmor,
        updateCounter
    };
};

import { useCallback, useMemo } from 'react';
import { CharacterSheetData, DotEntry } from '../types';
import { RulesData, SkillBehavior } from '../types/rules';

export interface SkillBlock {
    title: string;
    items: DotEntry[];
    cat: string;
    description?: string;
}

export interface SheetColumn {
    id: number;
    topBlocks: SkillBlock[];
    bottomBlocks: SkillBlock[];
    readonly blocks: SkillBlock[];
}

export interface SheetLayout {
    columns: SheetColumn[];
    columnCount: number;
    backgrounds: SkillBlock[];
    counters: { title: string; id: string; description?: string }[];
}

type ColumnRow = 'top' | 'bottom';
interface Mapping {
    col: number;
    row: ColumnRow;
}

const LANDSCAPE_MAP: Record<string, Mapping> = {
    'Col_Comp_1': { col: 0, row: 'top' },
    'Col_Comp_2': { col: 1, row: 'top' },
    'Col_Comp_3': { col: 2, row: 'top' },
    'Col_Comp_4': { col: 3, row: 'top' },
    'Col_Comp_5': { col: 4, row: 'top' },
    'Col_Comp_6': { col: 0, row: 'bottom' },
    'Col_Comp_7': { col: 1, row: 'bottom' },
    'Col_Comp_8': { col: 2, row: 'bottom' },
    'Col_Comp_9': { col: 3, row: 'bottom' },
    'Col_Comp_10': { col: 4, row: 'bottom' },
};

const PORTRAIT_MAP: Record<string, Mapping> = {
    'Col_Comp_1': { col: 0, row: 'top' },
    'Col_Comp_2': { col: 1, row: 'top' },
    'Col_Comp_3': { col: 2, row: 'top' },
    'Col_Comp_4': { col: 3, row: 'top' },
    'Col_Comp_5': { col: 0, row: 'bottom' },
    'Col_Comp_6': { col: 1, row: 'bottom' },
    'Col_Comp_7': { col: 2, row: 'bottom' },
    'Col_Comp_8': { col: 3, row: 'bottom' },
    'Col_Comp_9': { col: 0, row: 'bottom' }, // Overflow
};

export const useSheetLayout = (data: CharacterSheetData, rules: RulesData | null) => {

    const attributeCategories = useMemo(() => data.attributeSettings || [
        { id: 'pave_attributs_1', label: 'Physique' },
        { id: 'pave_attributs_2', label: 'Mental' },
        { id: 'pave_attributs_3', label: 'Social' }
    ], [data.attributeSettings]);

    const getAttributesGridClass = useCallback(() => {
        const count = attributeCategories.length;
        if (count === 1) return 'grid-cols-1';
        if (count === 2) return 'grid-cols-2';
        if (count === 3) return 'grid-cols-3';
        if (count === 4) return 'grid-cols-4';
        return 'grid-cols-3'; // fallback
    }, [attributeCategories]);

    const getDynamicColumns = useCallback((isLandscape: boolean = false): SheetLayout => {
        const skillCats = rules?.definitions?.skillCategories || [];
        const fallback: SheetLayout = { columns: [], columnCount: isLandscape ? 5 : 4, backgrounds: [], counters: [] };

        if (skillCats.length === 0) return fallback;

        // 1. Separate by behavior
        const skillsSet = skillCats.filter(c => c.behavior === 'Comp├®tence' || c.behavior === 'Secondaire');
        const backgroundsSet = skillCats.filter(c => c.behavior === 'Arri├¿re-plan');
        const countersSet = skillCats.filter(c => c.behavior === 'Compteur');

        // 2. Base columns
        const columnCount = isLandscape ? 5 : 4;
        const columns: SheetColumn[] = Array.from({ length: columnCount }, (_, id) => ({
            id,
            topBlocks: [],
            bottomBlocks: [],
            get blocks() { return [...this.topBlocks, ...this.bottomBlocks]; }
        }));

        const mapping = isLandscape ? LANDSCAPE_MAP : PORTRAIT_MAP;

        skillsSet.forEach(cat => {
            const items = data.skills[cat.id] || [];

            // Enrich items with metadata from rules (search in all relevant libraries)
            const enrichedItems = items.map(item => {
                const targetId = item.definitionId || item.id;
                // 1. Lookup by ID (definitionId ou item.id)
                let def =
                    rules?.libraries?.skills.find(s => s.id === targetId) ||
                    rules?.libraries?.mysticAbilities.find(s => s.id === targetId);

                // 2. Fallback par nom pour compatibilit├® fiches existantes (pas de definitionId)
                if (!def && item.name) {
                    const nameLower = item.name.trim().toLowerCase();
                    def = rules?.libraries?.skills.find(s => s.name.trim().toLowerCase() === nameLower);
                }

                if (def) {
                    return {
                        ...item,
                        mysticAbilityId: def.mysticAbilityId || (rules?.libraries?.mysticAbilities.some(ma => ma.id === targetId) ? targetId : undefined),
                        isVariable: def.isVariable
                    };
                }
                return item;
            });

            const map = mapping[cat.id] || { col: 0, row: 'top' };
            const block: SkillBlock = {
                title: cat.label,
                items: enrichedItems,
                cat: cat.id,
                description: cat.description
            };

            // Safety check for col index
            if (map.col < columns.length) {
                if (map.row === 'top') {
                    columns[map.col].topBlocks.push(block);
                } else {
                    columns[map.col].bottomBlocks.push(block);
                }
            }
        });

        return {
            columns,
            columnCount,
            backgrounds: backgroundsSet.map(cat => {
                const items = data.skills[cat.id] || [];
                const enrichedItems = items.map(item => {
                    const targetId = item.definitionId || item.id;
                    // 1. Lookup par ID
                    let def =
                        rules?.libraries?.skills.find(s => s.id === targetId) ||
                        rules?.libraries?.mysticAbilities.find(s => s.id === targetId) ||
                        rules?.libraries?.backgrounds.find(s => s.id === targetId);

                    // 2. Fallback par nom pour r├®trocompatibilit├®
                    if (!def && item.name) {
                        const nameLower = item.name.trim().toLowerCase();
                        def = rules?.libraries?.skills.find(s => s.name.trim().toLowerCase() === nameLower)
                            || rules?.libraries?.backgrounds.find(s => s.name.trim().toLowerCase() === nameLower);
                    }

                    if (def) {
                        return {
                            ...item,
                            mysticAbilityId: def.mysticAbilityId || (rules?.libraries?.mysticAbilities.some(ma => ma.id === targetId) ? targetId : undefined),
                            isVariable: def.isVariable
                        };
                    }
                    return item;
                });
                return {
                    title: cat.label,
                    items: enrichedItems,
                    cat: cat.id,
                    description: cat.description
                };
            }),
            counters: countersSet.map(cat => ({
                title: cat.label,
                id: cat.id,
                description: cat.description
            }))
        };
    }, [data.skills, rules?.definitions?.skillCategories]);

    return {
        attributeCategories,
        getAttributesGridClass,
        getDynamicColumns
    };
};

import { useState, useMemo, useCallback } from 'react';
import { CharacterSheetData, LibraryEntry, TraitEffect } from '../types';
import { MergedEntry } from '../utils/libraryMerger';
import { useRules } from '../context/RulesContext';

export const useTraitActions = (
    data: CharacterSheetData,
    onUpdate: (newData: CharacterSheetData) => void,
    defaultType: 'avantage' | 'desavantage'
) => {
    const { rules, updateRules } = useRules();
    const allFormulas = useMemo(() => rules?.libraries?.formulas || [], [rules]);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editForm, setEditForm] = useState<LibraryEntry | null>(null);
    const [tagInput, setTagInput] = useState('');
    const [error, setError] = useState<string | null>(null);
    const [showDeleteConfirm, setShowDeleteConfirm] = useState<string | null>(null);
    const [showOfficialUpdateConfirm, setShowOfficialUpdateConfirm] = useState(false);
    const [updateResult, setUpdateResult] = useState<{ success: boolean; message: string } | null>(null);

    const handleOpenNew = useCallback(() => {
        setError(null);
        setTagInput('');
        setEditForm({
            id: Math.random().toString(36).substr(2, 9),
            name: '',
            type: defaultType,
            cost: '1',
            pointsLabel: '1 point',
            description: '',
            tags: [],
            effects: []
        });
        setIsModalOpen(true);
    }, [defaultType]);

    const handleOpenEdit = useCallback((merged: MergedEntry<LibraryEntry> | LibraryEntry) => {
        const entry = 'entry' in merged ? merged.entry : merged;
        const source = 'source' in merged ? merged.source : 'local';

        setError(null);
        setTagInput('');
        setEditForm({
            ...entry,
            id: entry.id,
            tags: [...(entry.tags || [])],
            effects: (entry.effects || []).map(e => ({ ...e }))
        });
        setIsModalOpen(true);
    }, []);

    const handleDelete = useCallback((id: string, source: string) => {
        if (source === 'official') return;
        setShowDeleteConfirm(id);
    }, []);

    const confirmDelete = useCallback(() => {
        if (!showDeleteConfirm) return;
        const local = (data && Array.isArray(data.library)) ? data.library : [];
        onUpdate({ ...data, library: local.filter(l => l.id !== showDeleteConfirm) });
        setShowDeleteConfirm(null);
    }, [data, onUpdate, showDeleteConfirm]);

    const handleSave = useCallback(() => {
        if (!editForm) return;
        if (!editForm.name.trim()) { setError("Le nom du trait ne peut pas ├¬tre vide."); return; }

        const local = (data && Array.isArray(data.library)) ? data.library : [];
        const duplicate = local.find(l => l.id !== editForm.id && l.name.trim().toLowerCase() === editForm.name.trim().toLowerCase());

        if (duplicate) { setError("Un trait personnel portant ce nom existe d├®j├á."); return; }

        const formToSave = {
            ...editForm,
            variants: editForm.variants ? editForm.variants.map(v => v.trim()).filter(v => v !== '') : []
        };

        const existsLocally = local.some(l => l.id === formToSave.id);
        const newLibrary = existsLocally
            ? local.map(l => l.id === formToSave.id ? formToSave : l)
            : [formToSave, ...local];

        onUpdate({ ...data, library: newLibrary });
        setIsModalOpen(false);
        setEditForm(null);
    }, [data, editForm, onUpdate]);

    const executeOfficialUpdate = async () => {
        try {
            const res = await fetch('./data/traits.json?t=' + Date.now());
            if (!res.ok) throw new Error("Fichier introuvable");

            const json = await res.json();
            const newTraits = json.data as LibraryEntry[];

            if (json.meta && json.meta.type !== 'traits') throw new Error("Format invalide");

            const updatedRules = {
                ...rules!,
                libraries: {
                    ...rules!.libraries,
                    traits: newTraits
                },
                lastUpdated: Date.now() // Force CharacterContext reconciliation
            };
            updateRules(updatedRules);
            setUpdateResult({ success: true, message: `Biblioth├¿que officielle mise ├á jour (${newTraits.length} traits).` });
        } catch (e) {
            setUpdateResult({ success: false, message: "├ëchec de la mise ├á jour officielle : " + (e as Error).message });
        } finally {
            setShowOfficialUpdateConfirm(false);
        }
    };

    const handleImportTraits = useCallback((importedEntries: LibraryEntry[]) => {
        const local = (data && Array.isArray(data.library)) ? data.library : [];
        const newLibrary = [...local];

        importedEntries.forEach(entry => {
            const index = newLibrary.findIndex(l => l.id === entry.id);
            if (index >= 0) {
                newLibrary[index] = entry;
            } else {
                newLibrary.unshift(entry);
            }
        });

        onUpdate({ ...data, library: newLibrary });
    }, [data, onUpdate]);

    const addTag = useCallback(() => {
        if (!editForm || !tagInput.trim()) return;
        const newTag = tagInput.trim();
        if (!(editForm.tags || []).includes(newTag)) {
            setEditForm({ ...editForm, tags: [...(editForm.tags || []), newTag] });
        }
        setTagInput('');
    }, [editForm, tagInput]);

    const removeTag = useCallback((tagToRemove: string) => {
        if (!editForm) return;
        setEditForm({ ...editForm, tags: (editForm.tags || []).filter(t => t !== tagToRemove) });
    }, [editForm]);

    const addEffect = useCallback(() => {
        if (!editForm) return;
        const newEffect: TraitEffect = { id: Math.random().toString(36).substr(2, 9), type: 'formula', value: 0 };
        setEditForm({ ...editForm, effects: [...(editForm.effects || []), newEffect] });
    }, [editForm]);

    const updateEffect = useCallback((id: string, field: keyof TraitEffect, value: any) => {
        if (!editForm) return;

        const newEffects = (editForm.effects || []).map(e => e.id === id ? { ...e, [field]: value } : e);

        // D├®tecter si une des formules force la variante
        const hasForceVariantFormula = newEffects.some(ef => {
            if (!ef.formulaId) return false;
            const formula = allFormulas.find(f => f.id === ef.formulaId);
            return formula?.forceVariant;
        });

        // Si une formule force la variante, on s'assure que le trait est marqu├® comme variable
        const updatedForm: LibraryEntry = {
            ...editForm,
            effects: newEffects,
            isVariable: hasForceVariantFormula ? true : editForm.isVariable
        };

        setEditForm(updatedForm);
    }, [editForm, allFormulas]);

    const removeEffect = useCallback((id: string) => {
        if (!editForm) return;
        const newEffects = (editForm.effects || []).filter(e => e.id !== id);

        // Recalculer si une des formules restantes force toujours la variante
        const hasForceVariantFormula = newEffects.some(ef => {
            if (!ef.formulaId) return false;
            const formula = allFormulas.find(f => f.id === ef.formulaId);
            return formula?.forceVariant;
        });

        setEditForm({
            ...editForm,
            effects: newEffects,
            isVariable: hasForceVariantFormula ? true : editForm.isVariable
        });
    }, [editForm, allFormulas]);

    const allSkills = useMemo(() => {
        const skills: { id: string, name: string }[] = [];

        // 1. From Character Sheet (Local)
        if (data?.skills) {
            Object.values(data.skills).forEach(skillList => {
                skillList.forEach(s => {
                    if (s.name && s.name.trim() !== '') {
                        skills.push({ id: s.id, name: s.name });
                    }
                });
            });
        }

        // 2. From Official Campaign Libraries
        if (rules?.libraries) {
            if (rules.libraries.skills) {
                rules.libraries.skills.forEach(skill => {
                    if (!skills.some(s => s.id === skill.id)) {
                        skills.push({ id: skill.id, name: skill.name });
                    }
                });
            }
            if (rules.libraries.mysticAbilities) {
                rules.libraries.mysticAbilities.forEach(ma => {
                    if (!skills.some(s => s.id === ma.id)) {
                        skills.push({ id: ma.id, name: ma.name });
                    }
                });
            }
            if (rules.libraries.backgrounds) {
                rules.libraries.backgrounds.forEach(bg => {
                    if (!skills.some(s => s.id === bg.id)) {
                        skills.push({ id: bg.id, name: bg.name });
                    }
                });
            }
        }

        return skills.sort((a, b) => a.name.localeCompare(b.name));
    }, [data.skills, rules?.libraries]);

    const allAttributes = useMemo(() => {
        if (!data || !data.attributes) return [];
        const attrs: { id: string, name: string }[] = [];
        if (data.attributes) {
            Object.keys(data.attributes).forEach(key => {
                data.attributes[key].forEach(a => {
                    if (a.name && a.name.trim() !== '') {
                        attrs.push({ id: a.id, name: a.name });
                    }
                });
            });
        }
        return attrs.sort((a, b) => a.name.localeCompare(b.name));
    }, [data.attributes]);

    const allCounters = useMemo(() => {
        if (!data || !data.counters) return [];
        const counters: { id: string, name: string }[] = [];

        // System counters
        Object.keys(data.counters).forEach(key => {
            if (key !== 'custom' && !Array.isArray(data.counters[key])) {
                const c = data.counters[key] as any;
                if (c && c.name && c.name.trim() !== '') {
                    counters.push({ id: c.id || key, name: c.name });
                }
            }
        });

        // Custom counters
        if (data.counters.custom && Array.isArray(data.counters.custom)) {
            data.counters.custom.forEach(c => {
                if (c && c.name && c.name.trim() !== '') {
                    counters.push({ id: c.id, name: c.name });
                }
            });
        }

        // Also look at counterLibrary
        if (data.counterLibrary && Array.isArray(data.counterLibrary)) {
            data.counterLibrary.forEach(c => {
                if (c && c.name && c.name.trim() !== '' && !counters.some(ex => ex.name === c.name)) {
                    counters.push({ id: c.id, name: c.name });
                }
            });
        }

        return counters.sort((a, b) => a.name.localeCompare(b.name));
    }, [data.counters, data.counterLibrary]);



    return {
        isModalOpen,
        setIsModalOpen,
        editForm,
        setEditForm,
        tagInput,
        setTagInput,
        error,
        showDeleteConfirm,
        setShowDeleteConfirm,
        showOfficialUpdateConfirm,
        setShowOfficialUpdateConfirm,
        updateResult,
        setUpdateResult,
        handleOpenNew,
        handleOpenEdit,
        handleDelete,
        confirmDelete,
        handleSave,
        executeOfficialUpdate,
        handleImportTraits,
        addTag,
        removeTag,
        addEffect,
        updateEffect,
        removeEffect,
        allSkills,
        allAttributes,
        allCounters,
        allFormulas
    };
};

import { useMemo, useState } from 'react';
import { CharacterSheetData, LibraryEntry } from '../types';
import { useRules } from '../context/RulesContext';
import { mergeLibraries, MergedEntry } from '../utils/libraryMerger';
import { smartIncludes } from '../utils/stringUtils';

export type SortOption = 'name' | 'cost' | 'type';
export type SortOrder = 'asc' | 'desc';

export const useTraitLibrary = (
    data: CharacterSheetData,
    searchTerm: string,
    filterType: 'all' | 'avantage' | 'desavantage',
    selectedTags: string[],
    sortBy: SortOption,
    sortOrder: SortOrder,
    hidePossessed: boolean = false
) => {
    const { rules } = useRules();

    const hybridList = useMemo(() => {
        const local = (data && Array.isArray(data.library)) ? data.library.filter(entry => entry && typeof entry === 'object') : [];
        const official = rules?.libraries?.traits || [];
        return mergeLibraries(local, official);
    }, [data.library, rules]);

    // Pre-calculate possessed trait names for fast lookup
    const possessedTraitNames = useMemo(() => {
        if (!hidePossessed || !data?.page2) return new Set<string>();
        const names = new Set<string>();
        [...(data.page2.avantages || []), ...(data.page2.desavantages || [])].forEach(t => {
            if (t.name) names.add(t.name.trim().toLowerCase());
        });
        return names;
    }, [data?.page2, hidePossessed]);

    const allAvailableTags = useMemo(() => {
        const tags = new Set<string>();
        hybridList.forEach(m => (m.entry.tags || []).forEach(t => tags.add(t)));
        return Array.from(tags).sort();
    }, [hybridList]);

    const processedList = useMemo(() => {
        const list = hybridList.filter(m => {
            const entry = m.entry;

            // Filter already possessed standard traits if requested
            if (hidePossessed && !entry.isVariable) {
                if (possessedTraitNames.has(entry.name.trim().toLowerCase())) {
                    return false;
                }
            }

            const entryTags = entry.tags || [];
            const matchesSearch = smartIncludes(entry.name, searchTerm) ||
                smartIncludes(entry.description || "", searchTerm) ||
                entryTags.some(t => smartIncludes(t, searchTerm));
            const matchesType = filterType === 'all' || entry.type === filterType;
            const matchesTags = selectedTags.length === 0 || selectedTags.every(sel =>
                entryTags.some(t => t.toLowerCase() === sel.toLowerCase())
            );
            return matchesSearch && matchesType && matchesTags;
        });

        list.sort((a, b) => {
            const ea = a.entry;
            const eb = b.entry;

            let comparison = 0;
            if (sortBy === 'name') comparison = ea.name.localeCompare(eb.name);
            else if (sortBy === 'cost') comparison = (parseInt(ea.cost || "0") || 0) - (parseInt(eb.cost || "0") || 0);
            else if (sortBy === 'type') comparison = ea.type.localeCompare(eb.type);

            if (comparison === 0) return ea.name.localeCompare(eb.name);
            return sortOrder === 'asc' ? comparison : -comparison;
        });

        return list;
    }, [hybridList, searchTerm, filterType, selectedTags, sortBy, sortOrder, hidePossessed, possessedTraitNames]);

    return {
        hybridList,
        processedList,
        allAvailableTags
    };
};

import { useState, useCallback } from 'react';
import { LibraryEntry, LibraryFormulaEntry } from '../types';
import { MergedEntry } from '../utils/libraryMerger';

export interface SelectedInstance {
    tempId: string;
    entry: LibraryEntry;
    variant?: string;
    cost?: string;
}

export const useTraitSelection = (
    onMultiSelect?: (instances: { entry: LibraryEntry; variant?: string; cost?: string }[]) => void,
    formulas: LibraryFormulaEntry[] = []
) => {
    const [selection, setSelection] = useState<SelectedInstance[]>([]);
    const [variantPicker, setVariantPicker] = useState<LibraryEntry | null>(null);
    const isVariableCost = (entry: any) => {
        if (entry.isVariableCost || entry.is_variable_cost) return true;
        const label = entry.pointsLabel || entry.points_label || entry.cost;
        if (!label) return false;
        // Check for range characters or multiple values
        return /[-,ÔÇôÔÇö,;]/.test(label) || label.includes('..');
    };

    const toggleSelection = useCallback((id: string, hybridList: MergedEntry<LibraryEntry>[]) => {
        const entry = hybridList.find(m => m.entry.id === id)?.entry;
        if (!entry) return;

        // Check if any effect in this trait uses a formula that forces a variant
        const hasForceVariantFormula = entry.effects?.some(eff => {
            if (!eff.formulaId) return false;
            const formula = formulas.find(f => f.id === eff.formulaId);
            return formula?.forceVariant;
        }) || false;

        // Open configuration modal if it has variants OR variable cost OR forced by formula
        // EXCEPTION: master_skill traits use their own specialized wizard
        const isMasterSkill = entry.effects?.some(eff => {
            const formula = formulas.find(f => f.id === eff.formulaId);
            return (formula?.effectType === 'master_skill' || (formula as any)?.type === 'master_skill');
        });

        if (!isMasterSkill && (entry.isVariable || (entry as any).is_variable || isVariableCost(entry) || hasForceVariantFormula)) {
            setVariantPicker(entry);
        } else {
            setSelection(prev => {
                const isAlreadySelected = prev.some(s => s.entry.id === id);
                if (isAlreadySelected) {
                    return prev.filter(s => s.entry.id !== id);
                } else {
                    return [...prev, { tempId: Math.random().toString(36).substr(2, 9), entry, cost: entry.cost || undefined }];
                }
            });
        }
    }, [formulas]);

    const addInstanceWithVariant = useCallback((entry: LibraryEntry, variant: string, cost?: string) => {
        setSelection(prev => [
            ...prev,
            { tempId: Math.random().toString(36).substr(2, 9), entry, variant, cost: cost || entry.cost || undefined }
        ]);
        setVariantPicker(null);
    }, []);

    const removeInstance = useCallback((tempId: string) => {
        setSelection(prev => prev.filter(s => s.tempId !== tempId));
    }, []);

    const handleConfirmMultiSelect = useCallback(() => {
        if (onMultiSelect) {
            onMultiSelect(selection.map(s => ({ entry: s.entry, variant: s.variant, cost: s.cost })));
            setSelection([]);
        }
    }, [onMultiSelect, selection]);

    return {
        selection,
        variantPicker,
        setVariantPicker,
        toggleSelection,
        addInstanceWithVariant,
        removeInstance,
        handleConfirmMultiSelect
    };
};

import { supabase } from './supabase';
import { AttributePreset } from '../types/system';
import { ErrorService } from './ErrorService';
import { TABLE_ATTRIBUTE_PRESETS } from '../constants/db';

export const AttributeService = {
    /**
     * List all available attribute presets
     */
    async listAttributePresets(): Promise<AttributePreset[] | null> {
        const { data, error } = await supabase
            .from(TABLE_ATTRIBUTE_PRESETS)
            .select('*')
            .order('is_official', { ascending: false })
            .order('name', { ascending: true });

        if (error) {
            ErrorService.handleError(error, { context: 'AttributeService.listAttributePresets' });
            return null;
        }

        // Map DB snake_case to TS camelCase if needed (though here it seems we use it directly or it was already mapped)
        // Let's ensure mapping for consistency
        return (data || []).map(p => ({
            id: p.id,
            name: p.name,
            description: p.description,
            hasSecondary: p.has_secondary,
            structure: p.structure,
            isOfficial: p.is_official
        }));
    },

    /**
     * Save a new attribute preset
     */
    async saveAttributePreset(name: string, description: string, structure: any, hasSecondary: boolean): Promise<boolean> {
        const { error } = await supabase
            .from(TABLE_ATTRIBUTE_PRESETS)
            .insert([{
                name,
                description,
                structure,
                has_secondary: hasSecondary,
                is_official: false
            }]);

        if (error) {
            ErrorService.handleError(error, { context: 'AttributeService.saveAttributePreset', userMessage: "Impossible de sauvegarder le preset." });
            return false;
        }
        return true;
    },

    /**
     * Delete an attribute preset (only if not official)
     */
    async deleteAttributePreset(id: string): Promise<boolean> {
        const { error } = await supabase
            .from(TABLE_ATTRIBUTE_PRESETS)
            .delete()
            .eq('id', id)
            .eq('is_official', false); // Safety check

        if (error) {
            ErrorService.handleError(error, { context: 'AttributeService.deleteAttributePreset', userMessage: "Impossible de supprimer le preset." });
            return false;
        }
        return true;
    },

    /**
     * Update an attribute preset metadata
     */
    async updateAttributePreset(id: string, updates: { name?: string; description?: string }): Promise<boolean> {
        // Map camelCase to snake_case if needed (none here as name/description are same)
        const { error } = await supabase
            .from(TABLE_ATTRIBUTE_PRESETS)
            .update(updates)
            .eq('id', id);

        if (error) {
            ErrorService.handleError(error, { context: 'AttributeService.updateAttributePreset', userMessage: "Impossible de mettre ├á jour le preset." });
            return false;
        }
        return true;
    }
};

import { describe, it, expect, vi, beforeEach } from 'vitest';
