    }
}));

// We will use a "fake" IndexedDB implementation for OfflineStorageService logic
// since idb-keyval uses browser APIs not available in Node easily without setup.
// We'll mock the module 'idb-keyval' itself.
const mockStore = new Map<string, any>();

vi.mock('idb-keyval', () => ({
    get: vi.fn((key) => Promise.resolve(mockStore.get(key as string))),
    set: vi.fn((key, val) => {
        mockStore.set(key as string, val);
        return Promise.resolve();
    }),
    entries: vi.fn(() => Promise.resolve(Array.from(mockStore.entries()))),
    del: vi.fn((key) => {
        mockStore.delete(key as string);
        return Promise.resolve();
    })
}));

describe('Integration: CampaignService & OfflineStorage', () => {

    beforeEach(() => {
        vi.clearAllMocks();
        mockStore.clear();
    });

    it('should save loaded campaign to offline cache', async () => {
        const campaignId = 'camp-123';
        const mockDbSetting = {
            id: campaignId,
            name: 'Test Campaign',
            version: '1.0.0',
            last_updated: new Date().toISOString(),
            configurations: { ...defaultRules.configurations },
            definitions: { ...defaultRules.definitions },
            is_public: false,
            is_archived: false,
            show_metadata_to_players: true
        };

        const mockLibraries = {
            traits: [],
            skills: [],
            specializations: [],
            backgrounds: [],
            counters: []
        };

        // 1. Mock Database Response
        (DatabaseService.fetchOne as any).mockResolvedValue(mockDbSetting);
        (LibraryService.loadLibraries as any).mockResolvedValue(mockLibraries);

        // 2. Load Setting via CampaignService
        const setting = await CampaignService.loadSetting(campaignId);
        expect(setting).not.toBeNull();
        expect(setting?.settingId).toBe(campaignId);

        // 3. Manually trigger save to cache (usually done in RulesLoader or UI, but we test the Service interop here)
        // In the real app, RulesLoader calls CampaignService.loadSetting check then OfflineStorageService.saveRules.
        // Let's simulate that flow.

        if (setting) {
            await OfflineStorageService.saveRules(setting);
        }

        // 4. Verify Cache Content
        // Check "active" cache
        const activeRules = await OfflineStorageService.getActiveRules();
        expect(activeRules).toEqual(setting);
        expect(mockStore.get('rpg-rules-cache')).toBeDefined();

        // Check "specific" cache
        const specificRules = await OfflineStorageService.getRulesBySettingId(campaignId);
        expect(specificRules).toEqual(setting);
        expect(mockStore.get(`rpg-rules-${campaignId}`)).toBeDefined();
    });

    it('should retrieve campaign from offline cache when explicitly requested', async () => {
        const campaignId = 'offline-camp-456';
        const cachedRules: RulesData = {
            ...defaultRules,
            settingId: campaignId,
            settingName: 'Offline Campaign',
            version: '2.0.0'
        };

        // 1. Seed Cache
        await OfflineStorageService.saveRules(cachedRules);

        // 2. Retrieve from Cache
        const retrieved = await OfflineStorageService.getRulesBySettingId(campaignId);

        expect(retrieved).not.toBeNull();
        expect(retrieved?.settingName).toBe('Offline Campaign');
    });

    it('should list cached campaigns for offline switching', async () => {
        const c1: RulesData = { ...defaultRules, settingId: 'c1', settingName: 'Campaign One', version: '1.0' };
        const c2: RulesData = { ...defaultRules, settingId: 'c2', settingName: 'Campaign Two', version: '1.1' };

        await OfflineStorageService.saveRules(c1);
        await OfflineStorageService.saveRules(c2);

        const list = await OfflineStorageService.listCachedCampaigns();

        expect(list).toHaveLength(2);
        expect(list).toContainEqual({ id: 'c1', name: 'Campaign One', version: '1.0' });
        expect(list).toContainEqual({ id: 'c2', name: 'Campaign Two', version: '1.1' });
    });

    it('should handle updates: new fetch should overwrite cache', async () => {
        const campaignId = 'update-test';

        // 1. Initial State (Old Version in Cache)
        const oldRules: RulesData = { ...defaultRules, settingId: campaignId, version: '1.0' };
        await OfflineStorageService.saveRules(oldRules);

        // 2. New Version from DB
        const newDbSetting = {
            id: campaignId,
            name: 'Updated Campaign',
            version: '2.0',
            last_updated: new Date().toISOString(),
            configurations: { ...defaultRules.configurations },
            definitions: { ...defaultRules.definitions },
            is_public: true
        };
        (DatabaseService.fetchOne as any).mockResolvedValue(newDbSetting);
        (LibraryService.loadLibraries as any).mockResolvedValue({ traits: [], skills: [], specializations: [], backgrounds: [], counters: [] });

        // 3. Load & Save
        const newRules = await CampaignService.loadSetting(campaignId);
        expect(newRules).not.toBeNull();
        if (newRules) await OfflineStorageService.saveRules(newRules);

        // 4. Verify Cache Updated
        const cached = await OfflineStorageService.getRulesBySettingId(campaignId);
        expect(cached?.version).toBe('2.0');
    });
});

import { supabase } from './supabase';
import { DatabaseService } from './DatabaseService';
import { GameSetting, RulesData, GameSettingSummary } from '../types/rules';
export type { GameSetting, RulesData, GameSettingSummary };
import { LibraryService } from './LibraryService';
import { logger } from '../utils/logger';
import { ErrorService } from './ErrorService';
import { migrateRulesToV2 } from '../utils/migrations';
import { RulesDataSchema } from '../utils/validation/rulesSchema';
import { TABLE_GAME_SETTINGS, TABLE_LIBRARIES_TRAITS, TABLE_LIBRARIES_SKILLS, TABLE_LIBRARIES_SPECIALIZATIONS, TABLE_LIBRARIES_BACKGROUNDS, TABLE_LIBRARIES_COUNTERS } from '../constants/db';
import { reconcileRulesWithLibraries } from '../utils/reconcilers/campaignReconciler';

// Interface de la base de donn├®es (table game_settings)
interface DBGameSetting {
    id: string;
    name: string;
    version: string;
    last_updated: string;
    configurations: RulesData['configurations']; // JSONB
    definitions: RulesData['definitions']; // JSONB
    is_public: boolean;
    is_archived: boolean;
    description: string | null;
    welcome_message: string | null;
    show_metadata_to_players: boolean;
}

export const CampaignService = {

    /**
     * List all available settings (campagnes)
     */
    async listSettings(): Promise<GameSettingSummary[] | null> {
        return await DatabaseService.fetchAll<GameSettingSummary>(TABLE_GAME_SETTINGS, {
            select: 'id, name, version, last_updated, is_public, is_archived',
            order: { column: 'last_updated', ascending: false }
        }, 'CampaignService.listSettings');
    },

    /**
     * List public settings available for players
     */
    async listPublicSettings(): Promise<GameSettingSummary[]> {
        return await DatabaseService.fetchAll<GameSettingSummary>(
            TABLE_GAME_SETTINGS,
            {
                select: 'id, name, version, last_updated, is_public',
                eq: { is_public: true },
                order: { column: 'last_updated', ascending: false }
            },
            'CampaignService.listPublicSettings'
        ) || [];
    },

    /**
     * Duplicate an existing setting
     */
    async duplicateSetting(id: string, newName: string): Promise<string | null> {
        const originalSetting = await CampaignService.loadSetting(id);

        if (!originalSetting) {
            ErrorService.handleError(new Error(`Setting with ID ${id} not found for duplication.`), {
                context: 'CampaignService.duplicateSetting',
                userMessage: "La campagne originale n'a pas ├®t├® trouv├®e."
            });
            return null;
        }

        // Prepare rules for the new setting
        const newRules: Partial<RulesData> = {
            version: originalSetting.version,
            configurations: originalSetting.configurations,
            definitions: originalSetting.definitions,
            libraries: originalSetting.libraries,
            // Do not copy settingId, settingName, lastUpdated, is_public as they are specific to the original
        };

        // Create the new setting
        const newSettingId = await CampaignService.createSetting(newName, newRules);

        if (!newSettingId) {
            ErrorService.handleError(new Error(`Failed to create new setting for duplication of ${id}.`), {
                context: 'CampaignService.duplicateSetting',
                userMessage: "├ëchec de la cr├®ation de la nouvelle campagne."
            });
            return null;
        }

        return newSettingId;
    },

    /**
     * Create a new empty setting
     */
    async createSetting(name: string, initialRules: Partial<RulesData>): Promise<string | null> {
        // Prepare JSONBs
        const configurations = initialRules.configurations || {};
        const definitions = initialRules.definitions || {};

        const inserted = await DatabaseService.insert<{ id: string }>(TABLE_GAME_SETTINGS, {
            name,
            version: initialRules.version || '1.0.0',
            configurations,
            definitions,
            is_public: false
        }, 'CampaignService.createSetting');

        if (!inserted) return null;

        const result = Array.isArray(inserted) ? inserted[0] : inserted;
        const settingId = result.id;

        // Persist Libraries if present
        if (initialRules.libraries) {
            await LibraryService.persistInitialLibraries(settingId, initialRules);
        }

        return settingId;
    },

    /**
     * Load a full setting by ID
     */
    async loadSetting(id: string): Promise<RulesData | null> {
        if (!id || id === 'orphan') {
            return null;
        }

        try {
            // 1. Fetch Main Config
            const settingData = await DatabaseService.fetchOne<DBGameSetting>(TABLE_GAME_SETTINGS, id, 'CampaignService.loadSetting');

            if (!settingData) {
                return null;
            }

            // 2. Load Libraries
            const libraries = await LibraryService.loadLibraries(id);

            const rulesRaw = migrateRulesToV2({
                version: settingData.version,
                lastUpdated: new Date(settingData.last_updated).getTime(),
                configurations: settingData.configurations,
                definitions: settingData.definitions,
                theme: (settingData.configurations as Record<string, unknown>)?.theme as { creationColor: string; xpColor: string } || { creationColor: "#000", xpColor: "#000" },
                libraries: libraries
            });

            // Validate with Zod
            const validationResult = RulesDataSchema.safeParse(rulesRaw);

            if (!validationResult.success) {
                logger.warn("[CampaignService] Validation Details:", JSON.stringify(validationResult.error.flatten(), null, 2));
                ErrorService.handleError(new Error("Donn├®es de campagne non conformes"), {
                    context: 'CampaignService.loadSetting',
                    userMessage: "Certaines donn├®es de la campagne ne respectent pas le sch├®ma attendu (voir console)."
                });
                return null; // Don't proceed with invalid data
            }

            const rules = validationResult.data as RulesData;

            // Inject setting metadata
            rules.settingId = id;
            rules.settingName = settingData.name;
            rules.description = settingData.description || undefined;
            rules.welcomeMessage = settingData.welcome_message || undefined;
            rules.showMetadataToPlayers = settingData.show_metadata_to_players;
            rules.isArchived = settingData.is_archived;
            rules.source = 'database';

            // 3. Reconcile with libraries
            return reconcileRulesWithLibraries(rules, libraries);
        } catch (e) {
            ErrorService.handleError(e, { context: 'CampaignService.loadSetting', userMessage: "Erreur critique lors du chargement de la campagne." });
            return null;
        }
    },

    /**
     * Save/Update a setting
     * This is complex because we must save the root AND the libraries
     */
    async saveSetting(id: string, rules: RulesData, name?: string): Promise<{ success: boolean; message?: string }> {

        // 1. Update Root
        const rootUpdate: Partial<DBGameSetting> = {
            version: rules.version,
            last_updated: new Date().toISOString(),
            configurations: rules.configurations,
            definitions: rules.definitions,
            description: rules.description || null,
            welcome_message: rules.welcomeMessage || null,
            show_metadata_to_players: !!rules.showMetadataToPlayers,
            is_archived: !!rules.isArchived
        };
        if (name) rootUpdate.name = name;

        const success = await DatabaseService.update(TABLE_GAME_SETTINGS, id, rootUpdate, 'CampaignService.saveSetting');

        if (!success) {
            return { success: false, message: "Erreur MAJ Root" };
        }

        // 2. Synchronize Libraries
        try {
            await LibraryService.syncLibraries(id, rules);
            return { success: true };
        } catch (libError) {
            ErrorService.handleError(libError, { context: 'CampaignService.saveSetting', userMessage: "Erreur sauvegarde biblioth├¿ques." });
            return { success: false, message: `Erreur Biblioth├¿ques: ${(libError as Error).message}` };
        }
    },

    /**
     * Delete a setting and all its related data
     */
    async deleteSetting(id: string): Promise<boolean> {
        // Delete libraries first (manual cascade just in case DB cascade isn't set)
        const results = await Promise.allSettled([
            DatabaseService.deleteBy(TABLE_LIBRARIES_TRAITS, 'setting_id', id, 'CampaignService.deleteSetting.traits'),
            DatabaseService.deleteBy(TABLE_LIBRARIES_SKILLS, 'setting_id', id, 'CampaignService.deleteSetting.skills'),
            DatabaseService.deleteBy(TABLE_LIBRARIES_SPECIALIZATIONS, 'setting_id', id, 'CampaignService.deleteSetting.specs'),
            DatabaseService.deleteBy(TABLE_LIBRARIES_BACKGROUNDS, 'setting_id', id, 'CampaignService.deleteSetting.bgs'),
            DatabaseService.deleteBy(TABLE_LIBRARIES_COUNTERS, 'setting_id', id, 'CampaignService.deleteSetting.counters')
        ]);

        const failures = results.filter(r => r.status === 'rejected');
        if (failures.length > 0) {
            ErrorService.handleError(new Error(`${failures.length} suppressions de biblioth├¿ques ├®chou├®es`), {
                context: 'CampaignService.deleteSetting'
            });
            return false;
        }

        // Delete the setting itself
        return await DatabaseService.delete('game_settings', id, 'CampaignService.deleteSetting');
    },

    /**
     * Toggle public/private visibility
     */
    async togglePublic(id: string, isPublic: boolean): Promise<boolean> {
        return await DatabaseService.update(TABLE_GAME_SETTINGS, id, { is_public: isPublic }, 'CampaignService.togglePublic');
    },

    /**
     * Set archived status
     */
    async setArchived(id: string, isArchived: boolean): Promise<boolean> {
        return await DatabaseService.update(TABLE_GAME_SETTINGS, id, { is_archived: isArchived }, 'CampaignService.setArchived');
    },

    /**
     * Manual schema check for a setting
     */
    async checkSchema(id: string): Promise<boolean> {
        try {
            const rules = await CampaignService.loadSetting(id);
            if (!rules) return false;
            // loadSetting already performs Zod validation
            return true;
        } catch (e) {
            return false;
        }
    }

}

/**
 * CharacterSyncService
 * 
 * Handles synchronization of player character sheets to Supabase.
 * Players can sync their sheets manually; Admin can read them.
 */

import { DatabaseService } from './DatabaseService';
import { CharacterSheetData } from '../types/character';

import { ImageSyncResolver } from './ImageSyncResolver';
import { ErrorService } from './ErrorService';

// Types for sync operations
export interface SyncedCharacter {
    id: string;
    setting_id: string;
    character_name: string;
    player_name: string;
    data: CharacterSheetData;
    last_synced: string;
    created_at: string;
}

export interface SyncedCharacterSummary {
    id: string;
    setting_id: string;
    character_name: string;
    player_name: string;
    last_synced: string;
    data_size?: number; // Real size in bytes from view_characters_summary
}

export interface CharacterHistoryEntry {
    id: string;
    character_id: string;
    data: CharacterSheetData;
    metadata: {
        player_name: string;
        character_name: string;
        last_synced: string;
    };
    archived_at: string;
    version_reason: 'manual' | 'auto_1h';
}

export interface SyncResult {
    success: boolean;
    syncId?: string;
    hash?: string;
    error?: string;
}

// Assuming SyncInfo is part of CharacterSheetData, or a sub-interface.
// The instruction implies adding this field to the SyncInfo structure.
// For the purpose of this file, we'll assume CharacterSheetData's syncInfo property
// will now include mjMessage. The actual type definition for SyncInfo would be in '../types/character'.
// The provided snippet seems to be an attempt to show the *content* of the SyncInfo type.
// We will not add a new type definition here, but acknowledge the change in the external type.

export const CharacterSyncService = {

    /**
     * Generate a short digital signature of the character data.
     * Used for conflict detection and 'dirty' checking.
     */
    generateDataHash(data: CharacterSheetData): string {
        try {
            // We ignore volatile fields for the hash
            const { syncInfo: _s, appLogs: _a, xpLogs: _x, _rulesVersion: _r, ...stableData } = data;

            // Fast hashing via string manipulation
            const str = JSON.stringify(stableData);
            let hash = 0;
            for (let i = 0; i < str.length; i++) {
                const char = str.charCodeAt(i);
                hash = ((hash << 5) - hash) + char;
                hash = hash & hash; // Convert to 32bit integer
            }
            return Math.abs(hash).toString(36);
        } catch (e) {
            return "unknown";
        }
    },

    /**
     * Sync a character sheet to the database.

     * Uses upsert: creates if new, updates if exists (same setting/player/character combo).
     */
    async syncCharacter(
        settingId: string,
        playerName: string,
        characterName: string,
        data: CharacterSheetData,
        mode: 'manual' | 'auto' = 'manual'
    ): Promise<SyncResult> {
        try {
            // Step 0: Inject sync mode
            data.syncInfo = { ...data.syncInfo, syncMode: mode };

            // Step 1: Resolve and compress images for portable sync
            const dataToStore = await ImageSyncResolver.resolveImagesForSync(data);

            const result = await DatabaseService.upsert<{ id: string }>(
                'characters',
                {
                    setting_id: (settingId === 'orphan' || !settingId) ? null : settingId,
                    player_name: playerName.trim(),
                    character_name: characterName.trim(),
                    data: dataToStore,
                    last_synced: new Date().toISOString()
                },
                {
                    onConflict: 'setting_id,character_name,player_name',
                    ignoreDuplicates: false
                },
                'CharacterSyncService.syncCharacter'
            );

            if (!result) {
                return { success: false, error: "Erreur de synchronisation (DatabaseService)." };
            }

            return {
                success: true,
                syncId: result.id,
                hash: this.generateDataHash(data)
            };
        } catch (e) {
            ErrorService.handleError(e, { context: 'CharacterSyncService.syncCharacter' });
            return { success: false, error: (e as Error).message };
        }
    },

    /**
     * Get all characters synced by a specific player (for cloud loading).
     */
    async getCharactersByPlayerName(playerName: string): Promise<SyncedCharacterSummary[]> {
        return await DatabaseService.fetchAll<SyncedCharacterSummary>(
            'view_characters_summary',
            {
                select: 'id, character_name, player_name, last_synced, setting_id, data_size',
                eq: { player_name: playerName.trim() },
                order: { column: 'last_synced', ascending: false }
            },
            'CharacterSyncService.getCharactersByPlayerName'
        );
    },

    /**
     * Get ALL characters across all campaigns (for Admin Master List).
     */
    async getAllCharacters(): Promise<SyncedCharacterSummary[]> {
        return await DatabaseService.fetchAll<SyncedCharacterSummary>(
            'view_characters_summary',
            {
                select: 'id, character_name, player_name, last_synced, setting_id, data_size',
                order: { column: 'last_synced', ascending: false }
            },
            'CharacterSyncService.getAllCharacters'
        );
    },

    /**
     * Get all characters synced to a specific campaign (for Admin view).
     */
    async getCharactersBySettingId(settingId: string): Promise<SyncedCharacterSummary[]> {
        return await DatabaseService.fetchAll<SyncedCharacterSummary>(
            'view_characters_summary',
            {
                select: 'id, setting_id, character_name, player_name, last_synced, data_size',
                eq: { setting_id: settingId },
                order: { column: 'last_synced', ascending: false }
            },
            'CharacterSyncService.getCharactersBySettingId'
        );
    },

    /**
     * Get all FULL characters synced to a specific campaign (for Roster view).
     */
    async getFullCharactersBySettingId(settingId: string): Promise<SyncedCharacter[]> {
        return await DatabaseService.fetchAll<SyncedCharacter>(
            'characters',
            {
                select: '*',
                eq: { setting_id: settingId },
                order: { column: 'last_synced', ascending: false }
            },
            'CharacterSyncService.getFullCharactersBySettingId'
        );
    },

    /**
     * Get a single character by ID (for Admin or Player detail view).
     */
    async getCharacterById(id: string): Promise<SyncedCharacter | null> {
        return await DatabaseService.fetchOne<SyncedCharacter>(
            'characters',
            id,
            'CharacterSyncService.getCharacterById'
        );
    },

    /**
     * Update character data directly (MJ/Admin).
     * Used when the MJ makes manual modifications and wants to push them.
     */
    async updateCharacterData(id: string, data: CharacterSheetData): Promise<boolean> {
        try {
            // Re-compress images for storage
            const dataToStore = await ImageSyncResolver.resolveImagesForSync(data);

            return await DatabaseService.update(
                'characters',
                id,
                {
                    data: dataToStore,
                    last_synced: new Date().toISOString()
                },
                'CharacterSyncService.updateCharacterData'
            );
        } catch (e) {
            ErrorService.handleError(e, { context: 'CharacterSyncService.updateCharacterData' });
            return false;
        }
    },

    /**
     * Signal to the player that a manual update has been made by the MJ.
     * This updates the timestamp AND can inject a specific message.
     */
    async requestForceUpdate(id: string, message?: string): Promise<boolean> {
        try {
            // We need to fetch the character first to avoid wiping data if we just update the timestamp
            const character = await this.getCharacterById(id);
            if (!character) return false;

            const updatedData: CharacterSheetData = {
                ...character.data,
                syncInfo: {
                    ...(character.data.syncInfo || {}),
                    mjMessage: message,
                    lastSynced: Date.now()
                }
            };

            return await this.updateCharacterData(id, updatedData);
        } catch (e) {
            ErrorService.handleError(e, { context: 'CharacterSyncService.requestForceUpdate' });
            return false;
        }
    },

    /**
     * Delete a synced character (Admin only, if needed later).
     */
    async deleteCharacter(id: string): Promise<boolean> {
        return await DatabaseService.delete(
            'characters',
            id,
            'CharacterSyncService.deleteCharacter'
        );
    },

    /**
     * Check if character sync table exists and is accessible.
     */
    async checkSyncAvailable(): Promise<boolean> {
        return await DatabaseService.checkAvailable('characters');
    },

    async processImages(obj: any, action: 'compress' | 'decompress'): Promise<any> {
        return action === 'compress'
            ? ImageSyncResolver.resolveImagesForSync(obj)
            : ImageSyncResolver.injectImagesAfterSync(obj);
    },

    /**
     * Get historical versions for a character.
     */
    async getCharacterHistory(characterId: string): Promise<CharacterHistoryEntry[]> {
        return await DatabaseService.fetchAll<CharacterHistoryEntry>(
            'characters_history',
            {
                select: '*',
                eq: { character_id: characterId },
                order: { column: 'archived_at', ascending: false }
            },
            'CharacterSyncService.getCharacterHistory'
        );
    }
};

import { supabase } from './supabase';
import { ErrorService } from './ErrorService';

/**
 * Generic Database Service to abstract Supabase calls.
 * Provides consistent error handling and typing.
 */
export const DatabaseService = {

    /**
     * Execute a Supabase query builder and handle errors automatically.
     * Useful for complex queries constructed outside.
     */
    async execute<T>(
        queryPromise: PromiseLike<{ data: T | null; error: any }>,
        context: string,
        userMessage: string
    ): Promise<T | null> {
        // Supabase client does not throw, it returns error object.
        // However, if the promise rejects (network failure etc), we catch it.
        try {
            const { data, error } = await queryPromise;

            if (error) {
                // Determine if it's a "No rows found" error which might not be critical depending on context
                // But generally, if the caller expected data, it's an error.
                // The caller can check for null data.
                ErrorService.handleError(error, { context, userMessage });
                return null;
            }

            return data;
        } catch (e) {
            ErrorService.handleError(e, { context, userMessage });
            return null;
        }
    },

    /**
     * Fetch a single record by ID.
     */
    async fetchOne<T>(
        table: string,
        id: string,
        context: string = `DatabaseService.fetchOne(${table})`
    ): Promise<T | null> {
        const { data, error } = await supabase
            .from(table)
            .select('*')
            .eq('id', id)
            .single();

        if (error) {
            // PGRST116 means no rows returned for .single(), which is valid "null" result mostly
            if (error.code === 'PGRST116') return null;

            ErrorService.handleError(error, { context, userMessage: "Erreur lors de la r├®cup├®ration de la donn├®e." });
            return null;
        }
        return data;
    },

    /**
     * Fetch all records matching a simple equality filter.
     */
    async fetchAll<T>(
        table: string,
        query: {
            eq?: Record<string, any>,
            or?: string,
            select?: string,
            order?: { column: string, ascending?: boolean },
            limit?: number
        } = {},
        context: string = `DatabaseService.fetchAll(${table})`
    ): Promise<T[]> {
        let builder = supabase.from(table).select(query.select || '*');

        if (query.or) {
            builder = builder.or(query.or);
        }

        if (query.eq) {
            Object.entries(query.eq).forEach(([key, value]) => {
                if (value !== undefined && value !== null) {
                    builder = builder.eq(key, value);
                } else if (value === null) {
                    builder = builder.is(key, null);
                }
            });
        }

        if (query.order) {
            builder = builder.order(query.order.column, { ascending: query.order.ascending ?? true });
        }

        if (query.limit) {
            builder = builder.limit(query.limit);
        }

        const { data, error } = await builder;

        if (error) {
            ErrorService.handleError(error, { context, userMessage: "Erreur lors de la liste des donn├®es." });
            return [];
        }

        return data as T[];
    },

    /**
     * Insert a record (or multiple).
     * @returns The inserted data (single object or array depending on input).
     */
    async insert<T>(
        table: string,
        data: any | any[],
        context: string = `DatabaseService.insert(${table})`
    ): Promise<T | T[] | null> {
        const isArray = Array.isArray(data);

        let resultPromise;
        if (isArray) {
            resultPromise = supabase.from(table).insert(data).select();
        } else {
            resultPromise = supabase.from(table).insert(data).select().single();
        }

        const { data: inserted, error } = await resultPromise;

        if (error) {
            ErrorService.handleError(error, { context, userMessage: "Erreur lors de la cr├®ation." });
            return null;
        }
        return inserted as T | T[];
    },

    /**
     * Update a record by ID.
     */
    async update<T>(
        table: string,
        id: string,
        data: Partial<T>,
        context: string = `DatabaseService.update(${table})`
    ): Promise<boolean> {
        const { error } = await supabase
            .from(table)
            .update(data)
            .eq('id', id);

        if (error) {
            ErrorService.handleError(error, { context, userMessage: "Erreur lors de la mise ├á jour." });
            return false;
        }
        return true;
    },

    /**
     * Delete a record by ID.
     */
    async delete(
        table: string,
        id: string,
        context: string = `DatabaseService.delete(${table})`
    ): Promise<boolean> {
        const { error } = await supabase
            .from(table)
            .delete()
            .eq('id', id);

        if (error) {
            ErrorService.handleError(error, { context, userMessage: "Erreur lors de la suppression." });
            return false;
        }
        return true;
    },

    /**
     * Delete multiple records by a specific column filter (e.g. setting_id)
     */
    async deleteBy(
        table: string,
        column: string,
        value: string,
        context: string = `DatabaseService.deleteBy(${table})`
    ): Promise<boolean> {
        const { error } = await supabase
            .from(table)
            .delete()
            .eq(column, value);

        if (error) {
            ErrorService.handleError(error, { context, userMessage: "Erreur lors du nettoyage des donn├®es." });
            return false;
        }
        return true;
    },

    /**
     * Upsert a record.
     */
    async upsert<T>(
        table: string,
        data: Partial<T> | any, // Use any for raw data if T is complex, but Partial<T> is preferred
        options: { onConflict?: string, ignoreDuplicates?: boolean } = {},
        context: string = `DatabaseService.upsert(${table})`
    ): Promise<T | null> {
        const { data: result, error } = await supabase
            .from(table)
            .upsert(data, options)
            .select()
            .single();

        if (error) {
            ErrorService.handleError(error, { context, userMessage: "Erreur lors de la synchronisation (upsert)." });
            throw error;
        }
        return result as T;
    },

    /**
     * Check if a table is accessible (HEAD request).
     */
    async checkAvailable(table: string): Promise<boolean> {
        try {
            const { error } = await supabase
                .from(table)
                .select('id', { count: 'exact', head: true });
            return !error;
        } catch {
            return false;
        }
    }
};

export type ErrorSeverity = 'info' | 'warning' | 'error' | 'critical';

export interface ErrorLogOptions {
    context?: string;      // Ex: "CharacterSync", "LibraryLoader"
    userMessage?: string;  // Message friendly pour l'utilisateur
    silent?: boolean;      // Si true, log seulement en console, pas de notification
    error?: unknown;       // L'erreur originale
}

type NotifyFn = (
    message: string,
    type?: 'success' | 'danger' | 'info',
    category?: 'sheet' | 'settings' | 'both',
    deduplicationId?: string
) => void;

export class ErrorService {
    private static notifier: NotifyFn | null = null;

    /**
     * Injecte la fonction de notification (depuis NotificationContext ou CharacterContext)
     */
    static init(notifyFn: NotifyFn) {
        this.notifier = notifyFn;
    }

    /**
     * Log une erreur et notifie l'utilisateur si n├®cessaire
     */
    static handleError(error: unknown, options: ErrorLogOptions = {}) {
        const { context = 'General', userMessage, silent = false } = options;

        // Extraction du message d'erreur
        const technicalMessage = error instanceof Error
            ? error.message
            : typeof error === 'string'
                ? error
                : JSON.stringify(error);

        // 1. Console Log enrichi
        const isForbidden = technicalMessage.includes('403') || (error as any)?.status === 403 || (error as any)?.code === '42501';

        const timestamp = new Date().toLocaleTimeString();
        // eslint-disable-next-line no-console
        console.groupCollapsed(`%c[${timestamp}] [${context}] Error`, 'color: red; font-weight: bold;');
        console.error('Original Error:', error);
        // eslint-disable-next-line no-console
        if (userMessage) console.log('User Message:', userMessage);
        if (isForbidden) {
            console.warn('­ƒÆí Tip: This 403 error might be due to missing "admin" role in your Supabase app_metadata.');
        }
        // eslint-disable-next-line no-console
        console.groupEnd();

        // 2. Notification Utilisateur
        if (!silent && this.notifier) {
            let displayMsg = userMessage || `Erreur (${context}): ${technicalMessage}`;
            if (isForbidden && !userMessage) {
                displayMsg = `Acc├¿s refus├® (${context}). V├®rifiez vos droits administrateur.`;
            } else if (isForbidden) {
                displayMsg += " (V├®rifiez vos droits administrateur)";
            }
            // On utilise 'danger' pour les erreurs
            // On log dans 'both' pour ├¬tre s├╗r que ce soit visible dans l'historique global
            this.notifier(displayMsg, 'danger', 'both');
        }
    }

    /**
     * Wrapper pour les blocs try/catch
     */
    static async tryCatch<T>(
        promise: Promise<T>,
        options: ErrorLogOptions
    ): Promise<T | null> {
        try {
            return await promise;
        } catch (error) {
            this.handleError(error, options);
            return null;
        }
    }
}

/**
 * ImageCompressionService
 * 
 * Compresses images for efficient storage in database.
 * - Step 1: JPEG compression + resize (preserving aspect ratio)
 * - Step 2: gzip compression of base64 string
 * Total gain: 70-85% size reduction
 */

import pako from 'pako';
import { ErrorService } from './ErrorService';

export const GZIP_MARKER = 'GZIP:';

/**
 * Image compression constants
 * Quality range: 0-1 (0 = worst, 1 = best)
 * 0.8 = good balance between quality and size
 */
const IMAGE_COMPRESSION_CONFIG = {
    // Standard compression for avatars/thumbnails
    STANDARD: {
        quality: 0.5,
        maxWidth: 1200,
        format: 'webp' as const
    },

    // Full resolution for documents/detailed images
    FULL: {
        quality: 0.5,
        maxWidth: 1920,
        format: 'webp' as const
    }
};

export interface CompressionResult {
    compressed: string;
    originalSize: number;
    compressedSize: number;
    compressionRatio: number;
}

export const ImageCompressionService = {

    /**
     * Compress an image (base64) with WebP quality reduction and resize.
     * Preserves aspect ratio - only resizes if width > maxWidth.
     * 
     * @param base64 - Image in base64 format (data:image/...)
     * @param quality - WebP quality (0-1)
     * @param maxWidth - Maximum width in pixels
     * @returns Compressed base64 image
     */
    async compressImage(
        base64: string,
        quality: number = IMAGE_COMPRESSION_CONFIG.STANDARD.quality,
        maxWidth: number = IMAGE_COMPRESSION_CONFIG.STANDARD.maxWidth
    ): Promise<string> {
        return new Promise((resolve, reject) => {
            // Create image element
            const img = new Image();

            img.onload = () => {
                try {
                    // Calculate new dimensions preserving aspect ratio
                    let width = img.width;
                    let height = img.height;

                    if (width > maxWidth) {
                        const ratio = maxWidth / width;
                        width = maxWidth;
                        height = Math.round(height * ratio);
                    }

                    // Create canvas
                    const canvas = document.createElement('canvas');
                    canvas.width = width;
                    canvas.height = height;

                    // Draw and compress
                    const ctx = canvas.getContext('2d');
                    if (!ctx) {
                        reject(new Error('Failed to get canvas context'));
                        return;
                    }

                    ctx.drawImage(img, 0, 0, width, height);

                    // Convert to WebP with quality setting
                    // Fallback to JPEG if WebP is not supported (older browsers)
                    const compressedBase64 = canvas.toDataURL('image/webp', quality);

                    // Basic check: if it turned into png (default fallback), force jpeg
                    if (compressedBase64.startsWith('data:image/png')) {
                        const jpegFallback = canvas.toDataURL('image/jpeg', quality);
                        resolve(jpegFallback);
                    } else {
                        resolve(compressedBase64);
                    }

                } catch (e) {
                    reject(e);
                }
            };

            img.onerror = () => {
                reject(new Error('Failed to load image'));
            };

            img.src = base64;
        });
    },

    /**
     * Compress a base64 string using gzip (lossless).
     * 
     * @param base64 - Base64 string to compress
     * @returns Compressed base64 string with marker
     */
    compressBase64(base64: string): string {
        try {
            // WebP is already highly compressed. GZIP might add overhead or gain little.
            // But we keep it for now as "double safety" especially for the Base64 string overhead.

            // Remove data URL prefix if present
            const base64Data = base64.includes(',')
                ? base64.split(',')[1]
                : base64;

            // Convert base64 to binary
            const binaryString = atob(base64Data);
            const bytes = new Uint8Array(binaryString.length);
            for (let i = 0; i < binaryString.length; i++) {
                bytes[i] = binaryString.charCodeAt(i);
            }

            // Compress with pako (gzip)
            const compressed = pako.gzip(bytes);

            // Process in chunks to avoid call stack overflow on large images
            let binaryStr = '';
            const chunkSize = 8192;
            for (let i = 0; i < compressed.length; i += chunkSize) {
                binaryStr += String.fromCharCode(...compressed.subarray(i, i + chunkSize));
            }

            // Convert back to base64
            const compressedBase64 = btoa(binaryStr);

            // Add marker to identify compressed data
            return `${GZIP_MARKER}${compressedBase64}`;
        } catch (e) {
            ErrorService.handleError(e, { context: 'ImageCompressionService.compressBase64', silent: true });
            return base64; // Return original on error
        }
    },

    /**
     * Decompress a gzip-compressed base64 string.
     * 
     * @param compressed - Compressed string with GZIP: marker
     * @returns Original base64 string
     */
    decompressBase64(compressed: string): string {
        try {
            // Check if data is compressed
            if (!compressed.startsWith(GZIP_MARKER)) {
                return compressed; // Not compressed, return as-is
            }

            // Remove marker
            const compressedData = compressed.substring(GZIP_MARKER.length);

            // Convert base64 to binary
            const binaryString = atob(compressedData);
            const bytes = new Uint8Array(binaryString.length);
            for (let i = 0; i < binaryString.length; i++) {
                bytes[i] = binaryString.charCodeAt(i);
            }

            // Decompress with pako
            const decompressed = pako.ungzip(bytes);

            // Process in chunks to avoid call stack overflow on large images
            let binaryStr = '';
            const chunkSize = 8192;
            for (let i = 0; i < decompressed.length; i += chunkSize) {
                binaryStr += String.fromCharCode(...decompressed.subarray(i, i + chunkSize));
            }

            // Convert back to base64
            const base64 = btoa(binaryStr);

            // Ensure we return a valid Data URI for images. 
            // Since this is ImageCompressionService, we mostly deal with WebP.
            return base64.startsWith('data:') ? base64 : `data:image/webp;base64,${base64}`;
        } catch (e) {
            ErrorService.handleError(e, { context: 'ImageCompressionService.decompressBase64', silent: true });
            return compressed; // Return original on error
        }
    },

    /**
     * Full compression pipeline: Image compression + gzip.
     * 
     * @param base64 - Original image base64
     * @param quality - JPEG quality (0-1)
     * @param maxWidth - Maximum width
     * @returns Compression result with stats
     */
    async compressFull(
        base64: string,
        quality: number = IMAGE_COMPRESSION_CONFIG.FULL.quality,
        maxWidth: number = IMAGE_COMPRESSION_CONFIG.FULL.maxWidth
    ): Promise<CompressionResult> {
        const originalSize = base64.length;

        // Step 1: Image compression
        const imageCompressed = await this.compressImage(base64, quality, maxWidth);

        // Step 2: gzip compression
        const fullyCompressed = this.compressBase64(imageCompressed);

        const compressedSize = fullyCompressed.length;
        const compressionRatio = ((originalSize - compressedSize) / originalSize) * 100;

        return {
            compressed: fullyCompressed,
            originalSize,
            compressedSize,
            compressionRatio
        };
    },

    /**
     * Decompress data from full compression pipeline.
     * 
     * @param compressed - Fully compressed data
     * @returns Decompressed base64 image
     */
    decompressFull(compressed: string): string {
        // Only need to decompress gzip layer
        // Image compression is lossy and permanent
        return this.decompressBase64(compressed);
    },

    /**
     * Recursively process an object to compress/decompress image strings.
     * Moves this logic from CharacterSyncService to be reusable.
     */
    async processImages(obj: any, action: 'compress' | 'decompress'): Promise<any> {
        if (!obj || typeof obj !== 'object') return obj;

        if (Array.isArray(obj)) {
            return Promise.all(obj.map(item => this.processImages(item, action)));
        }

        const processed: any = {};
        for (const [key, value] of Object.entries(obj)) {
            if (typeof value === 'string') {
                if (action === 'compress' && value.startsWith('data:image/')) {
                    const result = await this.compressFull(value);
                    processed[key] = result.compressed;
                } else if (action === 'compress' && value.startsWith(GZIP_MARKER)) {
                    // ALREADY COMPRESSED - SKIP to avoid generation loss
                    processed[key] = value;
                } else if (action === 'decompress' && value.startsWith(GZIP_MARKER)) {
                    processed[key] = this.decompressFull(value);
                } else {
                    processed[key] = value;
                }
            } else if (typeof value === 'object') {
                processed[key] = await this.processImages(value, action);
            } else {
                processed[key] = value;
            }
        }
        return processed;
    }
};

import { getImage, saveImage, blobToBase64, base64ToBlob } from './imageDB';
import { GZIP_MARKER, ImageCompressionService } from './ImageCompressionService';
import { logger } from '../utils/logger';

/**
 * ImageSyncResolver
 * 
 * Orchestrates the conversion between local IndexedDB image references (imageId)
 * and compressed data strings used for cloud synchronization.
 */
export const ImageSyncResolver = {

    /**
     * Finds all imageId references in the data and replaces them with compressed WebP+GZIP strings.
     * This makes the character data "portable" for cloud sync.
     */
    async resolveImagesForSync(data: unknown): Promise<unknown> {
        if (!data || typeof data !== 'object' || data === null) return data;

        if (Array.isArray(data)) {
            return Promise.all(data.map(item => this.resolveImagesForSync(item)));
        }

        const obj = data as Record<string, unknown>;
        const processed: Record<string, unknown> = {};

        for (const [key, value] of Object.entries(obj)) {
            // SKIP if already compressed
            if (typeof value === 'string' && value.startsWith(GZIP_MARKER)) {
                processed[key] = value;
                continue;
            }

            // Case 1: Portrait Image ID
            if (key === 'characterImageId' && typeof value === 'string' && value.startsWith('img_')) {
                try {
                    const blob = await getImage(value);
                    if (blob) {
                        const base64 = await blobToBase64(blob);
                        const result = await ImageCompressionService.compressFull(base64);
                        processed[key] = result.compressed;
                        // Clear legacy carrier image if it exists in the same object
                        if (obj.characterImage !== undefined) processed.characterImage = '';
                    } else {
                        processed[key] = value;
                    }
                } catch (e) {
                    logger.error("[ImageSyncResolver] Failed to resolve portrait image:", e);
                    processed[key] = value;
                }
            }
            // Case 2: Grimoire Image Node (Tiptap bookImage)
            else if (key === 'type' && value === 'bookImage' && (obj.attrs as Record<string, any> | undefined)?.imageId) {
                try {
                    const attrs = obj.attrs as Record<string, any>;
                    const imageId = attrs.imageId;

                    // If imageId is already compressed, skip it
                    if (typeof imageId === 'string' && imageId.startsWith(GZIP_MARKER)) {
                        processed[key] = value;
                        continue;
                    }

                    if (typeof imageId === 'string' && imageId.startsWith('img_')) {
                        const blob = await getImage(imageId);
                        if (blob) {
                            const base64 = await blobToBase64(blob);
                            const result = await ImageCompressionService.compressFull(base64);

                            processed.type = 'bookImage';
                            processed.attrs = {
                                ...attrs,
                                imageId: result.compressed // Replace ID with compressed data for sync
                            };

                            // Copy any other node properties (content, marks, etc)
                            for (const k of Object.keys(obj)) {
                                if (k !== 'type' && k !== 'attrs') processed[k] = obj[k];
                            }
                            return processed;
                        }
                    }
                } catch (e) {
                    logger.error("[ImageSyncResolver] Failed to resolve book image:", e);
                }
                processed[key] = value;
            }
            // Case 3: Generic Base64 Image (any other field)
            else if (typeof value === 'string' && value.startsWith('data:image/')) {
                try {
                    const result = await ImageCompressionService.compressFull(value);
                    processed[key] = result.compressed;
                } catch (e) {
                    processed[key] = value;
                }
            }
            // Standard recursion
            else if (typeof value === 'object' && value !== null) {
                processed[key] = await this.resolveImagesForSync(value);
            } else {
                processed[key] = value;
            }
        }
        return processed;
    },

    /**
     * Finds all compressed image strings (GZIP:...) in the data, saves them to IndexedDB,
     * and replaces them with local imageIds.
     */
    async injectImagesAfterSync(data: unknown): Promise<unknown> {
        if (!data || typeof data !== 'object' || data === null) return data;

        if (Array.isArray(data)) {
            return Promise.all(data.map(item => this.injectImagesAfterSync(item)));
        }

        const obj = data as Record<string, unknown>;
        const processed: Record<string, unknown> = {};

        for (const [key, value] of Object.entries(obj)) {
            // Case 1: Portrait (compressed string in characterImageId field)
            if (key === 'characterImageId' && typeof value === 'string' && value.startsWith(GZIP_MARKER)) {
                try {
                    const decompressed = ImageCompressionService.decompressFull(value);
                    const blob = await base64ToBlob(decompressed);
                    const newId = await saveImage(blob);
                    processed[key] = newId;
                } catch (e) {
                    logger.error("[ImageSyncResolver] Failed to inject portrait image:", e);
                    processed[key] = '';
                }
            }
            // Case 1.1: Portrait Legacy (compressed string in characterImage field)
            else if (key === 'characterImage' && typeof value === 'string' && value.startsWith(GZIP_MARKER)) {
                try {
                    const decompressed = ImageCompressionService.decompressFull(value);
                    const blob = await base64ToBlob(decompressed);
                    const newId = await saveImage(blob);
                    processed.characterImageId = newId;
                    processed.characterImage = '';
                } catch (e) {
                    logger.error("[ImageSyncResolver] Failed to inject legacy character image:", e);
                    processed[key] = '';
                }
            }
            // Case 2: Grimoire Image Node (compressed string in imageId attr)
            else if (key === 'type' && value === 'bookImage' && (obj.attrs as Record<string, any> | undefined)?.imageId?.startsWith?.(GZIP_MARKER)) {
                try {
                    const attrs = obj.attrs as Record<string, any>;
                    const compressed = attrs.imageId;
                    const decompressed = ImageCompressionService.decompressFull(compressed);
                    const blob = await base64ToBlob(decompressed);
                    const newId = await saveImage(blob);

                    processed.type = 'bookImage';
                    processed.attrs = {
                        ...attrs,
                        imageId: newId // Replace compressed data with local ID
                    };

                    for (const k of Object.keys(obj)) {
                        if (k !== 'type' && k !== 'attrs') processed[k] = obj[k];
                    }
                    return processed;
                } catch (e) {
                    logger.error("[ImageSyncResolver] Failed to inject book image:", e);
                }
                processed[key] = value;
            }
            // Case 3: Campaign Note Cover (base64Cover field)
            else if (key === 'base64Cover' && typeof value === 'string' && value.startsWith(GZIP_MARKER)) {
                try {
                    const decompressed = ImageCompressionService.decompressFull(value);
                    const blob = await base64ToBlob(decompressed);
                    const newId = await saveImage(blob);
                    processed.imageId = newId;
                    // We don't return here because we want to keep processing other fields in the note
                } catch (e) {
                    logger.error("[ImageSyncResolver] Failed to inject note cover image:", e);
                }
                // Don't include base64Cover in the final object
                continue;
            }
            // Case 4: Campaign Note Gallery Image (base64Data field)
            else if (key === 'base64Data' && typeof value === 'string' && value.startsWith(GZIP_MARKER)) {
                try {
                    const decompressed = ImageCompressionService.decompressFull(value);
                    const blob = await base64ToBlob(decompressed);
                    const newId = await saveImage(blob);
                    processed.imageId = newId;
                } catch (e) {
                    logger.error("[ImageSyncResolver] Failed to inject note gallery image:", e);
                }
                // Don't include base64Data in the final object
                continue;
            }
            // Case 5: Generic Compressed Image
            else if (typeof value === 'string' && value.startsWith(GZIP_MARKER)) {
                try {
                    processed[key] = ImageCompressionService.decompressFull(value);
                } catch (e) {
                    processed[key] = value;
                }
            }
            // Standard recursion
            else if (typeof value === 'object' && value !== null) {
                processed[key] = await this.injectImagesAfterSync(value);
            } else {
                processed[key] = value;
            }
        }
        return processed;
    }
};

