import { describe, it, expect, vi, beforeEach, afterEach, Mock } from 'vitest';
import { loadRules } from './RulesLoader';
import { GithubRateLimiter } from '../utils/githubUtils';
import { OfflineStorageService } from './OfflineStorageService';
import { CampaignService } from './CampaignService';
import { defaultRules } from '../data/defaultRules';

// Mocks
vi.mock('../utils/githubUtils', () => ({
    GithubRateLimiter: {
        isOffline: vi.fn(),
        isLimited: vi.fn(),
        setLimited: vi.fn()
    }
}));

vi.mock('./OfflineStorageService', () => ({
    OfflineStorageService: {
        getActiveRules: vi.fn(),
        getRulesBySettingId: vi.fn(),
        saveRules: vi.fn()
    }
}));

vi.mock('./CampaignService', () => ({
    CampaignService: {
        loadSetting: vi.fn()
    }
}));

vi.mock('../utils/logger', () => ({
    logger: {
        log: vi.fn(),
        warn: vi.fn(),
        error: vi.fn()
    }
}));

// Global fetch mock
const mockFetch = vi.fn();
global.fetch = mockFetch;

describe('RulesLoader', () => {
    beforeEach(() => {
        vi.resetAllMocks();
        mockFetch.mockReset();

        // Default mocks
        (GithubRateLimiter.isOffline as Mock).mockReturnValue(false);
        (GithubRateLimiter.isLimited as Mock).mockReturnValue(false);
        (GithubRateLimiter.setLimited as Mock).mockImplementation(() => { });
        (OfflineStorageService.getActiveRules as Mock).mockResolvedValue(null);
        (OfflineStorageService.getRulesBySettingId as Mock).mockResolvedValue(null);
        (OfflineStorageService.saveRules as Mock).mockResolvedValue(true);
        (CampaignService.loadSetting as Mock).mockResolvedValue(null);
    });

    describe('Offline Mode', () => {
        beforeEach(() => {
            (GithubRateLimiter.isOffline as Mock).mockReturnValue(true);
        });

        it('should load active rules from cache when offline and no settingId', async () => {
            const mockCachedRules = { ...defaultRules, source: 'cache_test', version: '1.0.0' };
            (OfflineStorageService.getActiveRules as Mock).mockResolvedValue(mockCachedRules);

            const result = await loadRules();

            expect(OfflineStorageService.getActiveRules).toHaveBeenCalled();
            expect(result).toEqual({ ...mockCachedRules, source: 'cache' });
        });

        it('should load specific setting from cache when offline and settingId provided', async () => {
            const settingId = 'test-setting-id';
            const mockCachedRules = { ...defaultRules, settingId, version: '1.0.0' };
            (OfflineStorageService.getRulesBySettingId as Mock).mockResolvedValue(mockCachedRules);

            const result = await loadRules(settingId);

            expect(OfflineStorageService.getRulesBySettingId).toHaveBeenCalledWith(settingId);
            expect(result).toEqual({ ...mockCachedRules, source: 'cache' });
        });

        it('should fallback to default rules when offline and no cache', async () => {
            (OfflineStorageService.getActiveRules as Mock).mockResolvedValue(null);

            const result = await loadRules();

            expect(result).toEqual(defaultRules);
        });
    });

    describe('Online Mode - GitHub API Strategy', () => {
        it('should fetch from GitHub API if not rate limited', async () => {
            const mockApiRules = { ...defaultRules, version: '2.0.0' };
            mockFetch.mockResolvedValueOnce({
                ok: true,
                json: async () => mockApiRules
            });

            const result = await loadRules();

            expect(mockFetch).toHaveBeenCalledWith(expect.stringContaining('api.github.com'), expect.anything());
            expect(result).toEqual({ ...mockApiRules, source: 'api' });
        });

        it('should handle API rate limit (403) and fallback to Raw CDN', async () => {
            // API Fails with 403
            mockFetch.mockResolvedValueOnce({
                ok: false,
                status: 403
            });

            // Raw CDN Success
            const mockRawRules = { ...defaultRules, version: '3.0.0' };
            mockFetch.mockResolvedValueOnce({
                ok: true,
                json: async () => mockRawRules
            });

            const result = await loadRules();

            expect(GithubRateLimiter.setLimited).toHaveBeenCalled();
            expect(result).toEqual({ ...mockRawRules, source: 'api' });
        });

        it('should skip API if already rate limited', async () => {
            (GithubRateLimiter.isLimited as Mock).mockReturnValue(true);

            // Raw CDN Success
            const mockRawRules = { ...defaultRules, version: '4.0.0' };
            mockFetch.mockResolvedValueOnce({
                ok: true,
                json: async () => mockRawRules
            });

            const result = await loadRules();

            // Verify call URL instead of strict count
            const callUrls = mockFetch.mock.calls.map((c: any) => c[0]);
            const hasApi = callUrls.some((url: string) => url.includes('api.github.com'));
            const hasRaw = callUrls.some((url: string) => url.includes('raw.githubusercontent.com'));

            expect(hasApi).toBe(false);
            expect(hasRaw).toBe(true);
            expect(result).toEqual({ ...mockRawRules, source: 'api' });
        });
    });

    describe('Last Resort', () => {
        it('should fallback to general cache if online fetch fails', async () => {
            // API Fails
            mockFetch.mockRejectedValueOnce(new Error('Network Error'));
            // Raw Fails
            mockFetch.mockRejectedValueOnce(new Error('Network Error'));

            const mockCachedRules = { ...defaultRules, version: 'cache-v1' };
            (OfflineStorageService.getActiveRules as Mock).mockResolvedValue(mockCachedRules);

            const result = await loadRules();

            expect(OfflineStorageService.getActiveRules).toHaveBeenCalled();
            expect(result).toEqual(mockCachedRules);
        });

        it('should return defaultRules if absolutely all else fails', async () => {
            // API Fails
            mockFetch.mockRejectedValueOnce(new Error('Network Error'));
            // Raw Fails
            mockFetch.mockRejectedValueOnce(new Error('Network Error'));

            // Cache Fails
            (OfflineStorageService.getActiveRules as Mock).mockResolvedValue(null);

            const result = await loadRules();

            expect(result).toEqual(defaultRules);
        });
    });
});

import { set, get, del } from 'idb-keyval';
import { GZIP_MARKER } from './ImageCompressionService';

/**
 * Checks the available storage quota using the Estimation API.
 * Fallback to 40MB if API is not available.
 */
export const checkStorageQuota = async (): Promise<{ usage: number; quota: number; available: number }> => {
    if (navigator.storage && navigator.storage.estimate) {
        const estimate = await navigator.storage.estimate();
        const usage = estimate.usage || 0;
        const quota = estimate.quota || 100 * 1024 * 1024; // Default to 100MB if quota is missing
        return {
            usage,
            quota,
            available: Math.max(0, quota - usage)
        };
    }
    // Fallback for older browsers
    return {
        usage: 0,
        quota: 40 * 1024 * 1024, // 40MB safe fallback
        available: 40 * 1024 * 1024
    };
};

/**
 * Compress an image blob using Canvas API before storage.
 * - Resizes to max 1920px width (preserving aspect ratio)
 * - Converts to WebP at 80% quality
 * - Falls back to JPEG if WebP is unsupported
 * - Non-image blobs pass through unchanged
 */
const compressBlob = async (blob: File | Blob): Promise<Blob> => {
    // Only compress images
    if (!blob.type.startsWith('image/')) return blob;
    // Skip small images (< 100KB) ÔÇö not worth the overhead
    if (blob.size < 100 * 1024) return blob;

    const MAX_WIDTH = 1920;
    const QUALITY = 0.8;

    return new Promise<Blob>((resolve) => {
        const url = URL.createObjectURL(blob);
        const img = new Image();
        img.onload = () => {
            URL.revokeObjectURL(url);
            try {
                let w = img.width;
                let h = img.height;
                if (w > MAX_WIDTH) {
                    const ratio = MAX_WIDTH / w;
                    w = MAX_WIDTH;
                    h = Math.round(h * ratio);
                }
                const canvas = document.createElement('canvas');
                canvas.width = w;
                canvas.height = h;
                const ctx = canvas.getContext('2d');
                if (!ctx) { resolve(blob); return; }
                ctx.drawImage(img, 0, 0, w, h);
                canvas.toBlob(
                    (result) => resolve(result || blob),
                    'image/webp',
                    QUALITY
                );
            } catch {
                resolve(blob);
            }
        };
        img.onerror = () => { URL.revokeObjectURL(url); resolve(blob); };
        img.src = url;
    });
};

export const saveImage = async (file: File | Blob): Promise<string> => {
    // Compress image before storage
    const compressed = await compressBlob(file);

    const { available } = await checkStorageQuota();

    if (compressed.size > available) {
        const sizeKo = (compressed.size / 1024).toFixed(0);
        const availKo = (available / 1024).toFixed(0);
        throw new Error(`Espace de stockage insuffisant. Taille: ${sizeKo} Ko, Disponible: ${availKo} Ko.`);
    }

    const id = `img_${Math.random().toString(36).substr(2, 9)}_${Date.now()}`;

    try {
        await set(id, compressed);
    } catch (error) {
        if (error instanceof DOMException && error.name === 'QuotaExceededError') {
            throw new Error('Le stockage local est plein. Veuillez supprimer des images existantes.', { cause: error });
        }
        throw error;
    }

    return id;
};

export const getImage = async (id: string): Promise<Blob | undefined> => {
    return await get(id);
};

export const deleteImage = async (id: string): Promise<void> => {
    await del(id);
};

export const blobToBase64 = (blob: Blob): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onloadend = () => {
            if (typeof reader.result === 'string') {
                resolve(reader.result);
            } else {
                reject(new Error('Failed to convert blob to base64'));
            }
        };
        reader.onerror = reject;
        reader.readAsDataURL(blob);
    });
};

export const base64ToBlob = async (base64: string): Promise<Blob> => {
    const response = await fetch(base64);
    return await response.blob();
};

import { DatabaseService } from '../DatabaseService';
import { LibraryEntry as LibraryTraitEntry, LibrarySkillEntry, LibrarySpecializationEntry, LibraryBackgroundEntry, LibraryCounterEntry } from '../../types/system';
import { ErrorService } from '../ErrorService';

import { normalizeString } from '../../utils/stringUtils';
import { logger } from '../../utils/logger';

const ensureUUID = (id: string | undefined): string => {
    if (!id) return crypto.randomUUID();
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    if (uuidRegex.test(id)) return id;
    logger.warn(`[LibraryImporter] Legacy ID detected (${id}), replacing with UUID`);
    return crypto.randomUUID();
};

// Helper to check duplicates against DB
const filterDuplicates = async <T extends { name: string }>(table: string, targetId: string | null, newItems: T[]): Promise<T[]> => {
    if (newItems.length === 0) return [];

    // Check both ID and Name to be safe
    const query = targetId ? { eq: { setting_id: targetId } } : { eq: { setting_id: null } };

    // We fetch existing names.
    // Note: This isn't perfect if names are very similar but not identical, but `normalizeString` helps.
    const existing = await DatabaseService.fetchAll<{ name: string }>(table, { ...query, select: 'name' }, 'LibraryImporter.checkDupes');
    const existingNames = new Set(existing.map(e => normalizeString(e.name)));

    return newItems.filter(item => !existingNames.has(normalizeString(item.name)));
};

export const LibraryImporter = {
    /**
     * Partial Imports: Add items to libraries without overwriting existing ones.
     */
    async importTraits(targetId: string | null, traits: LibraryTraitEntry[], linkToSettingId?: string): Promise<boolean> {
        if (traits.length === 0) return true;
        const payload = traits.map(t => ({
            setting_id: targetId,
            id: ensureUUID(t.id),
            type: t.type,
            name: t.name,
            cost: t.cost || '0',
            points_label: t.pointsLabel || t.cost,
            is_variable_cost: t.isVariableCost || false,
            description: t.description || '',
            tags: t.tags || [],
            is_variable: t.isVariable || false,
            has_auto_counter: t.hasAutoCounter,
            auto_counter_name: t.autoCounterName,
            is_xp_upgradeable: t.isXPUpgradeable,
            effects: t.effects || []
        }));

        const uniquePayload = await filterDuplicates('libraries_traits', targetId, payload);

        // If nothing new to insert, we can still proceed to check links if needed, 
        // but typically we only link what we just inserted or if we know it exists.
        // However, if it was a duplicate, it implies it's already there. 
        // For simplicity and safety (avoiding duplicate primary key errors if we tried to re-insert), we only insert unique.

        let result = true;
        if (uniquePayload.length > 0) {
            result = !!(await DatabaseService.insert('libraries_traits', uniquePayload, 'LibraryImporter.importTraits'));
        }

        if (!result) return false;

        // Auto-link if global import but triggered from a campaign
        // Only link the ones we intended to import (even if they were duplicates, we might want to link them? 
        // The original logic only linked what was *inserted*). 
        // The prompt implies we want to prevent adding *duplicates* to the library.
        // If it's already in the library, rel-linking it might be redundant or handled elsewhere?
        // Let's stick to linking only what we successfully processed (or verified as existing?).
        // Actually, if it's a duplicate, it means it exists. We might still want to link it if `linkToSettingId` is provided.
        // But `uniquePayload` only contains NEW items.
        // If we want to link EXISTING items too, we'd need their IDs.
        // For now, let's stick to the pattern: Only insert and link validation for NEW items.
        // (If the user wants to link an existing global item, that's a different operation usually).

        if (targetId === null && linkToSettingId && uniquePayload.length > 0) {
            const relPayload = uniquePayload.map(p => ({ setting_id: linkToSettingId, trait_id: p.id, is_active: true }));
            await DatabaseService.insert('rel_setting_traits', relPayload, 'LibraryImporter.importTraits.link');
        }

        return true;
    },

    async importSkills(targetId: string | null, skills: LibrarySkillEntry[], linkToSettingId?: string): Promise<boolean> {
        if (skills.length === 0) return true;

        const payload = skills.map(s => ({
            setting_id: targetId,
            id: ensureUUID(s.id),
            name: s.name,
            description: s.description,
            default_category: s.defaultCategory,
            is_variable: s.isVariable
        }));

        const uniquePayload = await filterDuplicates('libraries_skills', targetId, payload);

        let result = true;
        if (uniquePayload.length > 0) {
            result = !!(await DatabaseService.insert('libraries_skills', uniquePayload, 'LibraryImporter.importSkills'));
        }
        if (!result) return false;

        // Auto-link if global
        if (targetId === null && linkToSettingId && uniquePayload.length > 0) {
            const relPayload = uniquePayload.map(p => ({ setting_id: linkToSettingId, skill_id: p.id, is_active: true }));
            await DatabaseService.insert('rel_setting_skills', relPayload, 'LibraryImporter.importSkills.link');
        }

        return true;
    },

    async importSpecializations(targetId: string | null, specs: LibrarySpecializationEntry[], linkToSettingId?: string): Promise<boolean> {
        if (specs.length === 0) return true;
        const payload = specs.map(s => ({
            setting_id: targetId,
