            await DatabaseService.insert('rel_setting_backgrounds', relPayload, 'LibraryImporter.importBackgrounds.link');
        }

        return true;
    },

    async importCounters(targetId: string | null, counters: LibraryCounterEntry[], linkToSettingId?: string): Promise<boolean> {
        if (counters.length === 0) return true;
        const payload = counters.map(c => ({
            setting_id: targetId,
            id: ensureUUID(c.id),
            name: c.name,
            description: c.description,
            max_value: c.maxValue || 10,
            default_value: c.defaultValue || 0,
            xp_cost: c.xpCost || 0
        }));

        const uniquePayload = await filterDuplicates('libraries_counters', targetId, payload);

        let result = true;
        if (uniquePayload.length > 0) {
            result = !!(await DatabaseService.insert('libraries_counters', uniquePayload, 'LibraryImporter.importCounters'));
        }
        if (!result) return false;

        if (targetId === null && linkToSettingId && uniquePayload.length > 0) {
            const relPayload = uniquePayload.map(p => ({ setting_id: linkToSettingId, counter_id: p.id, is_active: true }));
            await DatabaseService.insert('rel_setting_counters', relPayload, 'LibraryImporter.importCounters.link');
        }

        return true;
    }
};

import { supabase } from '../supabase';
import { DatabaseService } from '../DatabaseService';
import { RulesData } from '../../types/rules';
import { LibraryMapper } from './LibraryMapper';
import { ErrorService } from '../ErrorService';
import {
    DBTrait, DBSkill, DBSpecialization, DBBackground, DBCounter, DBMysticAbility, DBFormula,
    RelSettingTrait, RelSettingSkill, RelSettingSpecialization,
    RelSettingBackground, RelSettingCounter, RelSettingMysticAbility, RelSettingFormula,
    DBTraitVariant, DBSkillVariant, DBBackgroundVariant
} from '../../types/database';
import { ItemUsageDetail } from '../../types/usageTypes';
import {
    TABLE_LIBRARIES_TRAITS, TABLE_LIBRARIES_SKILLS, TABLE_LIBRARIES_SPECIALIZATIONS, TABLE_LIBRARIES_BACKGROUNDS, TABLE_LIBRARIES_COUNTERS, TABLE_LIBRARIES_MYSTIC_ABILITIES, TABLE_LIBRARIES_FORMULAS,
    TABLE_REL_SETTING_TRAITS, TABLE_REL_SETTING_SKILLS, TABLE_REL_SETTING_SPECIALIZATIONS, TABLE_REL_SETTING_BACKGROUNDS, TABLE_REL_SETTING_COUNTERS, TABLE_REL_SETTING_MYSTIC_ABILITIES, TABLE_REL_SETTING_FORMULAS,
    TABLE_LIBRARIES_TRAITS_VARIANTS, TABLE_LIBRARIES_SKILLS_VARIANTS, TABLE_LIBRARIES_BACKGROUNDS_VARIANTS
} from '../../constants/db';

export const LibraryLoader = {
    /**
     * Load libraries for a specific setting and map them to RulesData format
     */
    async loadLibraries(settingId: string): Promise<RulesData['libraries']> {
        try {
            // 1. Fetch Relations first to identify what belongs to this campaign
            const [
                relTraits, relSkills, relSpecs, relBackgrounds, relCounters, relMysticAbilities, relFormulas
            ] = await Promise.all([
                DatabaseService.fetchAll<RelSettingTrait>(TABLE_REL_SETTING_TRAITS, { eq: { setting_id: settingId } }, 'LibraryLoader.relTraits'),
                DatabaseService.fetchAll<RelSettingSkill>(TABLE_REL_SETTING_SKILLS, { eq: { setting_id: settingId } }, 'LibraryLoader.relSkills'),
                DatabaseService.fetchAll<RelSettingSpecialization>(TABLE_REL_SETTING_SPECIALIZATIONS, { eq: { setting_id: settingId } }, 'LibraryLoader.relSpecs'),
                DatabaseService.fetchAll<RelSettingBackground>(TABLE_REL_SETTING_BACKGROUNDS, { eq: { setting_id: settingId } }, 'LibraryLoader.relBackgrounds'),
                DatabaseService.fetchAll<RelSettingCounter>(TABLE_REL_SETTING_COUNTERS, { eq: { setting_id: settingId } }, 'LibraryLoader.relCounters'),
                DatabaseService.fetchAll<RelSettingMysticAbility>(TABLE_REL_SETTING_MYSTIC_ABILITIES, { eq: { setting_id: settingId } }, 'LibraryLoader.relMystic'),
                DatabaseService.fetchAll<RelSettingFormula>(TABLE_REL_SETTING_FORMULAS, { eq: { setting_id: settingId } }, 'LibraryLoader.relFormulas')
            ]);

            const traitIds = relTraits.map(r => r.trait_id);
            const skillIdsList = relSkills.map(r => r.skill_id);
            const specIds = relSpecs.map(r => r.specialization_id);
            const bgIds = relBackgrounds.map(r => r.background_id);
            const counterIds = relCounters.map(r => r.counter_id);
            const mysticIds = relMysticAbilities.map(r => r.mystic_ability_id);
            const formulaIds = relFormulas.map(r => r.formula_id);

            // 2. Fetch Reference Tables (First pass: items that don't depend on others being loaded)
            const buildFilter = (ids: string[]) => {
                const parts = [`setting_id.eq.${settingId}`];
                if (ids && ids.length > 0) {
                    // Filter out invalid or duplicate IDs to keep the query string safe
                    const validIds = Array.from(new Set(ids.filter(id => id && id.length === 36)));
                    if (validIds.length > 0) {
                        parts.push(`id.in.(${validIds.join(',')})`);
                    }
                }
                return parts.join(',');
            };

            const [
                traits, specs, backgrounds, counters, mysticAbilities, formulas
            ] = await Promise.all([
                DatabaseService.fetchAll<DBTrait>(TABLE_LIBRARIES_TRAITS, { or: buildFilter(traitIds) }, 'LibraryLoader.loadTraits'),
                DatabaseService.fetchAll<DBSpecialization>(TABLE_LIBRARIES_SPECIALIZATIONS, { or: buildFilter(specIds) }, 'LibraryLoader.loadSpecs'),
                DatabaseService.fetchAll<DBBackground>(TABLE_LIBRARIES_BACKGROUNDS, { or: buildFilter(bgIds) }, 'LibraryLoader.loadBackgrounds'),
                DatabaseService.fetchAll<DBCounter>(TABLE_LIBRARIES_COUNTERS, { or: buildFilter(counterIds) }, 'LibraryLoader.loadCounters'),
                DatabaseService.fetchAll<DBMysticAbility>(TABLE_LIBRARIES_MYSTIC_ABILITIES, { or: buildFilter(mysticIds) }, 'LibraryLoader.loadMystic'),
                DatabaseService.fetchAll<DBFormula>(TABLE_LIBRARIES_FORMULAS, { or: buildFilter(formulaIds) }, 'LibraryLoader.loadFormulas')
            ]);

            // 3. Second pass: Load Skills (merge explicitly linked skills AND skills referenced by loaded specializations)
            const allNeededSkillIds = new Set(skillIdsList);
            specs.forEach(s => {
                if (s.skill_ids && Array.isArray(s.skill_ids)) {
                    s.skill_ids.forEach(id => {
                        if (id) allNeededSkillIds.add(id);
                    });
                }
            });

            // Also check if some mystic abilities were referenced as skills (unlikely but safe)
            // If they are regular skills, we need them in the skills fetch.

            const skillIdsToFetch = Array.from(allNeededSkillIds);

            const [
                skills,
                traitVariants,
                skillVariants,
                bgVariants
            ] = await Promise.all([
                DatabaseService.fetchAll<DBSkill>(TABLE_LIBRARIES_SKILLS, { or: buildFilter(skillIdsToFetch) }, 'LibraryLoader.loadSkills'),
                DatabaseService.fetchAll<DBTraitVariant>(TABLE_LIBRARIES_TRAITS_VARIANTS, { or: buildFilter(traitIds), select: 'trait_id, name' }, 'LibraryLoader.loadTraitsVariants'),
                DatabaseService.fetchAll<DBSkillVariant>(TABLE_LIBRARIES_SKILLS_VARIANTS, { or: buildFilter(skillIdsToFetch), select: 'skill_id, name' }, 'LibraryLoader.loadSkillsVariants'),
                DatabaseService.fetchAll<DBBackgroundVariant>(TABLE_LIBRARIES_BACKGROUNDS_VARIANTS, { or: buildFilter(bgIds), select: 'background_id, name' }, 'LibraryLoader.loadBgVariants')
            ]);

            const traitVarMap = new Map<string, string[]>();
            traitVariants.forEach((v: DBTraitVariant) => {
                const list = traitVarMap.get(v.trait_id) || [];
                if (!list.includes(v.name)) {
                    list.push(v.name);
                    traitVarMap.set(v.trait_id, list);
                }
            });

            const skillVarMap = new Map<string, string[]>();
            skillVariants.forEach((v: DBSkillVariant) => {
                const list = skillVarMap.get(v.skill_id) || [];
                if (!list.includes(v.name)) {
                    list.push(v.name);
                    skillVarMap.set(v.skill_id, list);
                }
            });

            const bgVarMap = new Map<string, string[]>();
            bgVariants.forEach((v: DBBackgroundVariant) => {
                const list = bgVarMap.get(v.background_id) || [];
                if (!list.includes(v.name)) {
                    list.push(v.name);
                    bgVarMap.set(v.background_id, list);
                }
            });

            const activeTraitIds = new Set<string>(relTraits.filter((r: RelSettingTrait) => r.is_active).map((r: RelSettingTrait) => r.trait_id));
            const activeSkillIds = new Set<string>(relSkills.filter((r: RelSettingSkill) => r.is_active).map((r: RelSettingSkill) => r.skill_id));
            const activeSpecIds = new Set<string>(relSpecs.filter((r: RelSettingSpecialization) => r.is_active).map((r: RelSettingSpecialization) => r.specialization_id));
            const activeBgIds = new Set<string>(relBackgrounds.filter((r: RelSettingBackground) => r.is_active).map((r: RelSettingBackground) => r.background_id));
            const activeCounterIds = new Set<string>(relCounters.filter((r: RelSettingCounter) => r.is_active).map((r: RelSettingCounter) => r.counter_id));
            const activeMysticIds = new Set<string>(relMysticAbilities.filter((r: any) => r.is_active).map((r: any) => r.mystic_ability_id));
            const activeFormulaIds = new Set<string>(relFormulas.filter((r: RelSettingFormula) => r.is_active).map((r: RelSettingFormula) => r.formula_id));

            const skillRelMap = new Map<string, RelSettingSkill>(relSkills.map((r: RelSettingSkill) => [r.skill_id, r]));
            const bgDefaultMap = new Map<string, string>(relBackgrounds.map((r: RelSettingBackground) => [r.background_id, r.default_category]));
            const counterDefaultMap = new Map<string, string>(relCounters.map((r: RelSettingCounter) => [r.counter_id, r.default_category]));
            const mysticRelMap = new Map<string, any>(relMysticAbilities.map((r: any) => [r.mystic_ability_id, r]));
            const mysticDefaultMap = new Map<string, string>(relMysticAbilities.map((r: any) => [r.mystic_ability_id, r.default_category]));

            return {
                traits: traits.map((t: DBTrait) => LibraryMapper.mapTrait(t, activeTraitIds, settingId, traitVarMap.get(t.id))).sort((a, b) => a.name.localeCompare(b.name)),
                skills: skills.map((s: DBSkill) => LibraryMapper.mapSkill(s, activeSkillIds, settingId, skillVarMap.get(s.id), skillRelMap.get(s.id))).sort((a, b) => a.name.localeCompare(b.name)),
                specializations: specs.map((s: DBSpecialization) => LibraryMapper.mapSpec(s, activeSpecIds, settingId)).sort((a, b) => a.name.localeCompare(b.name)),
                backgrounds: backgrounds.map((b: DBBackground) => LibraryMapper.mapBackground(b, activeBgIds, settingId, bgVarMap.get(b.id), bgDefaultMap.get(b.id))).sort((a, b) => a.name.localeCompare(b.name)),
                counters: counters.map((c: DBCounter) => LibraryMapper.mapCounter(c, activeCounterIds, settingId, counterDefaultMap.get(c.id))).sort((a, b) => a.name.localeCompare(b.name)),
                mysticAbilities: mysticAbilities.map((m: any) => LibraryMapper.mapMysticAbility(m, activeMysticIds, settingId, mysticDefaultMap.get(m.id))).sort((a: any, b: any) => a.name.localeCompare(b.name)),
                formulas: (formulas || []).map((f: DBFormula) => LibraryMapper.mapFormula(f, activeFormulaIds, settingId)).sort((a, b) => a.name.localeCompare(b.name))
            };
        } catch (error) {
            ErrorService.handleError(error, {
                context: 'LibraryLoader.loadLibraries',
                userMessage: 'Erreur de chargement des biblioth├¿ques'
            });
            return { traits: [], skills: [], specializations: [], backgrounds: [], counters: [], mysticAbilities: [], formulas: [] };
        }
    },

    /**
     * Get usage statistics from all settings except the current one
     */
    async loadGlobalUsage(currentSettingId: string): Promise<Record<string, number>> {
        try {
            const tables = [
                { table: TABLE_REL_SETTING_TRAITS, id: 'trait_id', cat: false },
                { table: TABLE_REL_SETTING_SKILLS, id: 'skill_id', cat: true },
                { table: TABLE_REL_SETTING_BACKGROUNDS, id: 'background_id', cat: true },
                { table: TABLE_REL_SETTING_COUNTERS, id: 'counter_id', cat: true },
                { table: TABLE_REL_SETTING_SPECIALIZATIONS, id: 'specialization_id', cat: false },
                { table: TABLE_REL_SETTING_MYSTIC_ABILITIES, id: 'mystic_ability_id', cat: true },
                { table: TABLE_REL_SETTING_FORMULAS, id: 'formula_id', cat: false }
            ];

            const results = await Promise.all(tables.map(async t => {
                let query = supabase.from(t.table).select(`${t.id}, setting_id`);

                // Filter out current setting
                query = query.neq('setting_id', currentSettingId);

                // For tables with categories, count "placed" items OR items with overrides
                if (t.cat && t.table === TABLE_REL_SETTING_SKILLS) {
                    query = query.or(`default_category.not.is.null,name_override.not.is.null,description_override.not.is.null,is_variable_override.not.is.null,mystic_ability_id_override.not.is.null`);
                } else if (t.cat) {
                    query = query.not('default_category', 'is', null);
                }

                const { data } = await query;
                return { idKey: t.id, data: data || [] };
            }));

            const usageMap: Record<string, number> = {};
            results.forEach(res => {
                res.data.forEach((row: any) => {
                    const id = row[res.idKey];
                    usageMap[id] = (usageMap[id] || 0) + 1;
                });
            });

            return usageMap;
        } catch (error) {
            ErrorService.handleError(error, { context: 'LibraryLoader.loadGlobalUsage', silent: true });
            return {};
        }
    },

    /**
     * Load detailed usage information for a specific item (campaigns and characters)
     */
    async loadItemUsageDetails(
        itemId: string,
        currentSettingId: string,
        itemType: 'trait' | 'skill' | 'background' | 'counter' | 'mystic' | 'specialization' | 'formula'
    ): Promise<ItemUsageDetail> {
        try {
            // 1. Determine rel table and columns
            let relTable = '';
            let idColumn = '';

            switch (itemType) {
                case 'trait': relTable = TABLE_REL_SETTING_TRAITS; idColumn = 'trait_id'; break;
                case 'skill': relTable = TABLE_REL_SETTING_SKILLS; idColumn = 'skill_id'; break;
                case 'background': relTable = TABLE_REL_SETTING_BACKGROUNDS; idColumn = 'background_id'; break;
                case 'counter': relTable = TABLE_REL_SETTING_COUNTERS; idColumn = 'counter_id'; break;
                case 'mystic': relTable = TABLE_REL_SETTING_MYSTIC_ABILITIES; idColumn = 'mystic_ability_id'; break;
                case 'specialization': relTable = TABLE_REL_SETTING_SPECIALIZATIONS; idColumn = 'specialization_id'; break;
                case 'formula': relTable = TABLE_REL_SETTING_FORMULAS; idColumn = 'formula_id'; break;
            }

            if (!relTable) return { settings: [], characters: [] };

            // 2. Fetch campaign usage
            let query = supabase
                .from(relTable)
                .select(`setting_id, game_settings!inner(name)`)
                .eq(idColumn, itemId);

            if (currentSettingId && currentSettingId !== 'global') {
                query = query.neq('setting_id', currentSettingId);
            }

            const { data: settingsData, error: settingsError } = await query;

            if (settingsError) throw settingsError;

            const settings = (settingsData || []).map((row: any) => ({
                id: row.setting_id,
                name: row.game_settings.name
            }));

            // 3. Fetch character usage (focus on traits for now as it's the most common/tracable)
            let characters: any[] = [];
            if (itemType === 'trait') {
                const { data: charData, error: charError } = await supabase
                    .from('characters')
                    .select('character_name, player_name, game_settings(name)')
                    .or(`data->page2->avantages->0->>definitionId.eq.${itemId},data->page2->desavantages->0->>definitionId.eq.${itemId}`);

                // Note: The above .or with JSONB arrow is a bit limited in Supabase JS (only checks first element).
                // For a more robust solution in a real app, we would use .contains() but it requires the whole JSON path match.
                // Given the constraints, we will at least return the campaigns which is the primary lock source.

                if (!charError && charData) {
                    characters = charData.map(c => ({
                        name: c.character_name,
                        player: c.player_name,
                        settingName: (c.game_settings as any)?.name
                    }));
                }
            }

            return {
                settings,
                characters
            };
        } catch (error) {
            ErrorService.handleError(error, { context: 'LibraryLoader.loadItemUsageDetails', silent: true });
            return { settings: [], characters: [] };
        }
    }
};

import { LibraryBackgroundEntry, LibraryCounterEntry, LibrarySkillEntry, LibrarySpecializationEntry, LibraryFormulaEntry, LibraryEntry as LibraryTraitEntry } from '../../types/system';
import { DBTrait, DBSkill, DBSpecialization, DBBackground, DBCounter, DBMysticAbility, DBFormula } from '../../types/database';


const legacySkillMap: Record<string, string> = {
    'talents': 'Col_Comp_1',
    'competences': 'Col_Comp_2',
    'competences_col_2': 'Col_Comp_3',
    'connaissances': 'Col_Comp_4',
    'autres_competences': 'Col_Comp_5',
    'competences2': 'Col_Comp_6',
    'autres': 'Col_Comp_7',
    'arrieres_plans': 'Col_Comp_8',
    'counters': 'Col_Comp_9'
};

export const LibraryMapper = {
    mapTrait: (t: DBTrait, activeIds: Set<string>, sid: string, variants: string[] = []): LibraryTraitEntry => ({
        id: t.id,
        type: (t.type || 'avantage') as 'avantage' | 'desavantage',
        name: t.name,
        cost: t.cost || '0',
        pointsLabel: t.points_label || t.cost || '0',
        isVariableCost: t.is_variable_cost || false,
        description: t.description || '',
        tags: t.tags || [],
        isVariable: t.is_variable || false,
        hasAutoCounter: t.has_auto_counter || false,
        autoCounterName: t.auto_counter_name,
        isXPUpgradeable: t.is_xp_upgradeable || false,
        variants: variants,
        effects: t.effects || [],
        isGlobal: t.setting_id == null,
        isActive: activeIds.has(t.id) || t.setting_id === sid
    }),

    mapSkill: (s: DBSkill, activeIds: Set<string>, sid: string, variants: string[] = [], rel?: any): LibrarySkillEntry => {
        const isCustomized = !!(rel?.name_override || rel?.description_override || rel?.is_variable_override !== undefined || rel?.mystic_ability_id_override);

        return {
            id: s.id,
            name: rel?.name_override || s.name,
            description: rel?.description_override || s.description || '',
            defaultCategory: legacySkillMap[rel?.default_category || ''] || rel?.default_category || s.defaultCategory,
            isVariable: (rel?.is_variable_override !== undefined && rel?.is_variable_override !== null) ? rel.is_variable_override : (s.is_variable || false),
            variants: variants,
            isGlobal: s.setting_id == null,
            isActive: activeIds.has(s.id) || s.setting_id === sid,
            mysticAbilityId: rel?.mystic_ability_id_override || s.mystic_ability_id,
            isCustomized,
            masterDefinition: isCustomized ? {
                name: s.name,
                description: s.description || '',
                isVariable: s.is_variable || false,
                mysticAbilityId: s.mystic_ability_id
            } : undefined
        };
    },

    mapMysticAbility: (m: DBMysticAbility, activeIds: Set<string>, sid: string, localDefaultCategory?: string): LibrarySkillEntry => ({
        id: m.id,
        name: m.name,
        description: m.description || '',
        defaultCategory: legacySkillMap[localDefaultCategory || ''] || localDefaultCategory || legacySkillMap[m.default_category || ''] || m.default_category,
        isVariable: m.is_variable || false,
        isGlobal: m.setting_id == null,
        isActive: activeIds.has(m.id) || m.setting_id === sid
    }),

    mapSpec: (s: DBSpecialization, activeIds: Set<string>, sid: string): LibrarySpecializationEntry => ({
        id: s.id,
        name: s.name,
        description: s.description,
        skillIds: s.skill_ids || [],
        defaultMinLevel: s.default_min_level || 1,
        isImposed: s.is_imposed || false,
        isGlobal: s.setting_id == null,
        isActive: activeIds.has(s.id) || s.setting_id === sid
    }),

    mapBackground: (b: DBBackground, activeIds: Set<string>, sid: string, variants: string[] = [], localDefaultCategory?: string): LibraryBackgroundEntry => {
        const isCustomized = false; // Backgrounds customization not yet fully enabled in UI similarly to skills
        return {
            id: b.id,
            name: b.name,
            description: b.description,
            defaultCategory: localDefaultCategory,
            isVariable: b.is_variable || false,
            variants: variants,
            isGlobal: b.setting_id == null,
            isActive: activeIds.has(b.id) || b.setting_id === sid,
            isCustomized: false
        };
    },

    mapCounter: (c: DBCounter, activeIds: Set<string>, sid: string, localDefaultCategory?: string): LibraryCounterEntry => ({
        id: c.id,
        name: c.name,
        description: c.description || '',
        maxValue: (c as any).max_value ?? c.maxValue ?? 10,
        defaultValue: (c as any).default_value ?? c.defaultValue ?? 0,
        xpCost: (c as any).xp_cost ?? c.xpCost ?? 0,
        appearance: c.appearance || null,
        formulaId: c.formula_id,
        defaultCategory: localDefaultCategory || c.defaultCategory || (c as any).default_category,
        isGlobal: c.setting_id == null,
        isActive: activeIds.has(c.id) || c.setting_id === sid
    }),
    mapFormula: (f: DBFormula, activeIds: Set<string>, sid: string): LibraryFormulaEntry => {
        let type: 'modifier' | 'variable' = 'variable';
        if (f.type === 'effect' || f.type === 'modifier') type = 'modifier';
        else if (f.type === 'reserve' || f.type === 'variable') type = 'variable';

        return {
            id: f.id,
            name: f.name,
            code: f.code,
            formula: f.formula,
            type: type,
            aggregateConfig: f.aggregate_config,
            target: f.target,
            effectType: f.effect_type,
            operator: f.operator as 'ADD' | 'SET' | 'SUB' | '',
            forceVariant: f.force_variant || false,
            description: f.description || '',
            isGlobal: f.setting_id == null,
            isActive: activeIds.has(f.id) || f.setting_id === sid
        };
    }
};

import { DatabaseService } from '../../services/DatabaseService';
import { supabase } from '../../services/supabase';
import { RulesData } from '../../types/rules';
import { LIBRARY_TYPE_CONFIG } from '../../constants/db';

export const LibraryPersistence = {
    /**
     * Persist initial libraries for a new setting
     */
    async persistInitialLibraries(settingId: string, initialRules: Partial<RulesData>) {
        if (!initialRules.libraries) return;

        for (const typeCfg of LIBRARY_TYPE_CONFIG) {
            const items = (initialRules.libraries as any)[typeCfg.key] || [];
            if (items.length === 0) continue;

            // Fetch existing globals to avoid duplicates
            const globals = await DatabaseService.fetchAll<{ id: string, name: string }>(typeCfg.table, {
                select: 'id, name',
                eq: { setting_id: null }
            }, `LibraryPersistence.persistInitial.${typeCfg.key}.globals`);

            const globalMap = new Map((globals || []).map(g => [g.name.trim().toLowerCase(), g.id]));
            const toCreate: any[] = [];
            const toLink: any[] = [];

            items.forEach((item: any) => {
                const normalized = item.name.trim().toLowerCase();
                const existingId = globalMap.get(normalized);

                if (existingId) {
                    const link: any = { setting_id: settingId, [typeCfg.idKey]: existingId, is_active: true };
                    // Default categories for skills/backgrounds/counters/mysticAbilities
                    if (typeCfg.key === 'skills' || typeCfg.key === 'backgrounds' || typeCfg.key === 'counters' || typeCfg.key === 'mysticAbilities') {
                        link.default_category = item.defaultCategory;
                    }
                    toLink.push(link);
                } else {
                    // Create as global
                    const payload: any = {
                        id: item.id,
                        name: item.name,
                        code: item.code,
                        description: item.description,
                        setting_id: null
                    };

                    // Add type-specific fields
                    if (typeCfg.key === 'traits') {
                        payload.type = item.type;
                        payload.cost = item.cost || '0';
                        payload.points_label = item.pointsLabel || item.cost;
                        payload.is_variable_cost = item.isVariableCost || false;
                        payload.tags = item.tags || [];
                        payload.is_variable = item.isVariable;
                        payload.has_auto_counter = item.hasAutoCounter;
                        payload.auto_counter_name = item.autoCounterName;
                        payload.is_xp_upgradeable = item.isXPUpgradeable;
                        payload.effects = item.effects || [];
                    } else if (typeCfg.key === 'skills' || typeCfg.key === 'backgrounds') {
                        payload.is_variable = item.isVariable;
                        if (typeCfg.key === 'skills') payload.mystic_ability_id = item.mysticAbilityId;
                    } else if (typeCfg.key === 'mysticAbilities') {
                        payload.is_variable = item.isVariable;
                        payload.default_category = item.defaultCategory;
                    } else if (typeCfg.key === 'counters') {
                        payload.max_value = item.maxValue;
                        payload.default_value = item.defaultValue;
                        payload.xp_cost = item.xpCost;
                        payload.formula_id = item.formulaId || null;
                    } else if (typeCfg.key === 'specializations') {
                        payload.skill_ids = item.skillIds;
                        payload.default_min_level = item.defaultMinLevel;
                        payload.is_imposed = item.isImposed;
                    } else if (typeCfg.key === 'formulas') {
                        payload.formula = item.formula;
                        payload.type = item.type;
                        payload.target = item.target;
                        payload.effect_type = item.effectType;
                        payload.aggregate_config = item.aggregateConfig;
                        payload.operator = item.operator;
                        payload.force_variant = !!item.forceVariant;
                    }

                    toCreate.push(payload);
                    const link: any = { setting_id: settingId, [typeCfg.idKey]: item.id, is_active: true };
                    if (typeCfg.key === 'skills' || typeCfg.key === 'backgrounds' || typeCfg.key === 'counters' || typeCfg.key === 'mysticAbilities') {
                        link.default_category = item.defaultCategory;
                    }
                    toLink.push(link);
                }
            });

            if (toCreate.length > 0) await DatabaseService.insert(typeCfg.table, toCreate, `LibraryPersistence.persistInitial.${typeCfg.key}.create`);
            if (toLink.length > 0) await DatabaseService.insert(typeCfg.rel, toLink, `LibraryPersistence.persistInitial.${typeCfg.key}.links`);
        }
    },

    /**
     * Delete and Re-insert libraries (Standard Sync Strategy)
     */
    async syncLibraries(settingId: string, rules: RulesData) {
        for (const typeCfg of LIBRARY_TYPE_CONFIG) {
            const currentItems = (rules.libraries as any)[typeCfg.key] || [];

            // 0. Track current linked items to detect deletions
            const { data: oldLinks } = await supabase.from(typeCfg.rel).select(typeCfg.idKey).eq('setting_id', settingId);
            const oldIds = new Set<string>(oldLinks?.map((l: any) => l[typeCfg.idKey]) || []);

            // 1. UPSERT Global Repository items
            for (const item of currentItems) {
                const payload: any = {
                    id: item.id, // Mandatory for upsert
                    name: item.name,
                    code: item.code,
                    description: item.description,
                    setting_id: null // Ensure it's marked as Global in the repository
                };

                if (typeCfg.key === 'traits') {
                    payload.type = item.type;
                    payload.cost = item.cost || '0';
                    payload.points_label = item.pointsLabel || item.cost;
                    payload.is_variable_cost = item.isVariableCost || false;
                    payload.tags = item.tags;
                    payload.is_variable = item.isVariable;
                    payload.has_auto_counter = item.hasAutoCounter;
                    payload.auto_counter_name = item.autoCounterName;
                    payload.is_xp_upgradeable = item.isXPUpgradeable;
                    payload.effects = item.effects;
                } else if (typeCfg.key === 'skills' || typeCfg.key === 'backgrounds') {
                    payload.is_variable = !!item.isVariable;
                    if (typeCfg.key === 'skills') {
                        // SURGICAL: If it's a customization in a setting, do not overwrite global mystic link
                        if (item.isCustomized && settingId) {
                            // We skip upserting the global entry if it's already there and we are only customizing locally.
                            // If it's a new item (no ID or not in DB), we might still want to create it?
                            // But usually customized means it exists.
                            // Let's check if it's global.
                            if (item.isGlobal) {
                                // Skip global upsert for modified global items to protect the library
                                continue;
                            }
                        }
                        payload.mystic_ability_id = item.mysticAbilityId || null;
                    }
                } else if (typeCfg.key === 'mysticAbilities') {
                    payload.is_variable = item.isVariable;
                    payload.default_category = item.defaultCategory;
                } else if (typeCfg.key === 'counters') {
                    payload.max_value = item.maxValue;
                    payload.default_value = item.defaultValue;
                    payload.xp_cost = item.xpCost;
                    payload.formula_id = item.formulaId || null;
                } else if (typeCfg.key === 'specializations') {
                    payload.skill_ids = item.skillIds;
                    payload.default_min_level = item.defaultMinLevel;
                    payload.is_imposed = item.isImposed;
                } else if (typeCfg.key === 'formulas') {
                    payload.formula = item.formula;
                    payload.type = item.type;
                    payload.target = item.target;
                    payload.effect_type = item.effectType;
                    payload.aggregate_config = item.aggregateConfig;
                    payload.operator = item.operator;
                    payload.force_variant = !!item.forceVariant;
                }

                // Use UPSERT instead of update to handle newly created items from the UI
                await DatabaseService.upsert(typeCfg.table, payload, {}, `LibraryPersistence.sync.${typeCfg.key}.upsertGlobal`);
            }

            // 2. Refresh RELATIONSHIPS (Preserve all library items in linked state for this campaign)
            await DatabaseService.deleteBy(typeCfg.rel, 'setting_id', settingId, `LibraryPersistence.sync.${typeCfg.key}.deleteLinks`);
            if (currentItems.length > 0) {
                const relPayload = currentItems.map((item: any) => {
                    const link: any = {
                        setting_id: settingId,
                        [typeCfg.idKey]: item.id,
                        is_active: item.isActive !== false
                    };
                    // Skills, backgrounds, counters and mystic abilities have default categories
                    if (typeCfg.key === 'skills' || typeCfg.key === 'backgrounds' || typeCfg.key === 'counters' || typeCfg.key === 'mysticAbilities') {
                        link.default_category = item.defaultCategory;
                    }

                    // SKILL OVERRIDES
                    if (typeCfg.key === 'skills' && item.isCustomized) {
                        link.name_override = item.name;
                        link.is_variable_override = !!item.isVariable;
                        link.mystic_ability_id_override = item.mysticAbilityId;
                        link.description_override = item.description;
                    }
                    return link;
                });
                await DatabaseService.insert(typeCfg.rel, relPayload, `LibraryPersistence.sync.${typeCfg.key}.insertLinks`);
            }

            // 3. Refresh VARIANTS (if applicable)
            if ('variants' in typeCfg && typeCfg.variants) {
                const variantsTable = typeCfg.variants as string;

                // A. Delete all LOCAL variants for this setting
                await DatabaseService.deleteBy(variantsTable, 'setting_id', settingId, `LibraryPersistence.sync.${typeCfg.key}.deleteVariants`);

                // B. Surgical cleanup for GLOBAL variants of the items we are processing
                const globalItemIds = currentItems
                    .filter((i: any) => i.isGlobal && !i.isCustomized)
                    .map((i: any) => i.id);

                if (globalItemIds.length > 0) {
                    await supabase.from(variantsTable)
                        .delete()
                        .in(typeCfg.idKey, globalItemIds)
                        .is('setting_id', null);
                }

                const variantsPayload: any[] = [];
                currentItems.forEach((item: any) => {
                    if (item.variants && item.variants.length > 0) {
                        const isGlobalItem = item.isGlobal && !item.isCustomized;
                        const targetSid = isGlobalItem ? null : settingId;

                        item.variants.forEach((v: string) => {
                            variantsPayload.push({
                                [typeCfg.idKey]: item.id,
                                setting_id: targetSid,
                                name: v
                            });
                        });
                    }
                });

                if (variantsPayload.length > 0) {
                    await DatabaseService.insert(variantsTable, variantsPayload, `LibraryPersistence.sync.${typeCfg.key}.insertVariants`);
                }
            }

            // 4. CLEANUP ORPHANS (Items removed from this campaign that are no longer used anywhere)
            const currentIds = new Set(currentItems.map((i: any) => i.id));
            const removedIds = [...oldIds].filter(id => !currentIds.has(id));

            if (removedIds.length > 0) {
                for (const rid of removedIds) {
                    // Check if still used by ANY other campaign
                    const { count: relCount } = await supabase
                        .from(typeCfg.rel)
                        .select('*', { count: 'exact', head: true })
                        .eq(typeCfg.idKey, rid);

                    if (!relCount || relCount === 0) {
                        // Additional check for mystic abilities (used as overrides or in master skill table)
                        if (typeCfg.key === 'mysticAbilities') {
                            const { count: skillLinkCount } = await supabase.from('libraries_skills').select('*', { count: 'exact', head: true }).eq('mystic_ability_id', rid);
                            const { count: overrideLinkCount } = await supabase.from('rel_setting_skills').select('*', { count: 'exact', head: true }).eq('mystic_ability_id_override', rid);
                            if (skillLinkCount === 0 && overrideLinkCount === 0) {
                                await DatabaseService.delete(typeCfg.table, rid, `LibraryPersistence.sync.${typeCfg.key}.deleteOrphan`);
                            }
                        } else {
                            await DatabaseService.delete(typeCfg.table, rid, `LibraryPersistence.sync.${typeCfg.key}.deleteOrphan`);
                        }
                    }
                }
            }
        }
    }
};

import { PAGE_WIDTH, PAGE_CONTENT_HEIGHT, PAGE_CONTENT_WIDTH } from '../../components/campaign/constants';
import { logger } from '../logger';

const BUDGET_BUFFER = 0; // Removing safety margin to match editor exactly

/**
 * Creates an HTMLElement from an HTML string.
 */
function createElementFromHtml(html: string): HTMLElement {
    const template = document.createElement('template');
    template.innerHTML = html.trim();
    return (template.content.firstElementChild as HTMLElement) || document.createElement('div');
}

/**
 * Measures the total height of a set of HTML blocks as they would appear on a page.
 * Crucial: Includes margin collapse and uses the same typography context.
 */
function measureContentHeight(htmls: string[]): number {
    const temp = document.createElement('div');
    temp.className = 'book-page-content';
    temp.style.width = `${PAGE_WIDTH}px`;
    temp.style.padding = '0'; // Remove padding to allow margin collapse matching scrollHeight
    temp.style.position = 'absolute';
    temp.style.visibility = 'hidden';
    temp.style.top = '0';
    temp.style.left = '-9999px';
    temp.innerHTML = htmls.join('');
    document.body.appendChild(temp);

    // No padding subtraction needed
    const height = temp.offsetHeight;
    document.body.removeChild(temp);
    return height;
}

/**
 * Splits HTML content into pages of fixed height.
 */
export function splitIntoPages(html: string, pageHeight: number = PAGE_CONTENT_HEIGHT): string[] {
    if (!html || html.trim() === '' || html === '<p></p>') {
        return ['<p style="color:#94a3b8;font-style:italic;">Page vide</p>'];
    }

    const targetHeight = pageHeight - BUDGET_BUFFER;

    // Step 1: Parse HTML into separate blocks
    const parser = document.createElement('div');
    parser.innerHTML = html;
    const blockElements = Array.from(parser.children) as HTMLElement[];

    interface Block {
        html: string;
        isSplittable: boolean;
        isChapterHeader: boolean;
    }

    const blocks: Block[] = blockElements.map(el => ({
        html: el.outerHTML,
        isSplittable: !el.tagName.toLowerCase().startsWith('h') &&
            !el.classList.contains('chapter-header-wrapper') &&
            el.tagName.toLowerCase() !== 'figure' &&
            el.querySelector('img') === null,
        isChapterHeader: el.classList.contains('chapter-header-wrapper')
    }));

    // Step 2: Distribute into pages
    const pages: string[] = [];
    let currentPageBlocks: string[] = [];
    const blockQueue: Block[] = [...blocks];

    while (blockQueue.length > 0) {
        const block = blockQueue.shift()!;

        // Rule: Chapter headers always start a new page
        if (block.isChapterHeader && currentPageBlocks.length > 0) {
            pages.push(currentPageBlocks.join(''));
            currentPageBlocks = [];
        }

        const heightWithNewBlock = measureContentHeight([...currentPageBlocks, block.html]);

        if (heightWithNewBlock <= targetHeight) {
            currentPageBlocks.push(block.html);
        } else {
            // Block doesn't fit
            if (block.isSplittable) {
                // Try to split it
                const remainingSpace = targetHeight - measureContentHeight(currentPageBlocks);

                // If we have literally no space left, just move to next page
                if (remainingSpace < 10 && currentPageBlocks.length > 0) {
                    pages.push(currentPageBlocks.join(''));
                    currentPageBlocks = [];
                    blockQueue.unshift(block);
                    continue;
                }

                const splitResult = splitParagraph(block.html, targetHeight, currentPageBlocks);

                if (splitResult.firstPart) {
                    currentPageBlocks.push(splitResult.firstPart);
                    pages.push(currentPageBlocks.join(''));
                    currentPageBlocks = [];

                    if (splitResult.remainingParts.length > 0) {
                        const remainingBlocks: Block[] = splitResult.remainingParts.map(h => ({
                            html: h,
                            isSplittable: true,
                            isChapterHeader: false
                        }));
                        blockQueue.unshift(...remainingBlocks);
                    }
                } else {
                    // Cannot split even a bit, move whole block to next page
                    if (currentPageBlocks.length > 0) {
                        pages.push(currentPageBlocks.join(''));
                        currentPageBlocks = [];
                        blockQueue.unshift(block);
                    } else {
                        // Page is empty but block still doesn't fit? Force it to avoid loop
                        currentPageBlocks.push(block.html);
                        pages.push(currentPageBlocks.join(''));
                        currentPageBlocks = [];
                    }
                }
            } else {
                // Not splittable (heading, image, etc.)
                if (currentPageBlocks.length > 0) {
                    pages.push(currentPageBlocks.join(''));
                    currentPageBlocks = [];
                    blockQueue.unshift(block);
                } else {
                    // Force non-splittable block on empty page
                    currentPageBlocks.push(block.html);
                    pages.push(currentPageBlocks.join(''));
                    currentPageBlocks = [];
                }
            }
        }
    }

    if (currentPageBlocks.length > 0) {
        pages.push(currentPageBlocks.join(''));
    }

    logger.info(`[BookPageSplitter] Created ${pages.length} pages.`);
    return pages.length > 0 ? pages : ['<p style="color:#94a3b8;font-style:italic;">Page vide</p>'];
}

/**
 * Splits a paragraph into two parts.
 * Uses Binary Search for performance and cumulative measurement for accuracy.
 */
function splitParagraph(
    blockHtml: string,
    targetHeight: number,
    existingHtml: string[]
): { firstPart: string | null; remainingParts: string[] } {
    const element = createElementFromHtml(blockHtml);
    const text = element.textContent || '';

    if (text.length < 1) return { firstPart: null, remainingParts: [blockHtml] };

    // Split into tokens (preserving spaces)
    const tokens = text.split(/(\s+)/);

    // We'll use a single container for multiple measurements
    const measureContainer = document.createElement('div');
    measureContainer.className = 'book-page-content';
    measureContainer.style.width = `${PAGE_WIDTH}px`;
    measureContainer.style.padding = '0';
    measureContainer.style.position = 'absolute';
    measureContainer.style.visibility = 'hidden';
    measureContainer.style.top = '0';
    measureContainer.style.left = '-9999px';
    document.body.appendChild(measureContainer);

    // Context from previous blocks on the same page
    const prefixHtml = existingHtml.join('');

    // Range-based splitting helper
    const sourceDiv = document.createElement('div');
    sourceDiv.className = 'book-page-content';
    sourceDiv.style.width = `${PAGE_WIDTH}px`;
    sourceDiv.style.position = 'absolute';
    sourceDiv.style.left = '-9999px';
    sourceDiv.innerHTML = blockHtml;
    document.body.appendChild(sourceDiv);
    const sourceEl = sourceDiv.firstElementChild as HTMLElement;

    function getTextNodes(el: Node): { node: Text; start: number; end: number }[] {
        const nodes: { node: Text; start: number; end: number }[] = [];
        let offset = 0;
        const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
        let node: Text | null = walker.nextNode() as Text | null;
        while (node) {
            const len = node.textContent?.length || 0;
            nodes.push({ node, start: offset, end: offset + len });
            offset += len;
            node = walker.nextNode() as Text | null;
        }
        return nodes;
    }

    const textNodes = getTextNodes(sourceEl);

    function measureWithChars(charCount: number): number {
        if (charCount <= 0) return measureContentHeight(existingHtml);

        const endInfo = textNodes.find(n => charCount <= n.end) || textNodes[textNodes.length - 1];
        const offsetInNode = Math.min(charCount - endInfo.start, endInfo.node.textContent?.length || 0);

        const range = document.createRange();
        range.setStart(textNodes[0].node, 0);
        range.setEnd(endInfo.node, Math.max(0, offsetInNode));

        const frag = range.cloneContents();
        const wrap = sourceEl.cloneNode(false) as HTMLElement;
        wrap.appendChild(frag);

        measureContainer.innerHTML = prefixHtml + wrap.outerHTML;
        return measureContainer.offsetHeight;
    }

    // Binary search for the split point
    let low = 0;
    let high = tokens.length;
    let bestTokenIndex = 0;

    while (low <= high) {
        const mid = Math.floor((low + high) / 2);
        const charCount = tokens.slice(0, mid).join('').length;
        const height = measureWithChars(charCount);

        if (height <= targetHeight) {
            bestTokenIndex = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }

    const finalCharCount = tokens.slice(0, bestTokenIndex).join('').length;
    let result: { firstPart: string | null; remainingParts: string[] };

    if (finalCharCount > 0 && finalCharCount < text.length) {
        // Build parts using the final char count
        const endInfo = textNodes.find(n => finalCharCount <= n.end)!;

        const r1 = document.createRange();
        r1.setStart(textNodes[0].node, 0);
        r1.setEnd(endInfo.node, finalCharCount - endInfo.start);
        const w1 = sourceEl.cloneNode(false) as HTMLElement;
        w1.appendChild(r1.cloneContents());

        const r2 = document.createRange();
        r2.setStart(endInfo.node, finalCharCount - endInfo.start);
        r2.setEndAfter(sourceEl.lastChild!);
        const w2 = sourceEl.cloneNode(false) as HTMLElement;
        w2.appendChild(r2.cloneContents());

        result = { firstPart: w1.outerHTML, remainingParts: [w2.outerHTML] };
    } else {
        result = { firstPart: null, remainingParts: [blockHtml] };
    }

    document.body.removeChild(measureContainer);
    document.body.removeChild(sourceDiv);
    return result;
}

import {
    CharacterSheetData,
    ExperienceData,
    ExperienceBreakdownItem,
    TraitEffect,
    RulesData
} from '../../types';
import { normalizeString } from '../stringUtils';
import { calculateAttributeXP } from './xp/attributeXP';
import { calculateTraitXP } from './xp/traitXP';
import { calculateCounterXP } from './xp/counterXP';
import { calculateSkillXP } from './xp/skillXP';
import { evaluateFormula } from '../formulaEvaluator';
import { logger } from '../../utils/logger';

export { triangular, getXPCost } from './xp/xpCore';

interface ActiveEffect extends TraitEffect {
    traitLevel: number;
}

/**
 * Calcule le bilan d'XP complet pour un personnage
 */
export const calculateExperienceResults = (data: CharacterSheetData, rules?: RulesData): ExperienceData => {
    // 0. Extraction des effets actifs des traits
    const activeEffects: ActiveEffect[] = getActiveTraitEffects(data, rules);

    // 1. Helpers pour les bonus
    const getFreeRankLimit = (skillName: string) => {
        const normalizedSkillName = skillName.trim().toLowerCase();

        // 1. Bonus via trait effects (including formula-derived ones)
        const effect = activeEffects.find(e => {
            const effectiveType = (e as any).inferredEffectType || e.type;
            const effectiveTarget = e.target || (e as any).inferredTarget;

            return (effectiveType === 'free_skill_rank' ||
                (effectiveType === 'formula' && effectiveTarget === skillName)) &&
                effectiveTarget &&
                normalizedSkillName === effectiveTarget.trim().toLowerCase();
        });

        if (effect) return effect.value;

        // 2. Comp├®tence ma├«tris├®e via master_skill : rang 5 enti├¿rement gratuit
        const hasMasterEffect = activeEffects.some(e => {
            const effectiveType = (e as any).inferredEffectType || e.type;
            const effectiveTarget = e.target || (e as any).inferredTarget;

            return effectiveType === 'master_skill' &&
                effectiveTarget &&
                effectiveTarget.trim().toLowerCase() === normalizedSkillName;
        });

        // Backward compatibility for old masterSkillTarget field on traits
        const hasLegacyMasterEffect = [
            ...(data.page2?.avantages || []),
            ...(data.page2?.desavantages || [])
        ].some(trait =>
            trait.masterSkillTarget &&
            trait.masterSkillTarget.trim().toLowerCase() === normalizedSkillName
        );

        if (hasMasterEffect || hasLegacyMasterEffect) return 5;

        return 0;
    };

    // Calcul des bonus XP via Formules
    const xpFormulaEffects = activeEffects.filter(e => {
        const effectiveType = (e as any).inferredEffectType || e.type;
        const effectiveTarget = e.target || (e as any).inferredTarget;
        return (effectiveType === 'formula' || effectiveType === 'xp_bonus') &&
            effectiveTarget && effectiveTarget.trim().toUpperCase() === 'XP';
    });

    const scenarioLogs = (data.xpLogs || []).filter(log =>
        log.countsAsScenario !== undefined
            ? log.countsAsScenario
            : (log.amount > 0 || (log.scenario && log.scenario.trim() !== ''))
    );
    const scenarioCount = scenarioLogs.length;

    let totalTraitXP = 0;
    const formulaBonusBreakdown: ExperienceBreakdownItem[] = [];

    xpFormulaEffects.forEach(e => {
        // Resolve formula string: already enriched by getActiveTraitEffects
        const formulaString = e.formula;

        if (!formulaString) {
            logger.warn(`Formula string empty for XP effect from ${e.source}`);
            return;
        }

        try {
            const result = evaluateFormula(formulaString, data, {
                traitLevel: e.traitLevel,
                scenariosCount: scenarioCount
            });

            if (result !== 0) {
                // Operator is already in e (either from trait or enriched from global)
                const operator = e.operator || 'ADD';

                if (operator === 'SET') {
                    // Logic for SET in XP gain is tricky, we treat it as "at least this amount" or "reset to this"
                    // but for XP bonus it's usually incremental.
                    // For now, let's just make it additive to not break history, but log correctly.
                    totalTraitXP += result;
                } else if (operator === 'SUB') {
                    totalTraitXP -= result;
                } else {
                    totalTraitXP += result;
                }

                formulaBonusBreakdown.push({
                    name: `Bonus : ${e.source || 'Trait'}`,
                    amount: operator === 'SUB' ? -result : result
                });
            }
        } catch (err) {
            logger.error(`Error calculating XP formula for trait ${e.source}:`, err);
        }
    });

    // Gains de base (Log)
    const baseGainsBreakdown: ExperienceBreakdownItem[] = (data.xpLogs || [])
        .filter(entry => entry.amount !== 0)
        .map(entry => ({
            name: entry.scenario || (entry.date ? `Session ${entry.date}` : 'Gain divers'),
            amount: entry.amount
        }));

    const gainFromLogs = baseGainsBreakdown.reduce((sum, e) => sum + e.amount, 0);
    const totalGain = gainFromLogs + totalTraitXP;

    // 2. Calcul de l'XP d├®pens├®e
    const handledCounters = new Set<string>();

    const skillResult = calculateSkillXP(data, rules, getFreeRankLimit, handledCounters);
    const counterResult = calculateCounterXP(data, rules, handledCounters);
    const attributeResult = calculateAttributeXP(data);
    const traitResult = calculateTraitXP(data, rules);

    const totalSpent = skillResult.total + counterResult.total + attributeResult.total + traitResult.total;

    // 3. Construction du bilan final
    let gainDisplay = totalGain.toString();
    const tooltip = `Total : ${totalGain} XP\n\nBase (Historique) : ${gainFromLogs}`;

    if (totalTraitXP > 0) {
        gainDisplay += ` (+${totalTraitXP})`;
    }

    return {
        gain: gainDisplay,
        gainTooltip: tooltip,
        spent: totalSpent.toString(),
        rest: (totalGain - totalSpent).toString(),
        breakdown: {
            gains: [...baseGainsBreakdown, ...formulaBonusBreakdown],
            attributes: attributeResult.breakdown,
            skills: skillResult.breakdown,
            traits: traitResult.breakdown,
            counters: counterResult.breakdown
        }
    };
};

/**
 * Extrait tous les effets de traits actifs du personnage
 * Recherche d'abord dans la biblioth├¿que locale, puis dans les r├¿gles globales
 */
function getActiveTraitEffects(data: CharacterSheetData, rules?: RulesData): ActiveEffect[] {
    const activeEffects: ActiveEffect[] = [];

    const globalTraits = rules?.libraries?.traits || [];
    const globalTraitMap = new Map(globalTraits.map(t => [normalizeString(t.name), t]));

    const findEffects = (traitName: string, traitLevel: number) => {
        if (!traitName) return;
        const normalizedName = normalizeString(traitName);

        // helper to enrich effect with global formula data
        const enrichEffect = (e: TraitEffect, source: string): ActiveEffect => {
            const active: any = { ...e, source, traitLevel };
            if (e.formulaId && rules?.libraries?.formulas) {
                const global = rules.libraries.formulas.find(f => f.id === e.formulaId);
                if (global) {
                    if (global.target) active.inferredTarget = global.target;
                    if (global.effectType) active.inferredEffectType = global.effectType;
                    if (global.formula) active.formula = global.formula;
                    if (global.operator && !active.operator) active.operator = global.operator;
                }
            }
            return active;
        };

        // 1. Recherche Local
        const localEntry = data.library?.find(l => normalizeString(l.name) === normalizedName);
        if (localEntry && localEntry.effects && localEntry.effects.length > 0) {
            localEntry.effects.forEach(e => activeEffects.push(enrichEffect(e, localEntry.name)));
            return;
        }

        // 2. Recherche Global
        const globalEntry = globalTraitMap.get(normalizedName);
        if (globalEntry && globalEntry.effects && globalEntry.effects.length > 0) {
            globalEntry.effects.forEach(e => activeEffects.push(enrichEffect(e, globalEntry.name)));
        }
    };

    data.page2?.avantages?.forEach(t => findEffects(t.name, parseInt(t.value?.toString() || '1') || 1));
    data.page2?.desavantages?.forEach(t => findEffects(t.name, parseInt(t.value?.toString() || '1') || 1));
    return activeEffects;
}

import { CharacterSheetData } from '../types';

// --- RESET LOGIC ---
/**
 * Reset COMPLET d'une fiche (Table Rase totale).
 * Utilis├® pour red├®marrer un personnage de z├®ro.
 */
export const resetCharacterValues = (source: CharacterSheetData): CharacterSheetData => {
    const clean = JSON.parse(JSON.stringify(source));

    // Reset Header
    Object.keys(clean.header).forEach((k: keyof typeof clean.header) => clean.header[k] = "");

    // Reset XP & Logs
    clean.experience = { gain: '0', spent: '0', rest: '0' };
    clean.xpLogs = [];
    clean.appLogs = [];

    // Attributes
    if (clean.attributes) {
        Object.keys(clean.attributes).forEach((cat: string) => {
            if (Array.isArray(clean.attributes[cat])) {
                clean.attributes[cat].forEach((attr: any) => {
                    attr.val1 = ""; attr.val2 = ""; attr.val3 = "";
                    attr.creationVal1 = 0; attr.creationVal2 = 0; attr.creationVal3 = 0;
                });
            }
        });
    }

    // Secondary Attributes
    if (clean.secondaryAttributes) {
        Object.keys(clean.secondaryAttributes).forEach((cat: string) => {
            if (Array.isArray(clean.secondaryAttributes[cat])) {
                clean.secondaryAttributes[cat].forEach((attr: any) => {
                    attr.val1 = ""; attr.val2 = ""; attr.val3 = "";
                    attr.creationVal1 = 0; attr.creationVal2 = 0; attr.creationVal3 = 0;
                });
            }
        });
    }

    // Skills
    Object.keys(clean.skills).forEach((cat: string) => {
        clean.skills[cat].forEach((skill: any) => {
            skill.value = 0;
            skill.creationValue = 0;
            if (typeof skill.current !== 'undefined') skill.current = 0;
        });
    });

    // Combat
    clean.combat.weapons.forEach((w: any) => { w.weapon = ""; w.level = ""; w.init = ""; w.attack = ""; w.damage = ""; w.parry = ""; });
    clean.combat.armor.forEach((a: any) => { a.type = ""; a.protection = ""; a.weight = ""; });
    clean.combat.stats = { agility: '', dexterity: '', force: '', size: '' };

    // Page 2
    clean.page2.lieux_importants = "";
    clean.page2.contacts = "";
    clean.page2.reputation.forEach((r: any) => { r.reputation = ''; r.lieu = ''; r.valeur = ''; });
    clean.page2.connaissances = "";
    clean.page2.valeurs_monetaires = "";
    clean.page2.armes_list = "";
    clean.page2.avantages = Array(28).fill(null).map(() => ({ name: '', value: '' }));
    clean.page2.desavantages = Array(28).fill(null).map(() => ({ name: '', value: '' }));
    clean.page2.equipement = "";
    clean.page2.notes = "";
    clean.page2.characterImage = "";
    clean.page2.characterImageId = undefined;

    // Specializations
    clean.specializations = {};

    // Campaign Notes
    clean.campaignNotes = [];

    // Counters
    if (clean.counters?.volonte) {
        clean.counters.volonte.value = 3; clean.counters.volonte.creationValue = 3; clean.counters.volonte.current = 0;
    }
    if (clean.counters?.confiance) {
        clean.counters.confiance.value = 3; clean.counters.confiance.creationValue = 3; clean.counters.confiance.current = 0;
    }
    if (clean.counters?.custom) {
        clean.counters.custom.forEach((c: any) => { c.value = 0; c.creationValue = 0; c.current = 0; });
    }

    return clean;
};

