import { Parser, Tokenizer } from 'safe-expr-eval';
import { CharacterSheetData } from '../types';
import { normalizeString, smartIncludes } from './stringUtils';

const parser = new Parser();

const getExpressionVariables = (formula: string): string[] => {
    try {
        const tokenizer = new Tokenizer(formula);
        const tokens = tokenizer.tokenize();
        return Array.from(new Set(
            tokens
                .filter(t => t.type === 'IDENTIFIER')
                .map(t => String(t.value))
                .filter(v => v !== 'true' && v !== 'false')
        ));
    } catch {
        return [];
    }
};

/**
 * Extracts a map of variable names to their values from the character sheet.
 * Includes static values (attributes, skills) and aggregate calculations.
 */
export const getSheetVariables = (data: CharacterSheetData & { variables?: Record<string, number> }): Record<string, number> => {
    const vars: Record<string, number> = {};

    // 0. Explicit variables passed in (e.g., TRAIT_LEVEL)
    if (data.variables) {
        Object.assign(vars, data.variables);
    }

    // 1. Special Variables

    // 2. Skills (Lower priority, might be overwritten by attributes/counters)
    if (data.skills) {
        Object.values(data.skills).flat().forEach(skill => {
            if (skill.name) {
                const name = skill.name.trim();
                const val = skill.value || 0;
                vars[name] = val;

                const normalized = normalizeString(name);
                if (normalized !== name.toLowerCase()) {
                    vars[normalized] = val;
                }
            }
        });
    }

    // 3. Counters
    if (data.counters) {
        Object.entries(data.counters).forEach(([key, value]) => {
            if (key === 'custom' && Array.isArray(value)) {
                value.forEach(c => {
                    if (c.name) {
                        const name = c.name.trim();
                        vars[name] = c.value || 0;
                        const normalized = normalizeString(name);
                        if (normalized !== name.toLowerCase()) vars[normalized] = c.value || 0;
                    }
                });
            } else if (value && !Array.isArray(value)) {
                const val = (value as any).value || 0;
                vars[key] = val;
                if ((value as any).name) {
                    const name = (value as any).name.trim();
                    vars[name] = val;
                    const normalized = normalizeString(name);
                    if (normalized !== name.toLowerCase()) vars[normalized] = val;
                }
            }
        });
    }

    // 4. Secondary Attributes
    if (data.secondaryAttributes) {
        Object.values(data.secondaryAttributes).flat().forEach(attr => {
            if (attr.name) {
                const name = attr.name.trim();
                const total = (parseInt(attr.val1) || 0) + (parseInt(attr.val2) || 0) + (parseInt(attr.val3) || 0);
                vars[name] = total;
                const normalized = normalizeString(name);
                if (normalized !== name.toLowerCase()) vars[normalized] = total;
            }
        });
    }

    // 5. Attributes (High priority for core attributes like Volont├®)
    if (data.attributes) {
        Object.values(data.attributes).flat().forEach(attr => {
            if (attr.name) {
                const name = attr.name.trim();
                const v1 = parseInt(attr.val1) || 0;
                const v2 = parseInt(attr.val2) || 0;
                const v3 = parseInt(attr.val3) || 0;
                const total = v1 + v2 + v3;

                vars[name] = total;
                // Add normalized variant (e.g., Volonte for Volont├®)
                const normalized = normalizeString(name);
                if (normalized !== name.toLowerCase()) {
                    vars[normalized] = total;
                }
            }
        });
    }

    // 5. MJ Variables (from formulaLibrary) - RESOLVED LAST TO HAVE PRIORITY
    // We do multiple passes to resolve dependencies between variables
    if (data.formulaLibrary && Array.isArray(data.formulaLibrary)) {
        const variableEntries = data.formulaLibrary.filter(f => f.type === 'variable');


        const memo = new Map<string, number>();
        const visiting = new Set<string>();

        const resolveGlobal = (name: string): number => {
            if (memo.has(name)) return memo.get(name)!;
            const entry = variableEntries.find(f => (f.code && f.code === name) || f.name === name);
            if (!entry || visiting.has(name)) return vars[name] || 0;

            visiting.add(name);
            try {
                let result = 0;
                if (entry.aggregateConfig) {
                    result = calculateAggregate(data, entry.aggregateConfig);
                } else if (entry.formula) {
                    result = evaluateWithContext(entry.formula, { ...vars, ...Object.fromEntries(memo) }, resolveGlobal);
                }
                memo.set(name, result);
                return result;
            } catch {
                return 0;
            } finally {
                visiting.delete(name);
            }
        };

        // Pass 1: Resolve all MJ variables to populate the memo
        variableEntries.forEach(f => {
            const varName = f.code || f.name;
            if (varName) resolveGlobal(varName);
        });

        // Pass 2: Inject everything from memo into vars
        memo.forEach((val, varName) => {
            vars[varName] = val;
            // Also add normalized variant for MJ variables
            const normalized = normalizeString(varName);
            if (normalized !== varName.toLowerCase()) vars[normalized] = val;
        });
    }


    return vars;
};

/**
 * Pure evaluation function that doesn't re-calculate the whole sheet.
 */
const evaluateWithContext = (formula: string, context: Record<string, number>, resolver?: (name: string) => number): number => {
    if (!formula) return 0;
    try {
        const expr = parser.parse(formula);

        // Custom resolver for missing variables if needed
        if (resolver) {
            getExpressionVariables(formula).forEach(v => {
                if (context[v] === undefined) {
                    context[v] = resolver(v);
                }
            });
        }

        const result = expr.evaluate(context);
        return isNaN(result) ? 0 : Math.floor(Number(result));
    } catch {
        return 0;
    }
};

/**
 * Gets the specific elements involved in an aggregate calculation (e.g. all mystic skills)
 */
export const getAggregateDetails = (data: any, config: any): { name: string, value: number, category?: string, tag?: string }[] => {
    let baseList: any[] = [];
    const targetType = config.targetType || config.target; // Support both names

    switch (targetType) {
        case 'skills':
            // Inject category/tag metadata from the map keys and definitions
            if (data.skills) {
                Object.entries(data.skills).forEach(([catId, skills]) => {
                    (skills as any[]).forEach(skill => {
                        let tagFallback = skill.tag || catId;

                        // 1. Direct check on the skill object (historical/migrated data)
                        if (skill.mysticAbilityId) {
                            tagFallback += ' Mystique';
                        }
                        // 2. Cross-reference with definitions (local library)
                        else if (data.skillLibrary) {
                            // Match by definitionId OR by normalized name fallback
                            const def = data.skillLibrary.find((d: any) =>
                                (skill.definitionId && d.id === skill.definitionId) ||
                                (skill.name && d.name && normalizeString(skill.name) === normalizeString(d.name))
                            );
                            if (def && def.mysticAbilityId) {
                                tagFallback += ' Mystique';
                            }
                        }

                        baseList.push({
                            ...skill,
                            category: catId,
                            tag: tagFallback
                        });
                    });
                });
            }
            break;
        case 'attributes':
            baseList = Object.values(data.attributes || {}).flat();
            break;
        case 'secondaryAttributes':
            baseList = Object.values(data.secondaryAttributes || {}).flat();
            break;
        case 'traits': {
            const traitSources = [
                ...(data.page2?.avantages || []),
                ...(data.page2?.desavantages || [])
            ];
            baseList = traitSources.map((t: any) => {
                // Resolve tag from mysticAbilityId if explicit tag is missing
                let resolvedTag = t.tag || '';
                if (!resolvedTag && t.mysticAbilityId) {
                    resolvedTag = 'Mystique';
                }
                // Normalize numeric value (trait.value is a string like '2')
                const numericValue = typeof t.value === 'number' ? t.value
                    : typeof t.value === 'string' ? (parseInt(t.value, 10) || 0)
                        : 0;
                return { ...t, tag: resolvedTag, value: numericValue };
            });
            break;
        }
        case 'mysticAbilities':
            baseList = (data.mysticAbilities || []).filter((s: any) => typeof s !== 'string');
            break;
        default: return [];
    }

    // Apply filtering
    let filteredList = baseList;
    if (config.filterTarget && config.filterValue) {
        if (config.filterTarget === 'tag') {
            filteredList = baseList.filter(item =>
                smartIncludes(item.tag, config.filterValue) ||
                smartIncludes(item.category, config.filterValue)
            );
        } else if (config.filterTarget === 'category') {
            filteredList = baseList.filter(item => smartIncludes(item.category, config.filterValue));
        } else if (config.filterTarget === 'name') {
            filteredList = baseList.filter(item => smartIncludes(item.name, config.filterValue));
        }
    }

    // Perform extraction
    const details = filteredList.map(item => {
        let value = 0;
        if (typeof item.value === 'number') {
            value = item.value;
        } else if (typeof item.value === 'string') {
            value = parseInt(item.value, 10) || 0;
        }
        // Attributes/Secondary Attributes: Sum val1 + val2 + val3
        else if (item.val1 !== undefined || item.val2 !== undefined || item.val3 !== undefined) {
            const v1 = parseInt(item.val1 || "0") || 0;
            const v2 = parseInt(item.val2 || "0") || 0;
            const v3 = parseInt(item.val3 || "0") || 0;
            value = v1 + v2 + v3;
        }
        else if (typeof item.level === 'number') {
            value = item.level; // Legacy traits or custom entries
        }

        return {
            name: item.name || '',
            value,
            category: item.category,
            tag: item.tag
        };
    });

    return details;
};

/**
 * Helper to calculate aggregate values (Sum of Skills, Max Attribute, etc.)
 */
export const calculateAggregate = (data: any, config: any): number => {
    const details = getAggregateDetails(data, config);
    if (details.length === 0) return 0;

    const op = config.operation?.toLowerCase();
    const values = details.map(d => d.value);

    const result = ((): number => {
        switch (op) {
            case 'sum': return values.reduce((a, b) => a + b, 0);
            case 'count': return values.filter(v => v > 0).length;
            case 'max':
            case 'highest': return Math.max(...values);
            case 'avg':
            case 'average': return values.length > 0 ? values.reduce((a, b) => a + b, 0) / values.length : 0;
            default: return 0;
        }
    })();

    return result;
};

/**
 * Evaluates a given formula against a character's state.
 */
export const evaluateFormula = (
    formula: string,
    data: CharacterSheetData & { variables?: Record<string, number> },
    options: {
        entry?: any,
        traitLevel?: number,
        scenariosCount?: number
    } = {}
): number => {
    // If it's an aggregate formula, calculate it directly
    if (options.entry?.aggregateConfig) {
        return calculateAggregate(data, options.entry.aggregateConfig);
    }

    if (!formula) return 0;

    try {
        const sheetVars = getSheetVariables(data);
        const context = { ...sheetVars };

        // Inject contextual variables from options
        if (options.traitLevel !== undefined) {
            context['TRAIT_LEVEL'] = options.traitLevel;
        }
        if (options.scenariosCount !== undefined) {
            context['SCENARIOS_COUNT'] = options.scenariosCount;
        }

        // Use safe-expr-eval parser
        const expr = parser.parse(formula);

        // Map undefined variables to 0 to prevent evaluation errors
        getExpressionVariables(formula).forEach((v: string) => {
            if (context[v] === undefined) context[v] = 0;
        });

        // Evaluate with safe context
        const result = expr.evaluate(context);


        return isNaN(result) ? 0 : Math.floor(Number(result));
    } catch (e) {
        // Fallback for rough editing
        return 0;
    }
};

import { RulesData } from '../types/rules';
import { Parser } from 'safe-expr-eval';

/**
 * V├®rifie si la syntaxe d'une formule est valide via expr-eval
 */
export const isFormulaSyntaxValid = (formula?: string): boolean => {
    if (!formula || formula.trim() === '') return true;
    try {
        const parser = new Parser();
        parser.parse(formula);
        return true;
    } catch (e) {
        return false;
    }
};

/**
 * V├®rifie si une cible existe dans les d├®finitions de r├¿gles
 */
export const isTargetValid = (target: string, rules: RulesData): boolean => {
    if (!target) return true;
    const cleanTarget = target.trim().toLowerCase();
    if (cleanTarget === 'xp' || cleanTarget === 'total') return true;

    // Check Attributes
    const allAttributes = Object.values(rules.definitions.attributes || {}).flat();
    if (allAttributes.some(a => a.toLowerCase() === cleanTarget)) return true;

    // Check Secondary
    const secondaryAttributes = Object.values(rules.definitions.secondaryAttributes || {}).flat();
    if (secondaryAttributes.some(a => a.toLowerCase() === cleanTarget)) return true;

    // Check Counters
    const allCounters = Object.values(rules.definitions.counters || {}).map(c => c.name);
    if (allCounters.some(c => c.toLowerCase() === cleanTarget)) return true;

    // Check Skills
    const allSkills = Object.values(rules.definitions.skills || {}).flat();
    if (allSkills.some(s => s.toLowerCase() === cleanTarget)) return true;

    const allLibSkills = rules.libraries.skills?.map(s => s.name) || [];
    if (allLibSkills.some(s => s.toLowerCase() === cleanTarget)) return true;

    return false;
};

import { LibraryFormulaEntry } from '../types';
import { RulesData } from '../types/rules';
import { isFormulaSyntaxValid, isTargetValid } from '../utils/formulaUtils';

export interface ValidationResult {
    status: 'valid' | 'warning' | 'error';
    message: string;
    isValid: boolean;
}

/**
 * Calcule le statut de validation d'une entr├®e de formule
 */
export const validateFormulaEntry = (
    counter: LibraryFormulaEntry,
    rules: RulesData
): ValidationResult => {
    let status: 'valid' | 'warning' | 'error' = 'valid';
    let message = "Formule compl├¿te et valide";

    // L'├®quation math├®matique doit ├¬tre analysable (sauf si c'est un agr├®gat auto)
    const isMathValid = counter.aggregateConfig ? true : isFormulaSyntaxValid(counter.formula);

    if (!isMathValid) {
        status = 'error';
        message = "Syntaxe math├®matique invalide";
    } else if (counter.type === 'modifier' || (counter as any).type === 'effect') {
        const hasTarget = !!(counter.target && counter.target.trim() !== '');
        const hasOperator = !!(counter.operator && (counter.operator as string) !== '');
        const hasEquation = !!(counter.formula && counter.formula.trim() !== '');
        const actualEffectType = counter.effectType || 'modifier';
        const hasEffectType = !!(actualEffectType && actualEffectType !== '');

        if (!hasEffectType) {
            status = 'error';
            message = "Type d'effet manquant";
        } else if (hasTarget && !counter.forceVariant && !isTargetValid(counter.target!, rules)) {
            status = 'error';
            message = `La cible '${counter.target}' n'existe pas dans les r├¿gles`;
        } else if ((!hasTarget && !counter.forceVariant) || !hasOperator || !hasEquation) {
            status = 'warning';
            message = "Mod├¿le incomplet (sera compl├®t├® dans le trait)";
        } else if (counter.forceVariant && !hasTarget) {
            status = 'warning';
            message = "Cible vide : Le joueur devra saisir le nom manuellement.";
        }
    } else {
        // Pour une variable simple
        if (!counter.formula || counter.formula.trim() === '') {
            status = 'warning';
            message = "├ëquation vide (sera compl├®t├®e dans le trait)";
        }
    }

    return {
        status,
        message,
        isValid: status !== 'error'
    };
};

import { CharacterSheetData, LibraryEntry, LibrarySkillEntry, LibrarySpecializationEntry, AttributeEntry, DotEntry, CombatEntry, ReputationEntry, TraitEntry } from '../types';
import { APP_VERSION } from '../constants/app';
import { getImage, blobToBase64 } from '../services/imageDB';
import { ImageCompressionService } from '../services/ImageCompressionService';
import { ImageSyncResolver } from '../services/ImageSyncResolver';
import { ErrorService } from '../services/ErrorService';

/**
 * Utility to export a character as JSON.
 * Extracted from ExportPanel for reuse in safety modals.
 */
export const exportCharacterAsJSON = async (data: CharacterSheetData, addLog?: (msg: string, type: 'info' | 'success' | 'danger', scope?: any) => void) => {
    const dataToProcess: CharacterSheetData = JSON.parse(JSON.stringify(data));

    // 1. Resolve Images from DB
    if (dataToProcess.page2?.characterImageId) {
        try {
            const blob = await getImage(dataToProcess.page2.characterImageId);
            if (blob) {
                const base64 = await blobToBase64(blob);
                dataToProcess.page2.characterImage = base64;
            }
        } catch (e) {
            ErrorService.handleError(e, { context: 'ExportCharacter', userMessage: "Impossible d'exporter l'image du personnage (BDD)." });
        }
        delete dataToProcess.page2.characterImageId;
    }

    // Resolve Campaign Notes Images
    if (dataToProcess.campaignNotes) {
        for (const note of dataToProcess.campaignNotes) {
            // Main Image
            if (note.imageId && note.imageId.startsWith('img_')) {
                try {
                    const blob = await getImage(note.imageId);
                    if (blob) {
                        (note as any).base64Cover = await blobToBase64(blob);
                    }
                } catch (e) {
                    ErrorService.handleError(e, { context: 'ExportCharacter', userMessage: `Impossible d'exporter l'image de couverture de la note ${note.id}` });
                }
                delete note.imageId;
            }

            // Gallery Images
            if (note.images && Array.isArray(note.images)) {
                for (const img of note.images) {
                    if (img.imageId) {
                        try {
                            const blob = await getImage(img.imageId);
                            if (blob) {
                                img.base64Data = await blobToBase64(blob);
                            }
                        } catch (e) {
                            ErrorService.handleError(e, { context: 'ExportCharacter', userMessage: `Impossible d'exporter l'image de la note ${img.id}` });
                        }
                        // Type assertion needed because imageId is required in runtime type but removed for export
                        delete (img as any).imageId;
                    }
                }
            }
        }
    }

    // --- PERSIST LOCAL SETTINGS ---
    const expertMode = localStorage.getItem('rpg-sheet-expert-mode') === 'true';
    const activeRulesId = localStorage.getItem('rules-source-id') || undefined;

    dataToProcess.syncInfo = {
        ...dataToProcess.syncInfo,
        localSettings: {
            expertMode,
            activeRulesId
        }
    };

    if (!(dataToProcess as any).appVersion) {
        (dataToProcess as any).appVersion = APP_VERSION;
    }

    // 2. Compression
    if (addLog) addLog("Compression des images en cours...", 'info', 'sheet');
    let finalData = dataToProcess;
    try {
        finalData = await ImageSyncResolver.resolveImagesForSync(dataToProcess) as CharacterSheetData;
        if (addLog) addLog("Images compress├®es avec succ├¿s.", 'success', 'sheet');
    } catch (e) {
        ErrorService.handleError(e, { context: 'ExportCharacter', silent: true });
        if (addLog) addLog("Avertissement : La compression des images a ├®chou├®, export brut utilis├®.", 'danger', 'sheet');
    }

    // 3. Trigger Download
    const now = new Date();
    const timestamp = `${String(now.getDate()).padStart(2, '0')}-${String(now.getMonth() + 1).padStart(2, '0')}-${now.getFullYear()}_${String(now.getHours()).padStart(2, '0')}h${String(now.getMinutes()).padStart(2, '0')}`;
    const filename = `${timestamp}_Personnage_${data.header.name || 'SansNom'}.json`;

    const blob = new Blob([JSON.stringify(finalData, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);

    if (addLog) addLog(`Sauvegarde de secours r├®ussie : ${filename}`, 'success', 'both');
};

/**
 * Interface pour la d├®tection de conflits entre donn├®es locales et import├®es.
 */
export interface DataConflict {
    type: 'skill' | 'trait' | 'specialization';
    key: string;
    name: string;
    current: LibrarySkillEntry | LibraryEntry | LibrarySpecializationEntry;
    incoming: LibrarySkillEntry | LibraryEntry | LibrarySpecializationEntry;
}

/**
 * Cr├®e un mod├¿le vierge (template) ├á partir d'une structure de donn├®es existante.
 * R├®initialise toutes les valeurs personnelles du personnage tout en conservant la structure.
 */
export const createTemplateFromData = (source: CharacterSheetData): CharacterSheetData => {
    const clean = JSON.parse(JSON.stringify(source));

    // Reset Header
    Object.keys(clean.header).forEach(k => clean.header[k as keyof typeof clean.header] = "");

    // Reset XP
    clean.experience = { gain: '0', spent: '0', rest: '0' };
    clean.xpLogs = [];
    clean.appLogs = [];

    // Reset Attributes Values
    if (clean.attributes) {
        Object.keys(clean.attributes).forEach(cat => {
            if (Array.isArray(clean.attributes[cat])) {
                clean.attributes[cat].forEach((attr: AttributeEntry) => {
                    attr.val1 = ""; attr.val2 = ""; attr.val3 = "";
                    attr.creationVal1 = 0; attr.creationVal2 = 0; attr.creationVal3 = 0;
                });
            }
        });
    }

    // Reset Skills Values
    Object.keys(clean.skills).forEach(cat => {
        const skillList = clean.skills[cat as keyof typeof clean.skills];
        if (Array.isArray(skillList)) {
            skillList.forEach((skill: DotEntry) => {
                skill.value = 0;
                skill.creationValue = 0;
                skill.current = 0;
            });
        }
    });

    // Reset Combat
    if (clean.combat && clean.combat.weapons) {
        clean.combat.weapons.forEach((w: CombatEntry) => { w.weapon = ""; w.level = ""; w.init = ""; w.attack = ""; w.damage = ""; w.parry = ""; });
    }
    if (clean.combat && clean.combat.armor) {
        clean.combat.armor.forEach((a: { type: string, protection: string, weight: string }) => { a.type = ""; a.protection = ""; a.weight = ""; });
    }
    clean.combat.stats = { agility: '', dexterity: '', force: '', size: '' };

    // Reset Page 2 Details
    clean.page2.lieux_importants = "";
    clean.page2.contacts = "";
    clean.page2.reputation.forEach((r: ReputationEntry) => { r.reputation = ''; r.lieu = ''; r.valeur = ''; });
    clean.page2.connaissances = "";
    clean.page2.valeurs_monetaires = "";
    clean.page2.armes_list = "";
    clean.page2.avantages.forEach((t: TraitEntry) => { t.name = ''; t.value = ''; });
    clean.page2.desavantages.forEach((t: TraitEntry) => { t.name = ''; t.value = ''; });
    clean.page2.equipement = "";
    clean.page2.notes = "";
    clean.page2.characterImage = "";
    clean.page2.characterImageId = undefined;

    // Reset Specializations
    clean.specializations = {};

    // Counters
    if (clean.counters) {
        if (clean.counters.volonte) { clean.counters.volonte.value = 3; clean.counters.volonte.current = 0; }
        if (clean.counters.confiance) { clean.counters.confiance.value = 3; clean.counters.confiance.current = 0; }
        if (clean.counters.custom) {
            clean.counters.custom.forEach((c: DotEntry) => { c.value = 0; c.current = 0; });
        }
    }

    // Reset Specializations Library
    clean.specializationLibrary = [];

    // Disable creation mode
    clean.creationConfig.active = false;

    return clean;
};

/**
 * D├®tecte les conflits entre les biblioth├¿ques locales et les donn├®es import├®es.
 */
export const detectConflicts = (
    currentSkills: LibrarySkillEntry[],
    incomingSkills: LibrarySkillEntry[],
    currentTraits: LibraryEntry[],
    incomingTraits: LibraryEntry[],
    currentSpecs: LibrarySpecializationEntry[] = [],
    incomingSpecs: LibrarySpecializationEntry[] = []
) => {
    const conflicts: DataConflict[] = [];

    // 1. Detect Skill Conflicts
    const currentSkillMap = new Map(currentSkills.map(s => [s.name.trim().toLowerCase(), s]));
    incomingSkills.forEach(newItem => {
        const normName = newItem.name.trim().toLowerCase();
        if (currentSkillMap.has(normName)) {
            const existingItem = currentSkillMap.get(normName)!;
            const desc1 = (existingItem.description || '').trim();
            const desc2 = (newItem.description || '').trim();

            if (desc1 !== desc2) {
                conflicts.push({
                    type: 'skill',
                    key: `skill_${normName}`,
                    name: existingItem.name,
                    current: existingItem,
                    incoming: newItem
                });
            }
        }
    });

    // 2. Detect Trait Conflicts
    const currentTraitMap = new Map(currentTraits.map(t => [t.name.trim().toLowerCase(), t]));
    incomingTraits.forEach(newItem => {
        const normName = newItem.name.trim().toLowerCase();
        if (currentTraitMap.has(normName)) {
            const existingItem = currentTraitMap.get(normName)!;

            const diffDesc = (existingItem.description || '').trim() !== (newItem.description || '').trim();
            const diffCost = existingItem.cost !== newItem.cost;
            const diffType = existingItem.type !== newItem.type;
            const diffEffects = JSON.stringify(existingItem.effects || []) !== JSON.stringify(newItem.effects || []);

            if (diffDesc || diffCost || diffType || diffEffects) {
                conflicts.push({
                    type: 'trait',
                    key: `trait_${normName}`,
                    name: existingItem.name,
                    current: existingItem,
                    incoming: newItem
                });
            }
        }
    });

    // 3. Detect Specialization Conflicts
    const currentSpecMap = new Map((currentSpecs || []).map(s => [s.name.trim().toLowerCase(), s]));
    (incomingSpecs || []).forEach(newItem => {
        const normName = newItem.name.trim().toLowerCase();
        if (currentSpecMap.has(normName)) {
            const existingItem = currentSpecMap.get(normName)!;

            const diffDesc = (existingItem.description || '').trim() !== (newItem.description || '').trim();
            const diffLevel = existingItem.defaultMinLevel !== newItem.defaultMinLevel;
            const diffSkills = JSON.stringify([...(existingItem.skillIds || [])].sort()) !==
                JSON.stringify([...(newItem.skillIds || [])].sort());

            if (diffDesc || diffLevel || diffSkills) {
                conflicts.push({
                    type: 'specialization',
                    key: `spec_${normName}`,
                    name: existingItem.name,
                    current: existingItem,
                    incoming: newItem
                });
            }
        }
    });

    return conflicts;
};

/**
 * Fusion intelligente de tableaux d'objets (traits ou comp├®tences).
 */
export const smartMerge = <T extends { name: string }>(
    current: T[],
    incoming: T[],
    resolutions: Record<string, 'keep_current' | 'replace'>,
    prefix: 'skill' | 'trait' | 'specialization'
) => {
    const finalMap = new Map<string, T>();

    // 1. Add all existing
    current.forEach(s => {
        finalMap.set(s.name.trim().toLowerCase(), s);
    });

    // 2. Process incoming
    incoming.forEach(newItem => {
        const normName = newItem.name.trim().toLowerCase();
        const resolutionKey = `${prefix}_${normName}`;

        if (finalMap.has(normName)) {
            const decision = resolutions[resolutionKey];
            if (decision === 'replace') {
                finalMap.set(normName, newItem);
            }
        } else {
            finalMap.set(normName, newItem);
        }
    });

    return Array.from(finalMap.values()).sort((a, b) => a.name.localeCompare(b.name));
};

import { LibraryEntry, LibrarySkillEntry } from '../types';

export type EntrySource = 'local' | 'official' | 'modified';

export interface MergedEntry<T> {
    entry: T;
    source: EntrySource;
    originalId: string; // The ID in the official library (if applicable)
}

import { normalizeString } from './stringUtils';

/**
 * Merges the local library with the official library.
 * - Local items always appear.
 * - Official items appear UNLESS they are already in the local library (by ID or Normalized Name).
 *   - If they are in local, it means the player "owns" it (modified or not).
 * 
 * Strategy:
 * 1. Start with ALL Local items (Source: 'local').
 * 2. Add Official items that are NOT in Local ID list AND NOT matching a Local Name (normalized).
 */
export const mergeLibraries = <T extends { id: string, name: string }>(
    localList: T[],
    officialList: T[]
): MergedEntry<T>[] => {
    const mergedMap = new Map<string, MergedEntry<T>>();
    const localNames = new Set<string>();
    const localIds = new Set<string>();

    // Pre-compute official IDs and names for fast lookup
    const officialIds = new Set<string>(officialList.map(o => o.id));
    const officialNames = new Set<string>(officialList.map(o => normalizeString(o.name)));

    // 1. Add all local items first (Priority)
    // If a local item has the same ID as an official one, it is marked 'official'
    // (it's a stale copy from a previous reconciler injection ÔÇö content stays, badge is corrected)
    localList.forEach(item => {
        const isAlsoOfficial = officialIds.has(item.id) || officialNames.has(normalizeString(item.name));
        mergedMap.set(item.id, {
            entry: item,
            source: isAlsoOfficial ? 'official' : 'local',
            originalId: item.id
        });
        localIds.add(item.id);
        if (item.name) {
            localNames.add(normalizeString(item.name));
        }
    });

    // 2. Add Official items if missing (check ID AND Name)
    officialList.forEach(item => {
        const normName = normalizeString(item.name);

        // Skip if ID exists in local
        if (localIds.has(item.id)) return;

        // Skip if Name exists in local (Deduplication by content)
        if (localNames.has(normName)) return;

        mergedMap.set(item.id, {
            entry: item,
            source: 'official',
            originalId: item.id
        });
    });

    // Return as array, sorted by name
    return Array.from(mergedMap.values()).sort((a, b) =>
        a.entry.name.localeCompare(b.entry.name)
    );
};

export const forceRulesReconciliation = (parsed: any): void => {
