        }));
    }

    // Remove "Valets / Dames / Rois"
    if (Array.isArray(parsed.counters.custom)) {
        parsed.counters.custom = parsed.counters.custom.filter((c: any) =>
            c && c.name !== "Valets / Dames / Rois"
        );
    }
};

