import { INITIAL_DATA } from '../../data/initialState';
import { LibrarySkillEntry } from '../../types';

/**
 * Map of legacy skill category IDs to generic IDs
 */
export const LEGACY_SKILL_MAP: Record<string, string> = {
    'talents': 'Col_Comp_1',
    'competences': 'Col_Comp_2',
    'competences_col_2': 'Col_Comp_3',
    'connaissances': 'Col_Comp_4',
    'autres_competences': 'Col_Comp_5',
    'competences2': 'Col_Comp_6',
    'autres': 'Col_Comp_7',
    'arrieres_plans': 'Col_Comp_8',
    'counters': 'Col_Comp_9'
};

/**
 * Required skill category IDs
 */
export const REQUIRED_SKILL_CATS = [
    'Col_Comp_1', 'Col_Comp_2', 'Col_Comp_3', 'Col_Comp_4',
    'Col_Comp_5', 'Col_Comp_6', 'Col_Comp_7', 'Col_Comp_8', 'Col_Comp_9'
];

/**
 * Migration: Skills
 * - Migrate legacy category IDs to generic IDs (Col_Comp_x) FIRST
 * - Initialize missing skill categories from INITIAL_DATA
 * - Add creationValue property to skills
 * - Fix variable skills using skillLibrary
 */
export const migrateSkills = (parsed: any): void => {
    // Initialize skills object
    if (!parsed.skills) {
        parsed.skills = {};
    }

    // STEP 1: Migrate legacy skill category keys FIRST (before adding defaults)
    // This renames the keys without merging
    Object.keys(LEGACY_SKILL_MAP).forEach(oldKey => {
        if (parsed.skills[oldKey]) {
            const newKey = LEGACY_SKILL_MAP[oldKey];
            // Only move if the new key doesn't exist - don't merge!
            if (!parsed.skills[newKey]) {
                parsed.skills[newKey] = parsed.skills[oldKey];
            }
            delete parsed.skills[oldKey];
        }
    });

    // STEP 2: Inject from INITIAL_DATA only for truly missing categories
    Object.keys(INITIAL_DATA.skills).forEach(key => {
        if (!parsed.skills[key]) {
            parsed.skills[key] = INITIAL_DATA.skills[key];
        }
    });

    // STEP 3: Ensure all required categories exist
    REQUIRED_SKILL_CATS.forEach(cat => {
        if (!parsed.skills[cat]) {
            parsed.skills[cat] = INITIAL_DATA.skills[cat] || [];
        }
    });

    // STEP 4: Ensure all skills have creationValue
    const ensureCreationValue = (list: any[]) => {
        return list.map(item => {
            if (typeof item.creationValue === 'undefined') {
                return { ...item, creationValue: 0 };
            }
            return item;
        });
    };

    Object.keys(parsed.skills).forEach(key => {
        if (Array.isArray(parsed.skills[key])) {
            parsed.skills[key] = ensureCreationValue(parsed.skills[key]);
        }
    });

    // STEP 5: Fix variable skills using skillLibrary as Source of Truth
    if (parsed.skills && parsed.skillLibrary) {
        const variableSkillNames = new Set<string>();
        parsed.skillLibrary.forEach((s: LibrarySkillEntry) => {
            if (s.isVariable) {
                variableSkillNames.add(s.name.trim().toLowerCase());
            }
        });

        Object.keys(parsed.skills).forEach(key => {
            if (Array.isArray(parsed.skills[key])) {
                parsed.skills[key] = parsed.skills[key].map((skill: any) => {
                    if (!skill || !skill.name) return skill;
                    const normalized = skill.name.trim().toLowerCase();
                    if (variableSkillNames.has(normalized) && typeof skill.variant === 'undefined') {
                        return { ...skill, variant: "" };
                    }
                    return skill;
                });
            }
        });
    }
};

/**
 * Migration: Specializations
 * - Initialize specializations object
 * - Convert string specializations to objects with minLevel
 * - Build specializationLibrary from existing data
 */
export const migrateSpecializations = (parsed: any): void => {
    // Initialize specializations
    if (!parsed.specializations) {
        parsed.specializations = {};
    }

    // Convert string array to object array in imposedSpecializations
    if (parsed.imposedSpecializations) {
        Object.keys(parsed.imposedSpecializations).forEach(skillId => {
            const list = parsed.imposedSpecializations[skillId];
            if (Array.isArray(list) && list.length > 0 && typeof list[0] === 'string') {
                parsed.imposedSpecializations[skillId] = list.map((s: string) => ({
                    name: s,
                    minLevel: 0
                }));
            }
        });
    }

    // Build specializationLibrary from existing data
    if (!parsed.specializationLibrary) {
        parsed.specializationLibrary = [];
        const initialSpecList: any[] = [];
        const seenSpecNames = new Set<string>();

        // 1. Harvest from specializations Record
        if (parsed.specializations) {
            Object.keys(parsed.specializations).forEach(skillId => {
                const specs = parsed.specializations[skillId];
                if (Array.isArray(specs)) {
                    specs.forEach(s => {
                        if (s && s.trim() !== '') {
                            const normalized = s.trim().toLowerCase();
                            if (!seenSpecNames.has(normalized)) {
                                seenSpecNames.add(normalized);
                                initialSpecList.push({
                                    id: Math.random().toString(36).substr(2, 9),
                                    name: s.trim(),
                                    skillIds: [skillId],
                                    defaultMinLevel: 0,
                                    description: ""
                                });
                            } else {
                                const existing = initialSpecList.find(e => e.name.trim().toLowerCase() === normalized);
                                if (existing && !existing.skillIds.includes(skillId)) {
                                    existing.skillIds.push(skillId);
                                }
                            }
                        }
                    });
                }
            });
        }

        // 2. Harvest from imposedSpecializations
        if (parsed.imposedSpecializations) {
            Object.keys(parsed.imposedSpecializations).forEach(skillId => {
                const specs = parsed.imposedSpecializations[skillId];
                if (Array.isArray(specs)) {
                    specs.forEach(s => {
                        const name = typeof s === 'string' ? s : s.name;
                        if (name && name.trim() !== '') {
                            const normalized = name.trim().toLowerCase();
                            if (!seenSpecNames.has(normalized)) {
                                seenSpecNames.add(normalized);
                                initialSpecList.push({
                                    id: Math.random().toString(36).substr(2, 9),
                                    name: name.trim(),
                                    skillIds: [skillId],
                                    defaultMinLevel: typeof s === 'object' ? (s.minLevel || 0) : 0,
                                    description: ""
                                });
                            } else {
                                const existing = initialSpecList.find(e => e.name.trim().toLowerCase() === normalized);
                                if (existing && !existing.skillIds.includes(skillId)) {
                                    existing.skillIds.push(skillId);
                                }
                            }
                        }
                    });
                }
            });
        }

        initialSpecList.sort((a, b) => a.name.localeCompare(b.name));
        parsed.specializationLibrary = initialSpecList;
    }
};

/**
 * Migration: Terminology renaming
 * - vertus ÔåÆ avantages
 * - defauts ÔåÆ desavantages
 */
export const migrateTerminology = (parsed: any): void => {
    if (!parsed.page2) return;

    if (parsed.page2.vertus && !parsed.page2.avantages) {
        parsed.page2.avantages = parsed.page2.vertus;
        delete parsed.page2.vertus;
    }
    if (parsed.page2.defauts && !parsed.page2.desavantages) {
        parsed.page2.desavantages = parsed.page2.defauts;
        delete parsed.page2.defauts;
    }
};

import { LibraryEntry, TraitEffect } from '../../types';

export interface TraitMigrationInfo {
    id: string;
    name: string;
    changes: string[];
}

export interface LibraryMigrationResult {
    traits: LibraryEntry[];
    stats: {
        traitsMigrated: number;
        details: TraitMigrationInfo[];
    };
}

/**
 * Migre les propri├®t├®s h├®rit├®es (legacy effects) vers les nouvelles propri├®t├®s directes du trait.
 * Retourne le trait (migr├® ou non) et la liste des changements effectu├®s.
 */
export function migrateTraitProperties(trait: LibraryEntry): { trait: LibraryEntry, changes: string[] } {
    const effects = [...(trait.effects || [])];
    const changes: string[] = [];

    // Initialiser avec les valeurs existantes ou d├®fauts
    let hasAutoCounter = trait.hasAutoCounter || false;
    let autoCounterName = trait.autoCounterName;
    let isXPUpgradeable = trait.isXPUpgradeable || false;

    let hasChanges = false;

    // Parcourir les effets ├á l'envers pour pouvoir les supprimer
    for (let i = effects.length - 1; i >= 0; i--) {
        const effect = effects[i] as TraitEffect;

        if (effect.type === 'auto_counter') {
            hasAutoCounter = true;
            if (!autoCounterName) {
                autoCounterName = effect.target || (effect as any).associatedCounterId;
            }
            effects.splice(i, 1);
            hasChanges = true;
            changes.push(`Compteur Auto -> Propri├®t├® (Nom: ${autoCounterName || 'Par d├®faut'})`);
        } else if (effect.type === 'xp_upgradeable') {
            isXPUpgradeable = true;
            effects.splice(i, 1);
            hasChanges = true;
            changes.push('├ëligibilit├® XP -> Propri├®t├®');
        }
    }

    if (!hasChanges) return { trait, changes: [] };

    return {
        trait: {
            ...trait,
            hasAutoCounter,
            autoCounterName,
            isXPUpgradeable,
            effects: effects as any
        },
        changes
    };
}

/**
 * Migre une liste compl├¿te de traits et retourne les statistiques d├®taill├®es.
 */
export function migrateTraitLibrary(traits: LibraryEntry[]): LibraryMigrationResult {
    const details: TraitMigrationInfo[] = [];
    const updatedTraits = traits.map(t => {
        const { trait: migrated, changes } = migrateTraitProperties(t);
        if (changes.length > 0) {
            details.push({
                id: migrated.id,
                name: migrated.name,
                changes
            });
        }
        return migrated;
    });

    return {
        traits: updatedTraits,
        stats: {
            traitsMigrated: details.length,
            details
        }
    };
}

/**
 * Migration: Traits structure
 * - string[] ÔåÆ object[] for avantages/desavantages
 * - Padding to 28 elements
 */
export const migrateTraits = (parsed: any): void => {
    if (!parsed.page2) return;

    // Convert string[] to object[]
    if (parsed.page2.avantages && parsed.page2.avantages.length > 0 && typeof parsed.page2.avantages[0] === 'string') {
        parsed.page2.avantages = parsed.page2.avantages.map((s: string) => ({ name: s || '', value: '' }));
    }
    if (parsed.page2.desavantages && parsed.page2.desavantages.length > 0 && typeof parsed.page2.desavantages[0] === 'string') {
        parsed.page2.desavantages = parsed.page2.desavantages.map((s: string) => ({ name: s || '', value: '' }));
    }

    // Padding to 28 elements
    if (parsed.page2.avantages && parsed.page2.avantages.length < 28) {
        const diff = 28 - parsed.page2.avantages.length;
        parsed.page2.avantages = [...parsed.page2.avantages, ...Array(diff).fill(null).map(() => ({ name: '', value: '' }))];
    } else if (!parsed.page2.avantages) {
        parsed.page2.avantages = Array(28).fill(null).map(() => ({ name: '', value: '' }));
    }

    if (parsed.page2.desavantages && parsed.page2.desavantages.length < 28) {
        const diff = 28 - parsed.page2.desavantages.length;
        parsed.page2.desavantages = [...parsed.page2.desavantages, ...Array(diff).fill(null).map(() => ({ name: '', value: '' }))];
    } else if (!parsed.page2.desavantages) {
        parsed.page2.desavantages = Array(28).fill(null).map(() => ({ name: '', value: '' }));
    }
};

